/* Shared quiz question bank. */
window.questionBank = [
            { id: "programming-1", category: "programming", difficulty: "easy", question: "Apa fungsi variabel dalam program?", answers: ["Menyimpan nilai yang bisa digunakan ulang", "Menghapus error otomatis", "Mengubah desain database", "Menjalankan internet"], correct: 0, hint: "Bayangkan kotak bernama yang berisi data.", explanation: "Variabel dipakai untuk menyimpan nilai, lalu nilai itu dapat dibaca atau diubah selama program berjalan." },
            { id: "programming-2", category: "programming", difficulty: "easy", question: "Apa arti tipe data boolean?", answers: ["Nilai benar atau salah", "Daftar gambar", "Koneksi server", "Ukuran layar"], correct: 0, hint: "Biasanya bernilai true atau false.", explanation: "Boolean digunakan untuk kondisi logika seperti valid atau tidak valid, aktif atau tidak aktif." },
            { id: "programming-3", category: "programming", difficulty: "easy", question: "Mengapa komentar kode sebaiknya dipakai seperlunya?", answers: ["Agar menjelaskan bagian yang tidak langsung jelas tanpa membuat kode bising", "Agar semua baris kode menjadi hijau", "Agar program selalu lebih cepat", "Agar tidak perlu testing"], correct: 0, hint: "Komentar bagus membantu pembaca, bukan mengganti kode yang jelas.", explanation: "Komentar paling berguna untuk menjelaskan alasan atau konteks, bukan mengulang hal yang sudah jelas dari kode." },
            { id: "programming-4", category: "programming", difficulty: "easy", question: "Apa tujuan dasar conditional statement seperti if?", answers: ["Menjalankan kode tertentu hanya saat kondisi terpenuhi", "Menyimpan file gambar", "Membuat database baru", "Menghapus semua bug"], correct: 0, hint: "Pikirkan percabangan keputusan.", explanation: "Conditional statement membuat program dapat memilih alur berdasarkan kondisi tertentu." },
            { id: "programming-5", category: "programming", difficulty: "medium", question: "Kapan loop paling tepat digunakan?", answers: ["Saat perlu mengulang instruksi dengan pola tertentu", "Saat ingin membuat warna tombol", "Saat membuat nama file", "Saat menutup browser"], correct: 0, hint: "Cari kebutuhan yang terjadi berkali-kali.", explanation: "Loop membantu menjalankan blok kode berulang kali sampai kondisi tertentu terpenuhi." },
            { id: "programming-6", category: "programming", difficulty: "medium", question: "Apa manfaat memecah kode menjadi function kecil?", answers: ["Kode lebih mudah diuji, dibaca, dan digunakan ulang", "Kode selalu lebih cepat tanpa pengecualian", "Program tidak perlu data", "Semua bug langsung hilang"], correct: 0, hint: "Pikirkan maintainability.", explanation: "Function kecil membuat tanggung jawab kode lebih jelas sehingga mudah diuji, dirawat, dan dipakai ulang." },
            { id: "programming-7", category: "programming", difficulty: "medium", question: "Apa yang biasanya dilakukan proses debugging?", answers: ["Menemukan penyebab error dan memperbaiki perilaku program", "Mengubah semua teks menjadi kapital", "Menghapus dokumentasi", "Membuat logo aplikasi"], correct: 0, hint: "Debugging mencari akar masalah.", explanation: "Debugging bukan hanya menebak perbaikan, tetapi melacak data, alur, dan kondisi yang membuat program gagal." },
            { id: "programming-8", category: "programming", difficulty: "hard", question: "Mengapa asynchronous programming penting pada aplikasi modern?", answers: ["Agar operasi lambat seperti network tidak memblokir alur utama", "Agar semua kode berjalan tanpa urutan", "Agar database tidak dibutuhkan", "Agar CSS bisa dihapus"], correct: 0, hint: "Network request bisa lama.", explanation: "Async membantu aplikasi tetap responsif saat menunggu operasi I/O seperti fetch API, file, atau database." },
            { id: "programming-9", category: "programming", difficulty: "hard", question: "Apa risiko utama global state yang tidak terkendali?", answers: ["Perubahan dari banyak tempat sulit dilacak dan memicu bug tersembunyi", "Semua variabel menjadi lebih aman", "UI otomatis responsif", "Testing menjadi tidak perlu"], correct: 0, hint: "Semakin banyak tempat bisa mengubah state, semakin sulit dilacak.", explanation: "Global state perlu dibatasi atau dikelola jelas agar perubahan data tidak menimbulkan efek samping yang sulit diprediksi." },
            { id: "programming-10", category: "programming", difficulty: "hard", question: "Apa prinsip utama clean code?", answers: ["Kode mudah dipahami, bernama jelas, dan punya tanggung jawab terarah", "Kode harus selalu paling pendek", "Kode harus tanpa function", "Kode harus menyembunyikan semua maksudnya"], correct: 0, hint: "Pembaca kode adalah target utama.", explanation: "Clean code memprioritaskan kejelasan, struktur, nama yang bermakna, dan desain yang mudah dirawat." },
            { id: "programming-11", category: "programming", difficulty: "easy", question: "Apa output dari ekspresi 5 + '5' dalam JavaScript?", answers: ["'55'", "'10'", "Error", "NaN"], correct: 0, hint: "JavaScript akan melakukan konversi tipe data otomatis (coercion).", explanation: "Operator + pada string dan number akan mengakibatkan number dikoersi menjadi string, lalu digabungkan (concatenated)." },
            { id: "programming-12", category: "programming", difficulty: "easy", question: "Di bawah ini yang merupakan struktur data dengan prinsip FIFO (First In First Out) adalah?", answers: ["Queue (Antrean)", "Stack (Tumpukan)", "Array", "Tree"], correct: 0, hint: "Seperti antrean bioskop.", explanation: "Queue (antrean) memproses data yang pertama kali masuk terlebih dahulu, sedangkan Stack menggunakan prinsip LIFO (Last In First Out)." },
            { id: "programming-13", category: "programming", difficulty: "medium", question: "Apa perbedaan utama antara compiler dan interpreter?", answers: ["Compiler menerjemahkan seluruh kode sekaligus, Interpreter menerjemahkan baris demi baris", "Compiler hanya untuk bahasa C, sedangkan interpreter hanya untuk Python", "Compiler tidak menghasilkan file output, interpreter menghasilkan file exe", "Interpreter membuat program berjalan jauh lebih cepat daripada compiler"], correct: 0, hint: "Pikirkan waktu penerjemahan kode.", explanation: "Compiler menerjemahkan seluruh source code menjadi machine code sebelum dijalankan, sedangkan interpreter menerjemahkan dan mengeksekusi instruksi baris demi baris saat program berjalan." },
            { id: "programming-14", category: "programming", difficulty: "medium", question: "Dalam paradigma Object-Oriented Programming (OOP), apa yang dimaksud dengan Inheritance?", answers: ["Kemampuan suatu class untuk mewarisi sifat dan metode dari class lain", "Kemampuan menyembunyikan detail implementasi internal", "Kemampuan membuat objek tanpa class", "Kemampuan mengubah tipe data variabel secara dinamis"], correct: 0, hint: "Konsep pewarisan dalam keluarga.", explanation: "Inheritance (pewarisan) memungkinkan sebuah subclass mewarisi attribute and method dari superclass, mendukung reusability kode." },
            { id: "programming-15", category: "programming", difficulty: "medium", question: "Apakah fungsi dari Git dalam pengembangan perangkat lunak?", answers: ["Melacak perubahan pada kode sumber dan memfasilitasi kolaborasi tim", "Mengompilasi kode program menjadi aplikasi", "Menyimpan data user secara online", "Memperbaiki bug secara otomatis menggunakan AI"], correct: 0, hint: "Berhubungan dengan version control.", explanation: "Git adalah distributed version control system yang mencatat riwayat perubahan file kode dan membantu developer bekerja bersama pada project yang sama." },
            { id: "programming-16", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Time Complexity' dalam analisis algoritma?", answers: ["Representasi jumlah waktu atau langkah yang dibutuhkan algoritma untuk berjalan seiring bertambahnya ukuran input", "Lama waktu yang dibutuhkan developer untuk menulis kode program", "Waktu yang diperlukan CPU untuk melakukan restart", "Kecepatan internet saat mengunduh dependency library"], correct: 0, hint: "Pikirkan performa kode terhadap ukuran data (N).", explanation: "Time complexity (biasanya diukur dengan Big O notation) mengukur bagaimana jumlah operasi/waktu eksekusi suatu algoritma bertumbuh seiring bertambahnya ukuran input data." },
            { id: "programming-17", category: "programming", difficulty: "hard", question: "Manakah penjelasan terbaik mengenai rekursi (recursion) dalam pemrograman?", answers: ["Sebuah fungsi yang memanggil dirinya sendiri sampai mencapai base case", "Sebuah loop yang berjalan tanpa henti (infinite loop)", "Metode untuk mengamankan data rahasia user", "Cara untuk menggabungkan dua file database"], correct: 0, hint: "Memanggil diri sendiri.", explanation: "Rekursi adalah teknik pemrograman di mana sebuah fungsi memanggil dirinya sendiri untuk memecahkan sub-masalah yang lebih kecil, dengan base case sebagai batas berhenti." },
            { id: "programming-18", category: "programming", difficulty: "easy", question: "Mana yang merupakan contoh nama variabel yang valid menurut konvensi camelCase?", answers: ["totalHargaBarang", "total-harga-barang", "TotalHargaBarang", "total_harga_barang"], correct: 0, hint: "Kata pertama huruf kecil, kata berikutnya berawalan huruf besar.", explanation: "Konvensi camelCase diawali dengan huruf kecil, dan huruf pertama kata berikutnya ditulis dengan huruf besar tanpa spasi atau karakter khusus." },
            { id: "programming-19", category: "programming", difficulty: "medium", question: "Dalam OOP, apa arti dari Polymorphism?", answers: ["Satu antarmuka atau metode yang dapat memiliki banyak bentuk tindakan yang berbeda", "Kemampuan membuat objek menjadi tidak dapat diubah (immutable)", "Proses enkripsi data sebelum disimpan", "Membagi program menjadi beberapa server"], correct: 0, hint: "Poly berarti banyak, morph berarti bentuk.", explanation: "Polymorphism memungkinkan objek dari kelas-kelas berbeda merespons pesan atau metode yang sama dengan cara yang sesuai dengan spesifik kelas masing-masing." },
            { id: "programming-20", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Memory Leak'?", answers: ["Kondisi di mana memori yang dialokasikan tidak dibebaskan kembali meskipun sudah tidak digunakan", "Kerusakan fisik pada modul RAM di komputer", "Pencurian data memori oleh hacker pihak ketiga", "Proses pembersihan cache browser secara otomatis"], correct: 0, hint: "Memori terbuang sia-sia dan terus berkurang.", explanation: "Memory leak terjadi saat program mengalokasikan memori dinamis di RAM tetapi gagal membebaskannya (deallocation) setelah selesai digunakan, yang lama-kelamaan dapat menghabiskan memori sistem." },

            { id: "database-1", category: "database", difficulty: "easy", question: "Apa fungsi utama primary key dalam tabel database?", answers: ["Mengidentifikasi setiap baris secara unik", "Menghapus tabel", "Mengubah warna kolom", "Membuat animasi data"], correct: 0, hint: "Satu baris, satu identitas.", explanation: "Primary key memastikan setiap record memiliki identitas unik agar mudah direferensikan." },
            { id: "database-2", category: "database", difficulty: "easy", question: "Apa itu record dalam database relasional?", answers: ["Satu baris data dalam tabel", "Satu warna tombol", "Satu folder gambar", "Satu jenis animasi"], correct: 0, hint: "Tabel punya kolom dan baris.", explanation: "Record adalah satu baris yang berisi nilai untuk kolom-kolom dalam sebuah tabel." },
            { id: "database-3", category: "database", difficulty: "easy", question: "Perintah SQL SELECT digunakan untuk apa?", answers: ["Mengambil data dari tabel", "Menghapus aplikasi", "Mengubah ukuran layar", "Membuat ikon"], correct: 0, hint: "SELECT berkaitan dengan membaca data.", explanation: "SELECT digunakan untuk membaca data dari satu atau lebih tabel sesuai kolom dan filter yang dibutuhkan." },
            { id: "database-4", category: "database", difficulty: "easy", question: "Apa fungsi klausa WHERE dalam SQL?", answers: ["Menyaring baris berdasarkan kondisi", "Membuat tabel selalu kosong", "Mengganti nama database", "Mengurutkan warna UI"], correct: 0, hint: "WHERE adalah filter.", explanation: "WHERE membatasi hasil query hanya pada baris yang memenuhi kondisi tertentu." },
            { id: "database-5", category: "database", difficulty: "medium", question: "JOIN dalam SQL digunakan untuk apa?", answers: ["Menggabungkan data dari beberapa tabel yang saling berelasi", "Mengompres gambar", "Mengubah font", "Mengunci laptop"], correct: 0, hint: "Relasi antar tabel adalah kata kuncinya.", explanation: "JOIN menghubungkan tabel berdasarkan kolom terkait sehingga data bisa dibaca dalam satu hasil query." },
            { id: "database-6", category: "database", difficulty: "medium", question: "Apa tujuan normalisasi database?", answers: ["Mengurangi duplikasi dan menjaga konsistensi data", "Membuat semua tabel menjadi satu kolom", "Menghapus kebutuhan query", "Membuat UI lebih berwarna"], correct: 0, hint: "Normalisasi menata struktur data.", explanation: "Normalisasi memecah data ke struktur yang lebih tepat agar redundansi turun dan update lebih aman." },
            { id: "database-7", category: "database", difficulty: "medium", question: "Apa manfaat transaction dalam database?", answers: ["Menjaga beberapa operasi berhasil semua atau batal semua", "Membuat query selalu cepat", "Mengubah SQL menjadi HTML", "Menghapus kebutuhan backup"], correct: 0, hint: "Pikirkan atomicity.", explanation: "Transaction menjaga integritas data saat beberapa operasi harus dianggap sebagai satu kesatuan." },
            { id: "database-8", category: "database", difficulty: "hard", question: "Mengapa index database perlu dipakai dengan bijak?", answers: ["Index mempercepat baca, tetapi bisa menambah beban tulis dan storage", "Index selalu membuat semua query sempurna", "Index mengganti kebutuhan primary key", "Index hanya untuk desain UI"], correct: 0, hint: "Ada tradeoff antara read dan write.", explanation: "Index dapat mempercepat pencarian, tetapi terlalu banyak index memperlambat insert/update dan memakai ruang tambahan." },
            { id: "database-9", category: "database", difficulty: "hard", question: "Apa penyebab umum query menjadi lambat pada tabel besar?", answers: ["Filter tidak memanfaatkan index dan membaca terlalu banyak baris", "Nama tabel terlalu pendek", "Terlalu banyak komentar CSS", "Tombol submit berwarna biru"], correct: 0, hint: "Perhatikan jumlah baris yang discan.", explanation: "Query lambat sering terjadi karena full scan, join tidak efisien, atau index yang tidak cocok dengan pola filter." },
            { id: "database-10", category: "database", difficulty: "hard", question: "Apa risiko menyimpan data turunan tanpa strategi sinkronisasi?", answers: ["Nilainya bisa tidak konsisten dengan sumber data utama", "Database menjadi tidak bisa dibaca", "Semua query gagal otomatis", "Primary key berubah menjadi string"], correct: 0, hint: "Data yang sama di dua tempat harus dijaga.", explanation: "Denormalisasi bisa berguna untuk performa, tetapi perlu strategi agar data turunan tetap selaras." },
            { id: "database-11", category: "database", difficulty: "easy", question: "Apakah kegunaan utama dari SQL FOREIGN KEY?", answers: ["Menghubungkan baris di satu tabel dengan baris di tabel lainnya", "Membuat tabel baru secara otomatis", "Mengubah tipe data kolom menjadi string", "Menghapus database cadangan"], correct: 0, hint: "Berhubungan dengan relasi antar tabel.", explanation: "Foreign Key adalah kolom yang merujuk ke Primary Key di tabel lain, menjaga integritas referensial antara kedua tabel tersebut." },
            { id: "database-12", category: "database", difficulty: "easy", question: "Apakah kepanjangan dari SQL?", answers: ["Structured Query Language", "Simple Queue List", "System Query Locator", "Sequential Query Log"], correct: 0, hint: "Bahasa terstruktur untuk database.", explanation: "SQL singkatan dari Structured Query Language, bahasa standar untuk memanipulasi dan mengambil data dari database relasional." },
            { id: "database-13", category: "database", difficulty: "medium", question: "Manakah di bawah ini yang merupakan ciri utama database NoSQL (non-relasional) dibanding SQL?", answers: ["Skema data fleksibel atau tanpa skema tetap, mendukung skalabilitas horizontal", "Hanya bisa dijalankan di sistem operasi Linux", "Tidak mendukung penyimpanan data teks", "Selalu menggunakan tabel dengan baris dan kolom yang kaku"], correct: 0, hint: "Pikirkan format dokumen atau key-value yang fleksibel.", explanation: "NoSQL didesain untuk menangani data tidak terstruktur atau semi-terstruktur dengan skema fleksibel dan biasanya lebih mudah diskalakan secara horizontal (menambah server)." },
            { id: "database-14", category: "database", difficulty: "medium", question: "Apakah fungsi dari klausa GROUP BY dalam query SQL?", answers: ["Mengelompokkan baris yang memiliki nilai sama ke dalam baris ringkasan", "Mengurutkan data dari nilai terbesar ke terkecil", "Membatasi jumlah data yang ditampilkan di layar", "Menggabungkan dua tabel tanpa relasi"], correct: 0, hint: "Sering digunakan bersama fungsi agregasi seperti COUNT, SUM, atau AVG.", explanation: "GROUP BY digunakan bersama fungsi agregasi untuk mengelompokkan baris data berdasarkan satu atau beberapa kolom untuk menghasilkan ringkasan data." },
            { id: "database-15", category: "database", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Database Transaction'?", answers: ["Satu unit kerja logis yang berisi satu atau beberapa operasi SQL yang harus sukses semua atau gagal semua", "Proses transfer data database antar perusahaan", "Biaya sewa layanan cloud database per bulan", "Proses ekspor data ke format file Excel"], correct: 0, hint: "Pikirkan konsep 'All or Nothing'.", explanation: "Transaction mengelompokkan beberapa operasi database sehingga jika salah satu gagal, seluruh perubahan dibatalkan (rollback) untuk menjaga konsistensi data." },
            { id: "database-16", category: "database", difficulty: "hard", question: "Apakah kepanjangan dari ACID dalam prinsip database relasional?", answers: ["Atomicity, Consistency, Isolation, Durability", "Access, Control, Index, Data", "Accuracy, Cloud, Integration, Delivery", "Authentication, Cipher, Integrity, Decentralization"], correct: 0, hint: "Menjamin transaksi database yang andal.", explanation: "ACID adalah standar transaksi database: Atomicity (semua atau tidak sama sekali), Consistency (validitas data), Isolation (transaksi tidak saling mengganggu), dan Durability (data permanen setelah commit)." },
            { id: "database-17", category: "database", difficulty: "hard", question: "Dalam indexing database relasional, manakah struktur data yang paling umum digunakan?", answers: ["B-Tree atau B+ Tree", "Stack", "Queue", "Linked List"], correct: 0, hint: "Struktur pohon yang seimbang untuk pencarian cepat.", explanation: "B-Tree/B+ Tree digunakan karena mempertahankan data terurut dan memungkinkan pencarian, akses berurutan, penyisipan, dan penghapusan dalam waktu logaritmik." },
            { id: "database-18", category: "database", difficulty: "easy", question: "Klausa SQL ORDER BY digunakan untuk apa?", answers: ["Mengurutkan hasil query berdasarkan kolom tertentu secara ascending atau descending", "Membatasi baris data yang diambil", "Menghitung jumlah baris data", "Menghapus data duplikat"], correct: 0, hint: "Berkaitan dengan urutan alfabet atau angka.", explanation: "ORDER BY digunakan untuk mengurutkan hasil query, baik secara terkecil-terbesar (ASC) maupun terbesar-terkecil (DESC)." },
            { id: "database-19", category: "database", difficulty: "medium", question: "Manakah database berikut yang termasuk kategori NoSQL Document-Oriented?", answers: ["MongoDB", "MySQL", "PostgreSQL", "SQLite"], correct: 0, hint: "Menggunakan format JSON/BSON untuk menyimpan data.", explanation: "MongoDB menyimpan data dalam dokumen fleksibel mirip JSON, menjadikannya salah satu database NoSQL Document-Oriented terpopuler." },
            { id: "database-20", category: "database", difficulty: "hard", question: "Apa tujuan dari replikasi database (Database Replication)?", answers: ["Menyalin data ke server database lain untuk redundansi, high availability, dan pembagian beban baca", "Menghapus duplikasi data di satu tabel", "Mengubah database relasional menjadi NoSQL", "Meningkatkan kecepatan query write dengan membagi satu baris data"], correct: 0, hint: "Pikirkan backup aktif dan pembagian beban kerja.", explanation: "Replikasi database menyalin data secara real-time ke satu atau lebih server replika untuk memastikan jika server utama mati, aplikasi tetap bisa berjalan (failover)." },

            { id: "design-1", category: "design", difficulty: "easy", question: "Apa tujuan utama wireframe?", answers: ["Menyusun struktur dan alur layar sebelum desain visual detail", "Menghitung pajak aplikasi", "Membuat database production", "Menghapus semua teks"], correct: 0, hint: "Ini tahap rangka awal.", explanation: "Wireframe membantu tim melihat struktur, hirarki, dan alur sebelum masuk ke visual final." },
            { id: "design-2", category: "design", difficulty: "easy", question: "Apa arti visual hierarchy dalam UI?", answers: ["Pengaturan elemen agar pengguna tahu mana yang paling penting", "Daftar warna acak", "Teknik backup database", "Cara mematikan animasi"], correct: 0, hint: "Hierarchy membantu perhatian pengguna.", explanation: "Visual hierarchy memakai ukuran, warna, jarak, dan kontras untuk mengarahkan perhatian." },
            { id: "design-3", category: "design", difficulty: "easy", question: "Mengapa tombol utama biasanya dibuat lebih menonjol?", answers: ["Agar aksi prioritas mudah ditemukan", "Agar semua elemen sama penting", "Agar halaman lebih berat", "Agar teks hilang"], correct: 0, hint: "Primary action perlu jelas.", explanation: "Tombol utama menuntun pengguna ke aksi paling penting dalam konteks layar tersebut." },
            { id: "design-4", category: "design", difficulty: "easy", question: "Apa fungsi spacing dalam layout?", answers: ["Memberi jarak agar informasi mudah dipindai dan tidak terasa sesak", "Mengganti semua ikon", "Membuat server cepat", "Menyimpan password"], correct: 0, hint: "Ruang kosong juga bagian desain.", explanation: "Spacing membantu pengelompokan, keterbacaan, dan ritme visual dalam antarmuka itu." },
            { id: "design-5", category: "design", difficulty: "medium", question: "Apa manfaat usability testing?", answers: ["Menemukan masalah penggunaan dari perilaku pengguna nyata", "Membuat logo otomatis", "Mengganti server", "Memperbesar semua tombol tanpa alasan"], correct: 0, hint: "Uji dengan manusia, bukan asumsi saja.", explanation: "Usability testing memperlihatkan titik bingung, hambatan, dan kebutuhan pengguna saat memakai produk." },
            { id: "design-6", category: "design", difficulty: "medium", question: "Mengapa aksesibilitas penting dalam produk digital?", answers: ["Agar lebih banyak orang bisa memakai produk dengan nyaman", "Agar warna selalu hitam putih", "Agar aplikasi hanya bisa dibuka admin", "Agar tidak perlu desain responsif"], correct: 0, hint: "Tidak semua pengguna memakai perangkat dengan cara yang sama.", explanation: "Aksesibilitas mempertimbangkan kontras, keyboard, screen reader, ukuran teks, dan kebutuhan pengguna yang beragam." },
            { id: "design-7", category: "design", difficulty: "medium", question: "Apa contoh microcopy yang baik?", answers: ["Teks singkat yang menjelaskan aksi atau status dengan jelas", "Paragraf panjang di semua tombol", "Nama variabel database", "Kode CSS untuk shadow"], correct: 0, hint: "Microcopy membantu pengguna memahami apa yang terjadi.", explanation: "Microcopy seperti label tombol, pesan error, dan helper text harus ringkas, jelas, dan sesuai konteks." },
            { id: "design-8", category: "design", difficulty: "hard", question: "Design system yang baik biasanya membantu apa?", answers: ["Konsistensi UI, kecepatan produksi, dan kualitas kolaborasi", "Menghapus kebutuhan riset", "Membuat semua halaman identik total", "Mengganti semua developer"], correct: 0, hint: "Komponen dan aturan yang bisa dipakai bersama.", explanation: "Design system menyediakan komponen, token, dan pedoman agar desain lebih konsisten dan tim lebih efisien." },
            { id: "design-9", category: "design", difficulty: "hard", question: "Mengapa kontras warna harus diuji, bukan hanya dilihat sekilas?", answers: ["Persepsi warna berbeda dan standar aksesibilitas butuh rasio yang cukup", "Karena semua warna pasti gagal", "Karena kontras hanya untuk gambar", "Karena browser tidak mendukung warna"], correct: 0, hint: "Kontras memengaruhi keterbacaan.", explanation: "Uji kontras membantu memastikan teks dapat dibaca oleh pengguna dengan kondisi visual dan perangkat yang berbeda." },
            { id: "design-10", category: "design", difficulty: "hard", question: "Apa risiko membuat UI terlalu dekoratif pada tool produktivitas?", answers: ["Workflow inti bisa lambat dipindai dan aksi penting tenggelam", "Semua pengguna pasti lebih cepat", "Data menjadi lebih akurat", "Backend otomatis aman"], correct: 0, hint: "Tool kerja butuh kejelasan dan efisiensi.", explanation: "Dekorasi yang berlebihan dapat mengganggu pemindaian, prioritas aksi, dan fokus pengguna." },
            { id: "design-11", category: "design", difficulty: "easy", question: "Apakah kegunaan utama dari Figma dalam alur kerja UI/UX?", answers: ["Membuat desain antarmuka, komponen interaktif, dan kolaborasi tim secara real-time", "Menulis kode backend Node.js", "Menguji performa database SQL", "Membuat server host lokal"], correct: 0, hint: "Tool desain berbasis web terpopuler saat ini.", explanation: "Figma adalah aplikasi desain grafis vektor dan prototyping yang berfokus pada kolaborasi real-time untuk tim UI/UX." },
            { id: "design-12", category: "design", difficulty: "easy", question: "Apakah warna merah dalam desain UI paling sering digunakan untuk melambangkan?", answers: ["Aksi berbahaya, error, atau pembatalan (destructive action)", "Status sukses atau penyelesaian tugas", "Warna latar belakang default mode malam", "Tombol navigasi menu utama"], correct: 0, hint: "Pikirkan sinyal bahaya atau peringatan.", explanation: "Merah secara psikologis menarik perhatian kuat dan sering digunakan untuk error, peringatan, atau tombol hapus permanen." },
            { id: "design-13", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Color Contrast Ratio' dalam standar aksesibilitas web?", answers: ["Perbandingan tingkat kecerahan antara teks dan latar belakangnya agar mudah dibaca", "Jumlah kombinasi warna yang digunakan dalam satu halaman", "Kecepatan transisi warna saat tombol di-hover", "Proses kalibrasi warna monitor desainer"], correct: 0, hint: "Membantu pengguna dengan gangguan penglihatan membaca teks Anda.", explanation: "Rasio kontras warna membandingkan luminansi teks dengan latar belakangnya. WCAG menetapkan kontras minimum (misal 4.5:1 untuk teks normal) untuk aksesibilitas yang baik." },
            { id: "design-14", category: "design", difficulty: "medium", question: "Apakah perbedaan utama antara UI (User Interface) dan UX (User Experience)?", answers: ["UI berfokus pada keindahan visual antarmuka, sedangkan UX berfokus pada kenyamanan dan kemudahan pengguna saat memakai aplikasi", "UI adalah coding frontend, UX adalah coding backend", "UI hanya untuk website desktop, UX hanya untuk aplikasi mobile", "UI dikerjakan oleh manajer produk, UX dikerjakan oleh developer"], correct: 0, hint: "Pikirkan aspek 'estetika' vs 'pengalaman/perasaan'.", explanation: "UI mengurusi tata letak, warna, tipografi, dan aset visual (tampilan). UX mengurusi riset pengguna, alur navigasi, struktur informasi, dan kemudahan interaksi (rasa)." },
            { id: "design-15", category: "design", difficulty: "medium", question: "Apakah fungsi dari 'Grid System' dalam desain layout UI?", answers: ["Membantu menyusun elemen visual agar rapi, konsisten, sejajar, dan proporsional", "Membuat grid database untuk menyimpan gambar", "Mempercepat waktu loading asset gambar", "Mengenkripsi file desain sebelum dikirim"], correct: 0, hint: "Struktur garis bantu vertikal dan horizontal.", explanation: "Grid system (seperti 8px grid atau 12-column grid) digunakan untuk menyelaraskan elemen desain secara konsisten di berbagai ukuran layar." },
            { id: "design-16", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan prinsip 'Fitts's Law' dalam UX Design?", answers: ["Waktu untuk menjangkau target tergantung pada ukuran target dan jarak ke target tersebut", "Semakin banyak pilihan yang diberikan, semakin lama pengguna mengambil keputusan", "Desain harus selalu menggunakan warna pastel", "Website harus dimuat kurang dari 3 detik"], correct: 0, hint: "Tombol yang besar dan dekat lebih mudah diklik.", explanation: "Hukum Fitts menyatakan bahwa target yang berukuran besar dan diletakkan di tempat yang mudah dijangkau (seperti pojok layar atau dekat kursor) akan lebih cepat dan mudah diklik oleh pengguna." },
            { id: "design-17", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Heuristic Evaluation'?", answers: ["Metode pemeriksaan kegunaan (usability) sistem berdasarkan aturan desain praktis (heuristics)", "Proses analisis performa server menggunakan algoritma machine learning", "Pengujian kecepatan loading halaman web secara berkala", "Uji coba keamanan server dari serangan siber"], correct: 0, hint: "Mengevaluasi dengan 10 standar emas Usability milik Jakob Nielsen.", explanation: "Evaluasi heuristik adalah metode audit UX di mana ahli mengevaluasi antarmuka produk digital terhadap prinsip-prinsip kegunaan yang sudah diakui umum (seperti 10 Usability Heuristics Jakob Nielsen)." },
            { id: "design-18", category: "design", difficulty: "easy", question: "Apakah kepanjangan dari SVG dalam tipe file aset desain?", answers: ["Scalable Vector Graphics", "Standard Visual Grid", "Simple Vector Template", "System Visual Graphic"], correct: 0, hint: "Gambar vektor yang tidak pecah saat diperbesar.", explanation: "SVG (Scalable Vector Graphics) adalah format file gambar berbasis XML yang dapat diskalakan tanpa kehilangan resolusi atau kualitas visualnya." },
            { id: "design-19", category: "design", difficulty: "medium", question: "Manakah di bawah ini yang menggambarkan prinsip 'Hick's Law'?", answers: ["Waktu yang dibutuhkan untuk mengambil keputusan meningkat seiring bertambahnya jumlah dan kompleksitas pilihan", "Pengguna menghaisu sebagian besar waktu mereka di situs lain", "Elemen yang diletakkan berdekatan dianggap memiliki fungsi serupa", "Desain harus selalu menyembunyikan detail teknis"], correct: 0, hint: "Terlalu banyak pilihan menu membuat pengguna bingung dan lambat memilih.", explanation: "Hukum Hick menyatakan bahwa semakin banyak pilihan yang disajikan kepada pengguna, semakin lama waktu yang mereka butuhkan untuk berinteraksi dan membuat keputusan." },
            { id: "design-20", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Design Tokens'?", answers: ["Variabel visual terkecil (seperti warna, font, spacing) yang disimpan dalam format netral (JSON) untuk menjaga konsistensi di berbagai platform", "Mata uang kripto khusus untuk membayar desainer grafis", "Kunci keamanan untuk membuka file proyek Figma", "Kode promo diskon untuk membeli aset desain premium"], correct: 0, hint: "Menghubungkan variabel desain dengan kode developer secara otomatis.", explanation: "Design Tokens adalah unit keputusan desain atomik (seperti nilai HSL warna atau unit rem ukuran font) yang diekspor sebagai JSON/YAML agar bisa digunakan langsung oleh tim frontend (Web, iOS, Android) untuk menjaga konsistensi desain sistem." },

            { id: "analytics-1", category: "analytics", difficulty: "easy", question: "Apa itu KPI?", answers: ["Ukuran penting untuk menilai pencapaian tujuan", "Nama bahasa pemrograman", "Format gambar", "Jenis tombol navigasi"], correct: 0, hint: "KPI berhubungan dengan target.", explanation: "KPI adalah metrik utama yang dipakai untuk mengevaluasi performa terhadap tujuan tertentu." },
            { id: "analytics-2", category: "analytics", difficulty: "easy", question: "Apa fungsi dashboard analitik?", answers: ["Meringkas metrik penting agar mudah dipantau", "Menulis kode otomatis", "Menghapus database", "Mengganti UI menjadi gelap"], correct: 0, hint: "Dashboard membantu melihat status.", explanation: "Dashboard menyatukan metrik penting agar tim bisa memantau kondisi dan perubahan dengan cepat." },
            { id: "analytics-3", category: "analytics", difficulty: "easy", question: "Apa arti conversion rate?", answers: ["Persentase pengguna yang menyelesaikan aksi target", "Jumlah warna dalam halaman", "Ukuran file gambar", "Durasi animasi tombol"], correct: 0, hint: "Conversion berkaitan dengan aksi target.", explanation: "Conversion rate mengukur proporsi pengguna yang melakukan aksi penting seperti daftar, beli, atau menyelesaikan kuis." },
            { id: "analytics-4", category: "analytics", difficulty: "easy", question: "Apa itu data segmentasi?", answers: ["Membagi data ke kelompok bermakna untuk analisis lebih jelas", "Menghapus semua data kecil", "Mengubah data menjadi gambar", "Menyimpan data tanpa kategori"], correct: 0, hint: "Segmentasi memecah audiens atau data.", explanation: "Segmentasi membantu menemukan pola yang mungkin tertutup jika semua data digabung." },
            { id: "analytics-5", category: "analytics", difficulty: "medium", question: "Mengapa funnel analysis berguna?", answers: ["Melihat titik pengguna banyak berhenti dalam sebuah alur", "Menghapus data duplikat otomatis", "Membuat password", "Mengubah warna chart"], correct: 0, hint: "Perhatikan perjalanan pengguna dari awal sampai akhir.", explanation: "Funnel analysis menunjukkan tahap mana yang kehilangan banyak pengguna sehingga tim tahu prioritas perbaikan." },
            { id: "analytics-6", category: "analytics", difficulty: "medium", question: "Apa tujuan A/B testing?", answers: ["Membandingkan dua varian untuk melihat mana yang lebih efektif", "Membuat dua database identik", "Menghapus kebutuhan data", "Mengganti bahasa coding"], correct: 0, hint: "A dan B adalah dua versi.", explanation: "A/B testing membantu mengambil keputusan berbasis data dengan membandingkan performa dua varian." },
            { id: "analytics-7", category: "analytics", difficulty: "medium", question: "Mengapa data outlier perlu diperiksa?", answers: ["Outlier bisa menunjukkan error, kasus ekstrem, atau insight penting", "Outlier selalu harus dihapus", "Outlier hanya muncul di gambar", "Outlier membuat chart tidak bisa dibuka"], correct: 0, hint: "Nilai ekstrem punya cerita.", explanation: "Outlier tidak otomatis salah. Ia perlu diperiksa karena bisa berasal dari error atau fenomena penting." },
            { id: "analytics-8", category: "analytics", difficulty: "hard", question: "Apa risiko mengambil keputusan hanya dari rata-rata?", answers: ["Rata-rata bisa menyembunyikan outlier dan perbedaan antar segmen", "Rata-rata selalu salah", "Rata-rata hanya untuk UI", "Data tidak bisa dihitung"], correct: 0, hint: "Segmentasi sering membuka cerita yang tertutup.", explanation: "Rata-rata berguna, tetapi dapat menutup variasi penting. Segmentasi, distribusi, dan outlier perlu ikut dilihat." },
            { id: "analytics-9", category: "analytics", difficulty: "hard", question: "Mengapa korelasi tidak otomatis berarti sebab-akibat?", answers: ["Dua metrik bisa bergerak bersama karena faktor lain", "Korelasi selalu palsu", "Sebab-akibat hanya ada di CSS", "Data angka tidak bisa dibandingkan"], correct: 0, hint: "Ada kemungkinan variabel ketiga.", explanation: "Korelasi menunjukkan hubungan, tetapi eksperimen atau analisis lebih lanjut dibutuhkan untuk menyimpulkan kausalitas." },
            { id: "analytics-10", category: "analytics", difficulty: "hard", question: "Apa masalah umum vanity metric?", answers: ["Terlihat bagus tetapi tidak selalu terkait keputusan atau tujuan bisnis", "Tidak bisa divisualisasikan", "Selalu lebih akurat dari KPI", "Hanya berlaku untuk database"], correct: 0, hint: "Metrik cantik belum tentu actionable.", explanation: "Vanity metric bisa membuat performa tampak bagus tanpa memberi arah tindakan yang berarti." },
            { id: "analytics-11", category: "analytics", difficulty: "easy", question: "Apakah kepanjangan dari CAC dalam analisis bisnis?", answers: ["Customer Acquisition Cost", "Customer Active Count", "Click Action Rate", "Company Asset Cost"], correct: 0, hint: "Biaya untuk mendapatkan pelanggan baru.", explanation: "CAC mengukur total biaya pemasaran dan penjualan yang dikeluarkan untuk meyakinkan satu pelanggan baru agar membeli produk Anda." },
            { id: "analytics-12", category: "analytics", difficulty: "easy", question: "Dalam visualisasi data, kapankah pie chart paling tepat digunakan?", answers: ["Untuk membandingkan bagian-bagian kecil yang membentuk satu kesatuan penuh (persentase total)", "Untuk melacak tren data dari waktu ke waktu", "Untuk menunjukkan hubungan korelasi antara dua variabel angka", "Untuk memvisualisasikan data geografi"], correct: 0, hint: "Menunjukkan proporsi bagian dari 100%.", explanation: "Pie chart terbaik untuk menampilkan komposisi statis dari bagian-bagian kecil yang secara kumulatif membentuk 100%." },
            { id: "analytics-13", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Churn Rate'?", answers: ["Persentase pelanggan yang berhenti berlangganan atau berhenti menggunakan produk dalam jangka waktu tertentu", "Jumlah rata-rata klik yang didapatkan oleh sebuah iklan banner", "Kecepatan loading database saat memproses data transaksi", "Jumlah keuntungan bersih yang didapatkan per hari"], correct: 0, hint: "Berkaitan dengan pelanggan yang pergi/hilang.", explanation: "Churn rate mengukur tingkat kehilangan pelanggan, metrik krusial bagi bisnis berbasis langganan (SaaS) untuk mengukur kepuasan pelanggan." },
            { id: "analytics-14", category: "analytics", difficulty: "medium", question: "Apakah perbedaan utama antara korelasi (correlation) dan kausalitas (causality)?", answers: ["Korelasi menunjukkan hubungan statistik antara dua variabel, sedangkan kausalitas membuktikan bahwa perubahan satu variabel menyebabkan perubahan pada variabel lain", "Korelasi hanya untuk data kualitatif, kausalitas hanya untuk data kuantitatif", "Korelasi selalu benar, kausalitas hanya hipotesis", "Korelasi dikerjakan oleh data analyst, kausalitas dikerjakan oleh developer"], correct: 0, hint: "Ingat pepatah 'Correlation does not imply causation'.", explanation: "Korelasi berarti dua variabel bergerak bersama secara statistik, namun belum tentu salah satunya menyebabkan yang lain terjadi (bisa jadi ada faktor luar/variabel ketiga)." },
            { id: "analytics-15", category: "analytics", difficulty: "medium", question: "Apakah kegunaan utama dari scatter plot dalam analisis data?", answers: ["Melihat pola sebaran dan hubungan korelasi antara dua variabel numerik", "Menampilkan struktur hierarki manajemen perusahaan", "Mengurutkan data kategori dari yang tertinggi", "Menghitung rata-rata nilai matematika"], correct: 0, hint: "Menggunakan koordinat kartesius untuk memplot titik-titik data.", explanation: "Scatter plot menempatkan titik-titik data berdasarkan nilai X dan Y untuk melihat apakah ada hubungan (positif, negatif, atau acak) di antara kedua variabel tersebut." },
            { id: "analytics-16", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'LTV' (Lifetime Value) pelanggan dan mengapa ia penting dibandingkan CAC?", answers: ["Perkiraan total pendapatan yang akan dihasilkan pelanggan selama hubungan bisnis mereka dengan perusahaan; LTV harus lebih tinggi dari CAC agar bisnis profitabel", "Durasi waktu pelanggan membuka aplikasi web; LTV tinggi berarti server lambat", "Jumlah aset komputer yang dipinjamkan ke pelanggan", "Biaya hukum untuk menyelesaikan komplain dari pelanggan"], correct: 0, hint: "Hubungan nilai jangka panjang vs biaya akuisisi.", explanation: "LTV mengukur kontribusi keuangan jangka panjang seorang pelanggan. Rasio LTV:CAC yang sehat (biasanya 3:1) menunjukkan model bisnis berkelanjutan dan menguntungkan." },
            { id: "analytics-17", category: "analytics", difficulty: "hard", question: "Dalam statistika, apakah yang dimaksud dengan 'P-value'?", answers: ["Probabilitas mendapatkan hasil ekstrem yang diamati jika hipotesis nol (H0) benar; digunakan untuk menentukan signifikansi statistik", "Jumlah data outlier yang ditemukan dalam sampel", "Nilai rata-rata dari seluruh populasi data", "Persentase data yang hilang akibat error teknis"], correct: 0, hint: "Nilai batas signifikansi yang biasanya dibandingkan dengan alpha (0.05).", explanation: "P-value mengukur kekuatan bukti melawan hipotesis nol. P-value < 0.05 biasanya dianggap signifikan secara statistik, menolak hipotesis nol untuk mendapat dukungan hipotesis alternatif." },
            { id: "analytics-18", category: "analytics", difficulty: "easy", question: "Apakah kepanjangan dari SQL dalam data analytics?", answers: ["Structured Query Language", "System Query Link", "Simple Quantized Layout", "Standardized Queue Logic"], correct: 0, hint: "Bahasa standar untuk berinteraksi dengan database data.", explanation: "SQL digunakan analis data untuk mengambil, memfilter, dan mengagregasi data dari database relasional sebelum dianalisis." },
            { id: "analytics-19", category: "analytics", difficulty: "medium", question: "Manakah definisi yang tepat untuk 'Cohort Analysis'?", answers: ["Analisis perilaku sekelompok pengguna yang berbagi karakteristik atau pengalaman yang sama dalam rentang waktu tertentu", "Proses pembersihan data dari nilai kosong menggunakan algoritma python", "Metode untuk mengamankan hak akses database", "Penghitungan laba bersih sebelum dipotong pajak"], correct: 0, hint: "Mengelompokkan pengguna berdasarkan bulan pendaftaran mereka.", explanation: "Cohort Analysis membagi pengguna ke dalam kelompok (kohort) berdasarkan tanggal aktivitas awal mereka untuk melihat bagaimana retensi atau perilaku mereka berubah seiring waktu." },
            { id: "analytics-20", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Predictive Analytics'?", answers: ["Penggunaan data historis, algoritma statistik, dan teknik machine learning untuk memprediksi hasil di masa depan", "Laporan ringkasan tentang penjualan perusahaan di bulan lalu", "Sistem pendeteksi virus komputer yang berjalan di server", "Proses mengarsipkan data lama yang sudah tidak aktif ke cold storage"], correct: 0, hint: "Berfokus pada peramalan masa depan (forecasting).", explanation: "Predictive analytics melampaui analisis data deskriptif (apa yang terjadi) untuk memprediksi tren dan perilaku masa depan berdasarkan pola data historis." },

            { id: "web-1", category: "web", difficulty: "easy", question: "Apa fungsi HTML dalam halaman web?", answers: ["Menyusun struktur konten halaman", "Mengatur query database", "Menjalankan server fisik", "Mengenkripsi password"], correct: 0, hint: "HTML adalah kerangka konten.", explanation: "HTML mendefinisikan struktur seperti heading, paragraf, link, form, dan elemen halaman." },
            { id: "web-2", category: "web", difficulty: "easy", question: "Apa fungsi CSS?", answers: ["Mengatur tampilan visual seperti layout, warna, dan spacing", "Menyimpan data permanen", "Mengirim email otomatis", "Membuat primary key"], correct: 0, hint: "CSS bicara soal gaya visual.", explanation: "CSS mengontrol presentasi halaman web, termasuk responsif, animasi, dan komponen visual." },
            { id: "web-3", category: "web", difficulty: "easy", question: "Apa fungsi JavaScript di browser?", answers: ["Membuat halaman interaktif dan merespons aksi pengguna", "Mengganti semua file menjadi gambar", "Mencetak database", "Menghapus kebutuhan HTML"], correct: 0, hint: "Interaksi adalah kata kuncinya.", explanation: "JavaScript memungkinkan validasi form, update UI, fetch data, dan logika interaktif di browser." },
            { id: "web-4", category: "web", difficulty: "easy", question: "Apa arti responsive design?", answers: ["Tampilan menyesuaikan ukuran layar dan perangkat", "Server merespons lebih cepat", "Semua tombol berkedip", "Website hanya untuk desktop"], correct: 0, hint: "Pikirkan mobile dan desktop.", explanation: "Responsive design membuat layout tetap nyaman di berbagai ukuran layar." },
            { id: "web-5", category: "web", difficulty: "medium", question: "Apa kegunaan fetch API?", answers: ["Mengambil atau mengirim data melalui request HTTP", "Menggambar ikon SVG otomatis", "Mengubah font Google", "Membuat file zip"], correct: 0, hint: "Fetch berkaitan dengan network request.", explanation: "Fetch API digunakan untuk berkomunikasi dengan server, biasanya mengambil JSON atau mengirim data." },
            { id: "web-6", category: "web", difficulty: "medium", question: "Mengapa semantic HTML penting?", answers: ["Membantu aksesibilitas, SEO, dan struktur dokumen yang jelas", "Agar CSS tidak perlu ditulis", "Agar semua gambar hilang", "Agar database otomatis terhubung"], correct: 0, hint: "Makna elemen penting.", explanation: "Semantic HTML seperti nav, main, section, dan button memberi makna yang dapat dipahami browser dan assistive tech." },
            { id: "web-7", category: "web", difficulty: "medium", question: "Apa penyebab umum layout shift?", answers: ["Ukuran elemen seperti gambar tidak disiapkan sebelum konten dimuat", "Terlalu banyak primary key", "Nama class terlalu panjang", "Semua link memakai href"], correct: 0, hint: "Layout berubah setelah loading.", explanation: "Layout shift terjadi ketika elemen berubah posisi setelah konten lain dimuat, misalnya gambar tanpa dimensi tetap." },
            { id: "web-8", category: "web", difficulty: "hard", question: "Mengapa event delegation berguna?", answers: ["Satu listener parent bisa menangani banyak child dinamis", "Semua event jadi lebih lambat", "CSS otomatis dibuat", "HTML tidak perlu struktur"], correct: 0, hint: "Parent bisa mendengar klik child.", explanation: "Event delegation memanfaatkan bubbling untuk menangani elemen dinamis tanpa memasang listener satu per satu." },
            { id: "web-9", category: "web", difficulty: "hard", question: "Apa risiko menyimpan token sensitif di localStorage?", answers: ["Token rentan dicuri jika terjadi XSS", "Token otomatis terenkripsi kuat", "Token tidak bisa dibaca JavaScript", "Browser menolak semua localStorage"], correct: 0, hint: "localStorage bisa dibaca JavaScript.", explanation: "Jika aplikasi terkena XSS, script berbahaya dapat membaca localStorage dan mengambil token sensitif." },
            { id: "web-10", category: "web", difficulty: "hard", question: "Apa fungsi lazy loading pada aset web?", answers: ["Menunda pemuatan aset sampai benar-benar dibutuhkan", "Memuat semua aset dua kali", "Menghapus gambar dari DOM", "Membuat CSS tidak berlaku"], correct: 0, hint: "Tidak semua aset harus dimuat di awal.", explanation: "Lazy loading dapat mempercepat load awal dengan menunda gambar atau modul yang belum terlihat." },
            { id: "web-11", category: "web", difficulty: "easy", question: "Apakah fungsi utama dari protokol HTTPS dibanding HTTP biasa?", answers: ["Mengamankan komunikasi data dengan enkripsi SSL/TLS agar tidak bisa diintip pihak luar", "Mempercepat loading website dengan kompresi gambar", "Membuat desain website menjadi responsif otomatis", "Mencegah website mati saat diakses banyak pengunjung"], correct: 0, hint: "Pikirkan keamanan enkripsi data sensitif.", explanation: "HTTPS (Hypertext Transfer Protocol Secure) mengenkripsi seluruh pertukaran data antara browser dan server untuk melindunginya dari intersepsi (eavesdropping)." },
            { id: "web-12", category: "web", difficulty: "easy", question: "Manakah tag HTML yang digunakan untuk membuat link ke halaman lain?", answers: ["<a>", "<link>", "<href>", "<button>"], correct: 0, hint: "Singkatan dari 'anchor'.", explanation: "Tag <a> (anchor) digunakan bersama atribut href untuk membuat hyperlink ke halaman web atau file lain." },
            { id: "web-13", category: "web", difficulty: "medium", question: "Apakah kegunaan utama dari CSS Flexbox?", answers: ["Menyusun tata letak elemen secara satu dimensi (baris atau kolom) agar responsif dan mudah sejajar", "Menghubungkan frontend dengan database relasional", "Mengatur fungsi interaktif seperti pop-up login", "Membuat animasi 3D yang berat di web"], correct: 0, hint: "Solusi layout satu dimensi yang fleksibel.", explanation: "Flexbox (Flexible Box Layout) memudahkan perataan, distribusi ruang, dan penyusunan elemen di dalam container, bahkan saat ukurannya dinamis." },
            { id: "web-14", category: "web", difficulty: "medium", question: "Apakah perbedaan utama antara Cookies, LocalStorage, dan SessionStorage di browser?", answers: ["Cookies dikirim ke server pada setiap request, LocalStorage bertahan selamanya, sedangkan SessionStorage hilang saat tab ditutup", "LocalStorage dikirim ke server, Cookies hanya disimpan di browser lokal", "SessionStorage bertahan selamanya, LocalStorage hilang saat browser ditutup", "Ketiganya memiliki kapasitas penyimpanan yang sama persis yaitu 100 GB"], correct: 0, hint: "Pikirkan masa aktif penyimpanan dan komunikasi dengan server.", explanation: "Cookies digunakan untuk autentikasi dan dikirim ke server. LocalStorage menyimpan data secara permanen di browser (kapasitas ~5-10MB). SessionStorage hanya menyimpan data selama sesi tab aktif." },
            { id: "web-15", category: "web", difficulty: "medium", question: "Apakah kepanjangan dari API dalam konteks web development?", answers: ["Application Programming Interface", "Active Performance Indicator", "Automated Program Integration", "Advanced Protocol Internet"], correct: 0, hint: "Jembatan komunikasi antar aplikasi.", explanation: "API adalah sekumpulan definisi dan protokol yang memungkinkan satu aplikasi perangkat lunak berinteraksi dan berbagi data dengan aplikasi lainnya." },
            { id: "web-16", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan CORS (Cross-Origin Resource Sharing)?", answers: ["Mekanisme keamanan browser untuk membatasi request resource dari origin yang berbeda dari origin situs saat ini", "Proses mengompres file CSS dan JS menjadi ukuran yang sangat kecil", "Sistem distribusi beban server web menggunakan CDN global", "Algoritma enkripsi password yang aman di server backend"], correct: 0, hint: "Browser memblokir fetch API dari domain lain jika header CORS tidak disiapkan.", explanation: "CORS adalah kebijakan keamanan browser (Same-Origin Policy) yang mencegah script berbahaya membaca resource sensitif dari origin (domain/protokol/port) lain kecuali server tujuan mengizinkannya secara eksplisit lewat header HTTP." },
            { id: "web-17", category: "web", difficulty: "hard", question: "Dalam optimasi performa web, apakah yang dimaksud dengan metrik 'LCP' (Largest Contentful Paint)?", answers: ["Waktu yang dibutuhkan browser untuk merender elemen visual terbesar (seperti gambar banner atau teks utama) di layar", "Kecepatan server merespons koneksi internet pertama kali", "Jumlah total bytes file javascript yang diunduh oleh halaman", "Durasi waktu yang diperlukan pengguna untuk berpindah halaman"], correct: 0, hint: "Salah satu metrik Core Web Vitals penting dari Google.", explanation: "LCP mengukur waktu rendering konten utama halaman web. LCP yang baik adalah kurang dari 2.5 detik untuk memberikan pengalaman pengguna yang responsif." },
            { id: "web-18", category: "web", difficulty: "easy", question: "Apakah fungsi dari tag HTML <meta charset='UTF-8'>?", answers: ["Menentukan encoding karakter dokumen agar browser menampilkan teks bahasa dunia dengan benar", "Mengatur warna latar belakang halaman web menjadi transparan", "Menyisipkan file stylesheet eksternal", "Menghubungkan halaman web dengan library JavaScript jQuery"], correct: 0, hint: "Berhubungan dengan encoding teks.", explanation: "UTF-8 mendukung hampir semua karakter tulisan dunia, memastikan browser menampilkan simbol dan alfabet khusus secara akurat." },
            { id: "web-19", category: "web", difficulty: "medium", question: "Manakah status kode HTTP yang menunjukkan bahwa resource tidak ditemukan di server?", answers: ["404 Not Found", "500 Internal Server Error", "200 OK", "302 Found (Redirect)"], correct: 0, hint: "Sangat populer saat halaman web rusak atau hilang.", explanation: "Status 404 adalah kode respons standar HTTP yang menunjukkan bahwa server tidak dapat menemukan berkas yang diminta oleh pengguna." },
            { id: "web-20", category: "web", difficulty: "hard", question: "Apakah perbedaan utama antara Single Page Application (SPA) dan Multi Page Application (MPA)?", answers: ["SPA memuat satu dokumen HTML awal dan memperbarui konten secara dinamis tanpa reload halaman, sedangkan MPA memuat dokumen HTML baru dari server setiap kali pindah halaman", "SPA ditulis dengan Python, MPA ditulis dengan PHP", "SPA hanya mendukung perangkat mobile, MPA mendukung semua perangkat", "SPA tidak bisa memiliki link eksternal, MPA bisa"], correct: 0, hint: "Pikirkan perilaku reload halaman browser saat pindah menu.", explanation: "SPA (seperti aplikasi React/Vue) menawarkan transisi yang lebih mulus dan cepat karena hanya meminta data (JSON) dari server, bukan dokumen HTML utuh seperti MPA tradisional." },

            { id: "cyber-1", category: "cyber", difficulty: "easy", question: "Apa ciri password yang lebih aman?", answers: ["Panjang, unik, dan sulit ditebak", "Sama untuk semua akun", "Berisi nama sendiri saja", "Disimpan di komentar publik"], correct: 0, hint: "Panjang dan unik lebih penting.", explanation: "Password kuat sebaiknya panjang, unik per layanan, dan dikelola dengan password manager bila memungkinkan." },
            { id: "cyber-2", category: "cyber", difficulty: "easy", question: "Apa itu phishing?", answers: ["Upaya menipu pengguna agar memberikan data sensitif", "Teknik mempercepat CSS", "Jenis database relasional", "Metode desain ikon"], correct: 0, hint: "Biasanya lewat pesan palsu.", explanation: "Phishing memancing korban lewat email, chat, atau halaman palsu agar memberikan password, OTP, atau data penting." },
            { id: "cyber-3", category: "cyber", difficulty: "easy", question: "Mengapa update software penting?", answers: ["Sering membawa perbaikan keamanan dan bug", "Agar semua data hilang", "Agar password menjadi pendek", "Agar layar selalu gelap"], correct: 0, hint: "Patch keamanan sering datang lewat update.", explanation: "Update software dapat menutup celah keamanan yang sudah diketahui dan meningkatkan stabilitas." },
            { id: "cyber-4", category: "cyber", difficulty: "easy", question: "Apa tujuan two-factor authentication?", answers: ["Menambah lapisan verifikasi selain password", "Menghapus akun lama", "Membuat UI lebih ramai", "Mengganti username"], correct: 0, hint: "Password bukan satu-satunya bukti.", explanation: "2FA mengurangi risiko akun diambil alih meski password bocor." },
            { id: "cyber-5", category: "cyber", difficulty: "medium", question: "Apa prinsip least privilege?", answers: ["Memberi akses minimum yang dibutuhkan untuk tugas", "Memberi akses admin ke semua orang", "Menghapus semua role", "Membuka database publik"], correct: 0, hint: "Akses secukupnya.", explanation: "Least privilege membatasi dampak kesalahan atau kebocoran dengan memberi izin sesuai kebutuhan saja." },
            { id: "cyber-6", category: "cyber", difficulty: "medium", question: "Mengapa backup perlu diuji restore-nya?", answers: ["Backup belum terbukti berguna sampai bisa dipulihkan", "Agar file backup lebih besar", "Agar password berubah", "Agar query lebih lambat"], correct: 0, hint: "Backup yang tidak bisa dipulihkan tidak banyak membantu.", explanation: "Uji restore memastikan data benar-benar dapat dikembalikan saat insiden terjadi." },
            { id: "cyber-7", category: "cyber", difficulty: "medium", question: "Apa itu data minimization?", answers: ["Mengumpulkan data secukupnya sesuai kebutuhan", "Menghapus semua data penting", "Menyimpan data tanpa izin", "Membuat data tidak bisa dicari"], correct: 0, hint: "Ambil yang perlu saja.", explanation: "Data minimization mengurangi risiko privasi dan keamanan dengan tidak mengumpulkan data berlebihan." },
            { id: "cyber-8", category: "cyber", difficulty: "hard", question: "Apa risiko XSS pada aplikasi web?", answers: ["Script berbahaya dapat berjalan di browser pengguna", "Server selalu mati total", "CSS tidak bisa dimuat", "Database otomatis terenkripsi"], correct: 0, hint: "XSS menyisipkan script.", explanation: "XSS memungkinkan penyerang menjalankan script di konteks situs, mencuri data, atau memanipulasi halaman." },
            { id: "cyber-9", category: "cyber", difficulty: "hard", question: "Mengapa input user harus divalidasi di server juga?", answers: ["Validasi client bisa dilewati atau dimanipulasi", "Server tidak bisa membaca input", "Browser selalu benar", "CSS bisa mengganti database"], correct: 0, hint: "Client bukan sumber kepercayaan.", explanation: "Validasi server wajib karena request bisa dibuat langsung tanpa mengikuti aturan UI di browser." },
            { id: "cyber-10", category: "cyber", difficulty: "hard", question: "Apa manfaat audit log pada sistem penting?", answers: ["Mencatat aktivitas agar insiden dan perubahan bisa ditelusuri", "Menghapus error otomatis", "Mengganti backup", "Membuat semua user admin"], correct: 0, hint: "Log membantu investigasi.", explanation: "Audit log memberi jejak aktivitas penting sehingga tim dapat meninjau perubahan, akses, dan potensi insiden." },
            { id: "cyber-11", category: "cyber", difficulty: "easy", question: "Apakah yang dimaksud dengan VPN (Virtual Private Network)?", answers: ["Layanan yang mengenkripsi lalu lintas internet Anda dan menyembunyikan identitas online Anda dengan merutekannya melalui server aman", "Aplikasi untuk mempercepat koneksi Wi-Fi secara gratis", "Antivirus untuk membersihkan file sampah di komputer", "Database khusus untuk menyimpan password akun media sosial"], correct: 0, hint: "Membuat terowongan enkripsi privat di internet publik.", explanation: "VPN mengamankan koneksi internet Anda dengan mengenkripsi data Anda dan menyembunyikan alamat IP asli Anda untuk menjaga privasi." },
            { id: "cyber-12", category: "cyber", difficulty: "easy", question: "Apakah kepanjangan dari MFA dalam keamanan siber?", answers: ["Multi-Factor Authentication", "Malicious File Analyzer", "Mobile Firewall Access", "Main Frame Auditor"], correct: 0, hint: "Membutuhkan lebih dari sekadar password untuk masuk.", explanation: "MFA adalah metode verifikasi identitas yang mengharuskan pengguna memberikan dua atau lebih faktor verifikasi untuk mendapatkan akses ke akun." },
            { id: "cyber-13", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan serangan Ransomware?", answers: ["Malware yang mengenkripsi file korban dan menuntut pembayaran tebusan untuk kunci dekripsi", "Serangan yang membuat server web mati akibat dibanjiri trafik palsu", "Teknik mencuri informasi kartu kredit lewat form login palsu", "Penyusupan ke ruang server fisik untuk mencuri komputer"], correct: 0, hint: "Ransom berarti tebusan.", explanation: "Ransomware adalah jenis perangkat perusak (malware) berbahaya yang menyandera data komputer dengan enkripsi kuat, lalu memeras korban untuk membayar uang tebusan." },
            { id: "cyber-14", category: "cyber", difficulty: "medium", question: "Apakah perbedaan utama antara enkripsi simetris (symmetric encryption) dan enkripsi asimetris (asymmetric encryption)?", answers: ["Enkripsi simetris menggunakan satu kunci untuk enkripsi dan dekripsi, sedangkan asimetris menggunakan sepasang kunci (kunci publik dan kunci privat)", "Enkripsi simetris hanya untuk teks pendek, asimetris untuk file besar", "Enkripsi simetris tidak aman, asimetris sangat aman", "Enkripsi simetris diproses oleh hardware, asimetris oleh software"], correct: 0, hint: "Jumlah kunci rahasia yang digunakan.", explanation: "Enkripsi simetris lebih cepat tetapi membutuhkan transfer kunci aman. Enkripsi asimetris menyelesaikan masalah distribusi kunci dengan menggunakan Public Key untuk enkripsi dan Private Key untuk dekripsi." },
            { id: "cyber-15", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Social Engineering' dalam keamanan informasi?", answers: ["Teknik manipulasi psikologis untuk membohongi orang agar membocorkan informasi rahasia atau melakukan tindakan tertentu", "Pekerjaan membangun jaringan server yang ramah lingkungan", "Cara membuat postingan media sosial yang cepat viral", "Proses audit hubungan interpersonal di dalam kantor"], correct: 0, hint: "Meretas manusia, bukan meretas sistem komputer langsung.", explanation: "Social engineering menargetkan kerentanan manusia (seperti rasa percaya, takut, atau tergesa-gesa) untuk menipu mereka agar memberikan data login, OTP, atau uang." },
            { id: "cyber-16", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan serangan 'Man-in-the-Middle' (MitM)?", answers: ["Penyerang secara diam-diam mencegat dan mengubah komunikasi antara dua pihak yang percaya mereka terhubung langsung satu sama lain", "Serangan fisik dengan merusak kabel internet bawah laut", "Proses membagi tugas server backend secara adil", "Hacker yang menyamar menjadi staf IT internal perusahaan"], correct: 0, hint: "Pikirkan penyadap di antara pengirim dan penerima.", explanation: "Serangan MitM sering terjadi pada jaringan Wi-Fi publik yang tidak aman, di mana penyerang berada di tengah lalu lintas komunikasi untuk mencuri data sensitif seperti password atau data kartu kredit." },
            { id: "cyber-17", category: "cyber", difficulty: "hard", question: "Manakah deskripsi terbaik untuk prinsip keamanan 'Zero Trust'?", answers: ["Jangan pernah percaya, selalu verifikasi; setiap permintaan akses harus diautentikasi, diotorisasi, dan dienkripsi sebelum diizinkan", "Sistem keamanan yang tidak membutuhkan password sama sekali", "Database yang tidak memiliki aturan hak akses user", "Kepercayaan penuh pada firewall perimeter untuk mengamankan jaringan internal"], correct: 0, hint: "Mengasumsikan jaringan internal sudah disusupi.", explanation: "Model Zero Trust meniadakan anggapan bahwa segala sesuatu di dalam jaringan internal aman. Ia mewajibkan verifikasi ketat untuk setiap perangkat dan pengguna, di mana pun lokasinya." },
            { id: "cyber-18", category: "cyber", difficulty: "easy", question: "Di bawah ini, manakah yang merupakan contoh malware?", answers: ["Virus, Trojan, Worm, dan Spyware", "Windows Defender, Avast, dan Kaspersky", "Chrome, Firefox, dan Safari", "MySQL, MongoDB, dan Oracle"], correct: 0, hint: "Perangkat lunak berbahaya.", explanation: "Malware (malicious software) adalah istilah umum untuk program berbahaya yang dirancang untuk merusak, mengganggu, atau menyusup ke sistem komputer tanpa izin." },
            { id: "cyber-19", category: "cyber", difficulty: "medium", question: "Apakah kegunaan utama dari Firewall dalam sistem jaringan?", answers: ["Memantau dan menyaring lalu lintas jaringan masuk dan keluar berdasarkan aturan keamanan yang ditentukan", "Menghapus virus dan malware yang sudah masuk ke harddisk", "Mempercepat transfer file antar komputer di kantor", "Mengubah IP address komputer menjadi IP address server otomatis"], correct: 0, hint: "Pikirkan pos penjaga gerbang masuk jaringan.", explanation: "Firewall bertindak sebagai penghalang antara jaringan internal tepercaya dan jaringan eksternal yang tidak tepercaya (seperti internet) untuk memblokir akses ilegal." },
            { id: "cyber-20", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan serangan SQL Injection (SQLi) dan bagaimana cara terbaik untuk mencegahnya?", answers: ["Penyisipan kode SQL berbahaya ke input form untuk memanipulasi query database; dicegah dengan Prepared Statements (Parameterized Queries)", "Memasukkan terlalu banyak data ke tabel database; dicegah dengan normalisasi tabel", "Serangan menghapus file backup database; dicegah dengan enkripsi harddisk", "Mengganti password database secara paksa; dicegah dengan two-factor authentication"], correct: 0, hint: "Memisahkan data dari instruksi SQL menggunakan parameterized query.", explanation: "SQLi terjadi saat input pengguna langsung digabungkan ke string SQL. Prepared Statements memisahkan kode SQL dari input data sehingga database memperlakukan input murni sebagai data, bukan perintah yang bisa dieksekusi." },
            
            // Programming (New 21-30)
            { id: "programming-21", category: "programming", difficulty: "easy", question: "Apa fungsi dari indeks array?", answers: ["Mengakses elemen spesifik berdasarkan posisinya mulai dari 0", "Menghitung total elemen secara otomatis", "Mengubah tipe data array menjadi string", "Menghapus data array permanen dari RAM"], correct: 0, hint: "Indeks adalah alamat urutan di dalam laci data.", explanation: "Indeks array digunakan untuk merujuk ke elemen tertentu dalam array, di mana penomoran indeks dimulai dari angka 0." },
            { id: "programming-22", category: "programming", difficulty: "easy", question: "Apa kegunaan utama dari tipe data float atau double?", answers: ["Menyimpan angka desimal (pecahan)", "Menyimpan karakter huruf tunggal", "Menghubungkan program ke internet", "Membuat loop berjalan lebih cepat"], correct: 0, hint: "Pikirkan angka seperti 3.14 atau 0.5.", explanation: "Tipe data float atau double digunakan untuk menyimpan bilangan riil yang memiliki koma atau pecahan desimal." },
            { id: "programming-23", category: "programming", difficulty: "medium", question: "Apa kegunaan dari return statement pada sebuah function?", answers: ["Menghentikan eksekusi function dan mengembalikan suatu nilai ke pemanggilnya", "Mencetak teks ke console browser secara otomatis", "Mendeklarasikan variabel baru di dalam local scope", "Menyalin kode function ke file lain"], correct: 0, hint: "Mengirimkan hasil olahan fungsi kembali ke kode luar.", explanation: "Return statement mengakhiri jalannya blok fungsi dan mengirimkan nilai hasil komputasi kembali ke baris kode yang memanggil fungsi tersebut." },
            { id: "programming-24", category: "programming", difficulty: "medium", question: "Manakah penjelasan terbaik mengenai stack overflow?", answers: ["Kondisi eror saat tumpukan memori penuh akibat pemanggilan rekursi tanpa batas", "Database kelebihan kapasitas data transaksi", "Pencurian bandwidth internet oleh server asing", "Keadaan saat browser mendownload gambar terlalu besar"], correct: 0, hint: "Berhubungan dengan tumpukan memori (call stack) yang kehabisan ruang.", explanation: "Stack overflow terjadi ketika call stack melebihi batas alokasi memorinya, yang paling sering dipicu oleh fungsi rekursif yang tidak memiliki base case (kondisi berhenti) yang benar." },
            { id: "programming-25", category: "programming", difficulty: "medium", question: "Apa perbedaan utama antara runtime error dan syntax error?", answers: ["Syntax error melanggar aturan tata bahasa kode, runtime error terjadi saat program berjalan akibat logika atau data tak terduga", "Syntax error hanya terjadi di JavaScript, runtime error hanya terjadi di database", "Syntax error membuat RAM penuh, runtime error menghapus file kode", "Syntax error diperbaiki oleh browser, runtime error diperbaiki oleh OS"], correct: 0, hint: "Satu adalah kesalahan tata tulis sebelum dijalankan, yang lain adalah kesalahan saat eksekusi.", explanation: "Syntax error dideteksi oleh compiler/parser saat pembacaan kode karena melanggar tata bahasa pemrograman. Runtime error terjadi saat instruksi dijalankan (misal pembagian dengan nol atau mengakses properti null)." },
            { id: "programming-26", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Race Condition' dalam konsep pemrograman multithreading?", answers: ["Kondisi di mana hasil akhir program bergantung pada urutan atau waktu eksekusi thread yang tidak terduga", "Dua programmer menulis kode di file yang sama secara berebutan", "Kecepatan eksekusi kode backend yang lebih lambat dari frontend", "Proses transfer data database yang terhambat akibat antrean jaringan"], correct: 0, hint: "Beberapa thread memodifikasi data bersama secara tidak sinkron.", explanation: "Race condition terjadi ketika dua atau lebih thread mengakses data bersama secara konkuren dan hasil akhirnya ditentukan oleh urutan penjadwalan CPU, memicu bug yang sulit dilacak." },
            { id: "programming-27", category: "programming", difficulty: "hard", question: "Apa fungsi dari Garbage Collector dalam runtime environment pemrograman?", answers: ["Mengidentifikasi dan membebaskan memori yang tidak lagi dirujuk oleh program secara otomatis", "Membersihkan file cache browser secara berkala", "Menghapus kode program yang mengandung bug atau eror", "Mengompres ukuran file gambar di dalam folder project"], correct: 0, hint: "Mengelola memori RAM yang tidak terpakai lagi.", explanation: "Garbage Collector (seperti pada JavaScript V8 atau Java VM) melacak objek di memori dan menghapusnya jika objek tersebut sudah tidak memiliki referensi aktif, mencegah kebocoran memori." },
            { id: "programming-28", category: "programming", difficulty: "easy", question: "Di bawah ini, manakah yang merupakan operator perbandingan logika 'DAN' (AND) dalam JavaScript?", answers: ["&&", "||", "!", "=="], correct: 0, hint: "Membutuhkan kedua kondisi bernilai benar agar menghasilkan true.", explanation: "Operator && adalah operator logika AND yang mengembalikan true hanya jika ekspresi di kiri dan kanannya bernilai benar." },
            { id: "programming-29", category: "programming", difficulty: "medium", question: "Apa yang dimaksud dengan 'Scope' pada variabel?", answers: ["Wilayah atau cakupan kode di mana variabel tersebut dapat diakses dan digunakan", "Ukuran memori RAM yang digunakan oleh suatu variabel", "Waktu yang dibutuhkan variabel untuk melakukan update nilai", "Jenis tipe data yang dapat disimpan di dalam variabel"], correct: 0, hint: "Batasan visibilitas variabel (global vs lokal).", explanation: "Scope menentukan visibilitas atau aksesibilitas variabel di berbagai bagian kode program (seperti block scope, function scope, atau global scope)." },
            { id: "programming-30", category: "programming", difficulty: "hard", question: "Dalam OOP, apa bedanya Class dengan Object?", answers: ["Class adalah cetak biru (blueprint) desain, sedangkan Object adalah wujud nyata (instance) dari class tersebut", "Class digunakan untuk database, Object digunakan untuk tampilan UI", "Class hanya bisa dibuat sekali, Object bisa disalin ribuan kali tanpa class", "Class memperlambat program, Object mempercepat eksekusi memori"], correct: 0, hint: "Satu adalah rancangan di kertas, satu lagi adalah rumah yang sudah jadi.", explanation: "Class mendefinisikan struktur data dan perilaku (metode), sementara Object adalah instansiasi nyata di memori yang dibuat berdasarkan definisi Class tersebut." },

            // Database (New 21-30)
            { id: "database-21", category: "database", difficulty: "easy", question: "Bagaimana cara mengambil seluruh baris data dari tabel bernama 'siswa' menggunakan SQL?", answers: ["SELECT * FROM siswa;", "GET ALL FROM siswa;", "SELECT ALL siswa;", "READ TABLE siswa;"], correct: 0, hint: "Tanda bintang (*) melambangkan semua kolom.", explanation: "Kueri SELECT * FROM nama_tabel digunakan untuk membaca seluruh kolom dan baris yang ada di dalam tabel tersebut." },
            { id: "database-22", category: "database", difficulty: "easy", question: "Apa fungsi dari klausa LIMIT dalam query SQL?", answers: ["Membatasi jumlah baris hasil query yang dikembalikan oleh database", "Membatasi kapasitas memori harddisk untuk database", "Membatasi jumlah karakter yang bisa diinput ke kolom", "Menghapus koneksi database yang sedang idle"], correct: 0, hint: "Membatasi kuantitas data keluaran query.", explanation: "Klausa LIMIT (atau TOP di beberapa sistem) digunakan untuk membatasi jumlah record maksimal yang dikembalikan oleh kueri database." },
            { id: "database-23", category: "database", difficulty: "medium", question: "Manakah kueri SQL yang tepat untuk menghapus baris data di tabel 'guru' yang memiliki id = 5?", answers: ["DELETE FROM guru WHERE id = 5;", "DROP FROM guru WHERE id = 5;", "REMOVE FROM guru WHERE id = 5;", "DELETE WHERE id = 5 FROM guru;"], correct: 0, hint: "Gunakan perintah DELETE dengan filter WHERE.", explanation: "Perintah DELETE FROM guru WHERE id = 5 menghapus baris tertentu yang memenuhi filter, sementara DROP digunakan untuk menghapus seluruh struktur tabel." },
            { id: "database-24", category: "database", difficulty: "medium", question: "Apa perbedaan utama antara INNER JOIN dan LEFT JOIN?", answers: ["INNER JOIN hanya mengambil baris yang cocok di kedua tabel, LEFT JOIN mengambil semua baris tabel kiri dan yang cocok dari tabel kanan", "INNER JOIN menggabungkan kolom secara vertikal, LEFT JOIN secara horizontal", "INNER JOIN lebih lambat dari LEFT JOIN tanpa index", "INNER JOIN hanya untuk database SQL, LEFT JOIN untuk database NoSQL"], correct: 0, hint: "Pikirkan tentang data di tabel sebelah kiri yang tidak memiliki pasangan.", explanation: "INNER JOIN hanya mengembalikan baris yang memiliki kecocokan di kedua tabel. LEFT JOIN mengembalikan seluruh baris dari tabel kiri, serta baris yang cocok dari tabel kanan (diisi NULL jika tidak cocok)." },
            { id: "database-25", category: "database", difficulty: "medium", question: "Apa fungsi utama dari perintah SQL UPDATE?", answers: ["Mengubah atau memperbarui nilai kolom pada baris data yang sudah ada di tabel", "Membuat tabel baru dengan kolom yang diperbarui", "Mengimpor data dari file CSV eksternal", "Menambahkan baris baru ke dalam tabel database"], correct: 0, hint: "Mengedit isi record yang sudah tersimpan.", explanation: "UPDATE digunakan untuk memodifikasi nilai data pada baris yang sudah ada di tabel, biasanya diikuti klausa WHERE untuk membatasi baris yang diubah." },
            { id: "database-26", category: "database", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Database Indexing Cardinality'?", answers: ["Ukuran keunikan nilai data dalam suatu kolom tabel yang di-index", "Jumlah total index yang diizinkan dalam satu database", "Kecepatan database membaca index B-Tree di RAM", "Ukuran file penyimpanan index di harddisk server"], correct: 0, hint: "Semakin banyak nilai unik (seperti ID), semakin tinggi tingkat kardinalitasnya.", explanation: "Kardinalitas merujuk pada keunikan nilai data dalam kolom tertentu. Kolom dengan kardinalitas tinggi (misal email) sangat bagus untuk di-index dibanding kardinalitas rendah (misal gender)." },
            { id: "database-27", category: "database", difficulty: "hard", question: "Apa keuntungan utama menggunakan transaksi database bertingkat (nested transaction / savepoints)?", answers: ["Memungkinkan rollback sebagian operasi tanpa membatalkan seluruh transaksi utama", "Meningkatkan kecepatan query INSERT secara horizontal", "Mengurangi ukuran backup log database secara otomatis", "Menghubungkan database relasional ke server NoSQL secara langsung"], correct: 0, hint: "Gunakan SAVEPOINT untuk membuat titik pemulihan parsial.", explanation: "Dengan SAVEPOINT, pengembang dapat menandai titik tertentu di dalam transaksi dan melakukan ROLLBACK ke savepoint tersebut jika terjadi kegagalan kecil, tanpa membatalkan seluruh transaksi dari awal." },
            { id: "database-28", category: "database", difficulty: "easy", question: "Perintah SQL manakah yang digunakan untuk membuat database baru?", answers: ["CREATE DATABASE nama_database;", "NEW DATABASE nama_database;", "MAKE DATABASE nama_database;", "ADD DATABASE nama_database;"], correct: 0, hint: "CREATE adalah perintah DDL untuk membuat objek baru.", explanation: "CREATE DATABASE digunakan untuk membuat database baru di server manajemen database (DBMS)." },
            { id: "database-29", category: "database", difficulty: "medium", question: "Apa fungsi dari klausa HAVING dalam SQL?", answers: ["Menyaring baris ringkasan hasil GROUP BY berdasarkan kondisi agregat", "Mengurutkan hasil query dari nilai terbesar ke terkecil", "Menyaring baris sebelum data dikelompokkan oleh GROUP BY", "Mencegah nilai duplikat masuk ke database"], correct: 0, hint: "HAVING adalah WHERE untuk fungsi agregasi setelah GROUP BY.", explanation: "Klausa HAVING digunakan untuk memfilter baris hasil agregasi (seperti COUNT atau SUM) yang dihasilkan oleh klausa GROUP BY, karena WHERE tidak bisa digunakan langsung dengan fungsi agregat." },
            { id: "database-30", category: "database", difficulty: "hard", question: "Manakah penjelasan terbaik tentang 'Deadlock' dalam database?", answers: ["Kondisi di mana dua transaksi saling menunggu lock yang dipegang oleh transaksi lainnya, menyebabkan keduanya mandek", "Server database mati akibat korsleting listrik", "Kegagalan kueri akibat tabel yang terkunci permanen karena crash program", "File log transaksi yang sudah penuh dan menolak perintah tulis"], correct: 0, hint: "Transaksi A menunggu Transaksi B, sementara Transaksi B menunggu Transaksi A.", explanation: "Deadlock terjadi ketika Transaksi 1 mengunci Data A dan menunggu kunci Data B, sedangkan Transaksi 2 mengunci Data B dan menunggu kunci Data A. Keduanya saling memblokir selamanya hingga DBMS mendeteksi dan membatalkan salah satunya." },

            // Design (New 21-30)
            { id: "design-21", category: "design", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Color Palette' dalam UI design?", answers: ["Kumpulan warna pilihan yang digunakan secara konsisten di seluruh aplikasi", "Alat untuk mencampur warna cat fisik", "Kode HTML untuk merender gradasi warna", "Metode untuk mengompres asset gambar desain"], correct: 0, hint: "Berhubungan dengan identitas visual dan harmoni warna.", explanation: "Color palette adalah sekumpulan warna yang dipilih secara terencana untuk membangun identitas visual produk dan menjaga konsistensi antarmuka." },
            { id: "design-22", category: "design", difficulty: "easy", question: "Di bawah ini yang merupakan pengertian terdekat dari 'Button Hover State' adalah?", answers: ["Perubahan visual tombol saat kursor mouse diarahkan di atasnya", "Ukuran tombol saat ditekan oleh jari di layar HP", "Waktu yang dibutuhkan tombol untuk memicu fungsi klik", "Deskripsi tombol bagi pembaca layar disabilitas"], correct: 0, hint: "Umpan balik visual sebelum tombol diklik.", explanation: "Hover state memberikan feedback visual kepada pengguna bahwa elemen tersebut interaktif dan siap diklik saat kursor berada di atasnya." },
            { id: "design-23", category: "design", difficulty: "medium", question: "Mengapa penggunaan ruang kosong (whitespace) penting dalam desain antarmuka?", answers: ["Meningkatkan keterbacaan, fokus visual, dan kenyamanan mata pengguna saat memindai konten", "Mengurangi ukuran download file HTML halaman web", "Mempercepat waktu rendering elemen CSS di browser", "Agar developer bisa menulis kode lebih sedikit"], correct: 0, hint: "Memberi ruang bernapas bagi elemen desain.", explanation: "Whitespace (ruang negatif) membantu mengelompokkan elemen terkait, menegaskan visual hierarchy, dan membuat desain tidak terasa penuh atau membingungkan." },
            { id: "design-24", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'User Persona'?", answers: ["Representasi fiktif karakter pengguna target berdasarkan data riset riil", "Daftar hak akses pengguna di dalam database", "Foto profil pengguna yang dipasang di halaman dasbor", "Gaya penulisan microcopy pada tombol aplikasi"], correct: 0, hint: "Profil karakter yang merangkum tujuan, kebutuhan, dan kendala pengguna.", explanation: "User Persona merangkum karakteristik, perilaku, kebutuhan, dan rasa frustrasi dari kelompok pengguna target guna membantu tim desain mengambil keputusan yang berpusat pada manusia." },
            { id: "design-25", category: "design", difficulty: "medium", question: "Apa perbedaan utama antara wireframe low-fidelity dan prototype high-fidelity?", answers: ["Low-fidelity fokus pada struktur kasar tanpa warna, high-fidelity menyertakan detail visual dan interaksi mirip produk asli", "Low-fidelity dibuat di kertas, high-fidelity hanya bisa di-code", "Low-fidelity digunakan untuk backend, high-fidelity untuk frontend", "Low-fidelity tidak diuji ke user, high-fidelity wajib diuji"], correct: 0, hint: "Pikirkan tentang detail visual dan interaktivitas.", explanation: "Wireframe low-fidelity menyusun layout struktural cepat tanpa estetika warna/font. Prototype high-fidelity menyajikan visual final lengkap dengan interaksi tombol, animasi, dan alur transisi nyata." },
            { id: "design-26", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan prinsip 'Aesthetic-Usability Effect'?", answers: ["Pengguna cenderung menganggap desain yang estetis lebih mudah digunakan dibanding yang kurang estetis", "Kecepatan muat halaman web yang cantik selalu lebih cepat", "Desain yang buruk secara visual otomatis ditolak oleh browser", "Desainer harus selalu menggunakan warna hijau untuk status sukses"], correct: 0, hint: "Hubungan keindahan visual dengan persepsi kenyamanan pakai.", explanation: "Aesthetic-Usability Effect menunjukkan bahwa keindahan visual memengaruhi persepsi pengguna sehingga mereka cenderung lebih toleran terhadap kendala kegunaan minor karena menyukai tampilan produk." },
            { id: "design-27", category: "design", difficulty: "hard", question: "Bagaimana cara merancang navigasi untuk memenuhi standar WCAG 2.1 bagi pengguna screen reader?", answers: ["Menyediakan landmark semantik yang jelas dan memastikan urutan fokus keyboard yang logis", "Menghapus semua tombol drop-down navigasi", "Membuat menu navigasi selalu menggunakan ikon gambar tanpa teks", "Mengharuskan pengguna menggunakan mouse untuk berpindah menu"], correct: 0, hint: "Aksesibilitas bagi pengguna tanpa visual/tikus.", explanation: "Standar WCAG mewajibkan struktur HTML semantik (nav, header) dan urutan navigasi keyboard (tabindex) yang logis agar pembaca layar dapat membaca menu dengan teratur." },
            { id: "design-28", category: "design", difficulty: "easy", question: "Apa fungsi utama dari logo dalam bar navigasi atas website?", answers: ["Sebagai identitas merek dan jalan pintas navigasi untuk kembali ke beranda", "Menyimpan file cache halaman web", "Menampilkan animasi selamat datang kepada pengguna", "Menghubungkan halaman web dengan server basis data"], correct: 0, hint: "Konvensi umum saat logo diklik.", explanation: "Secara konvensi, logo di pojok kiri atas navbar berfungsi memperkuat identitas brand dan menjadi tombol pintas instan untuk kembali ke halaman utama (home)." },
            { id: "design-29", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Mobile-First Design'?", answers: ["Strategi mendesain untuk layar terkecil (mobile phone) terlebih dahulu sebelum merancang untuk layar yang lebih besar", "Mewajibkan pengguna membuka aplikasi hanya lewat handphone", "Membuat ukuran tombol navigasi selalu sebesar jempol tangan", "Desain yang tidak memerlukan koneksi internet di smartphone"], correct: 0, hint: "Mulai dari batasan ruang terkecil.", explanation: "Mobile-first memaksa desainer fokus pada fitur dan konten paling inti karena keterbatasan ruang layar smartphone, sebelum kemudian memperluas layout ke versi desktop (progressive enhancement)." },
            { id: "design-30", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Mental Model' pengguna dalam UX?", answers: ["Asumsi dan keyakinan pengguna tentang cara kerja suatu sistem berdasarkan pengalaman masa lalu mereka", "Algoritma AI untuk memprediksi suasana hati pengguna aplikasi", "Panduan gaya warna yang dibuat oleh desainer produk", "Sistem klasifikasi tingkat fokus pengguna saat melakukan testing"], correct: 0, hint: "Bagaimana pengguna 'berpikir' sistem Anda akan bekerja.", explanation: "Mental model adalah peta kognitif pengguna tentang bagaimana suatu produk digital bekerja. Desain yang baik menyelaraskan antarmuka dengan mental model pengguna agar sistem mudah dipahami tanpa instruksi rumit." },

            // Analytics (New 21-30)
            { id: "analytics-21", category: "analytics", difficulty: "easy", question: "Apakah kepanjangan dari ROI dalam analisis bisnis?", answers: ["Return on Investment", "Rate of Interest", "Real Organization Income", "Revenue of Industry"], correct: 0, hint: "Mengukur efisiensi laba dari investasi yang dikeluarkan.", explanation: "ROI (Return on Investment) adalah rasio keuangan yang membandingkan laba bersih yang diperoleh dengan biaya investasi yang telah dikeluarkan." },
            { id: "analytics-22", category: "analytics", difficulty: "easy", question: "Apa arti dari metrik Bounce Rate pada analisis website?", answers: ["Persentase pengunjung yang langsung keluar setelah membuka satu halaman saja tanpa interaksi lanjutan", "Kecepatan tombol memantul kembali setelah diklik", "Persentase data transaksi database yang gagal disimpan", "Jumlah pengguna yang memblokir notifikasi aplikasi"], correct: 0, hint: "Pengunjung datang lalu langsung pergi.", explanation: "Bounce rate mengukur pengunjung tunggal yang mendarat di halaman web Anda dan langsung meninggalkannya tanpa memicu aksi/klik ke halaman lain di situs tersebut." },
            { id: "analytics-23", category: "analytics", difficulty: "medium", question: "Apa kegunaan dari visualisasi histogram dalam analisis data?", answers: ["Menampilkan distribusi frekuensi dari data numerik kontinu", "Melacak tren penjualan mingguan selama setahun", "Menghubungkan titik koordinat lokasi pelanggan di peta", "Membandingkan persentase kontribusi kategori produk"], correct: 0, hint: "Melihat pola penyebaran dan kerapatan data angka.", explanation: "Histogram mengelompokkan data numerik ke dalam bin (rentang interval) untuk memvisualisasikan bentuk sebaran data, seperti normal, menceng, atau memiliki banyak puncak." },
            { id: "analytics-24", category: "analytics", difficulty: "medium", question: "Bagaimana rumus dasar menghitung Conversion Rate pendaftaran pengguna?", answers: ["(Jumlah pendaftaran / Jumlah total pengunjung unik) * 100", "(Total pengunjung / Jumlah pendaftaran) * 100", "(Jumlah pendaftaran * Biaya server) / 100", "(Pendapatan kotor - Pengeluaran klan) * 100"], correct: 0, hint: "Persentase aksi sukses terhadap total peluang.", explanation: "Conversion rate dihitung dengan membagi jumlah tindakan sukses (konversi) dengan total audiens yang terpapar (pengunjung), lalu dikalikan 100." },
            { id: "analytics-25", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan Cohort Retention Analysis?", answers: ["Mengamati persentase kelompok pengguna (kohort) yang tetap aktif menggunakan produk seiring berjalannya waktu", "Menghitung rata-rata pengeluaran iklan per bulan", "Menganalisis performa server database di jam-jam sibuk", "Membandingkan rating aplikasi di Android Play Store vs iOS App Store"], correct: 0, hint: "Cohort dihubungkan dengan retensi loyalitas pengguna.", explanation: "Analisis retensi kohort membagi pengguna berdasarkan waktu mulai mereka (misal: pendaftar bulan Januari) lalu melacak berapa persen dari kelompok tersebut yang kembali menggunakan aplikasi di minggu/bulan berikutnya." },
            { id: "analytics-26", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Statistical Power' dalam eksperimen A/B testing?", answers: ["Probabilitas eksperimen berhasil mendeteksi efek perbedaan yang nyata jika efek tersebut memang ada", "Jumlah total server yang dikerahkan untuk memproses data eksperimen", "Persentase varian B yang lebih unggul dibanding kontrol A", "Kecepatan algoritma statistika dalam menyaring data duplikat"], correct: 0, hint: "Kemampuan menghindari kesalahan Type II (False Negative).", explanation: "Statistical power (kekuatan statistik, biasanya ditargetkan 80%) adalah probabilitas menolak hipotesis nol dengan benar ketika hipotesis alternatif benar. Power rendah rentan gagal mendeteksi perubahan produk yang sebenarnya bermanfaat." },
            { id: "analytics-27", category: "analytics", difficulty: "hard", question: "Apa risiko dari fenomena 'Simpson's Paradox' dalam analisis data bisnis?", answers: ["Sebuah tren yang terlihat konsisten dalam kelompok data terpisah dapat terbalik atau hilang saat data digabungkan", "Grafik visualisasi data mengalami distorsi ukuran di layar mobile", "Rata-rata data bernilai negatif akibat outlier ekstrem", "Algoritma A/B testing terhenti akibat data sampel terlalu sedikit"], correct: 0, hint: "Efek variabel pengganggu (confounding variable) saat agregasi data.", explanation: "Paradoks Simpson terjadi ketika hubungan antara dua variabel berbalik arah atau hilang saat data dianalisis per kelompok dibanding saat seluruh data digabungkan, memicu kesalahan fatal dalam pengambilan keputusan jika analis mengabaikan pengelompokan yang relevan." },
            { id: "analytics-28", category: "analytics", difficulty: "easy", question: "Manakah jenis grafik yang paling cocok untuk menampilkan tren data penjualan bulanan selama 3 tahun terakhir?", answers: ["Line Chart (Grafik Garis)", "Pie Chart (Grafik Lingkaran)", "Scatter Plot", "Treemap"], correct: 0, hint: "Paling baik untuk visualisasi perubahan kontinu terhadap waktu.", explanation: "Line chart sangat efektif untuk menampilkan data deret waktu (time-series) guna melihat arah tren, fluktuasi, dan pola musiman." },
            { id: "analytics-29", category: "analytics", difficulty: "medium", question: "Apakah perbedaan utama antara data kualitatif dan data kuantitatif?", answers: ["Kualitatif berbentuk deskripsi kata/pengalaman, kuantitatif berbentuk angka yang dapat diukur secara statistik", "Kualitatif dianalisis oleh komputer, kuantitatif dianalisis secara manual oleh manusia", "Kualitatif selalu lebih akurat daripada kuantitatif", "Kualitatif disimpan di SQL, kuantitatif disimpan di Excel"], correct: 0, hint: "Kualitas (sifat) vs Kuantitas (jumlah).", explanation: "Data kualitatif bersifat non-numerik (seperti transkrip wawancara) untuk memahami alasan. Data kuantitatif bersifat numerik (seperti jumlah klik) untuk mengukur volume." },
            { id: "analytics-30", category: "analytics", difficulty: "hard", question: "Apakah kegunaan utama dari analisis regresi linear dalam Business Analytics?", answers: ["Memodelkan hubungan dan memprediksi nilai variabel dependen berdasarkan satu atau lebih variabel independen", "Membagi database menjadi beberapa tabel yang ter-normalisasi", "Menghapus duplikasi baris data secara otomatis di database", "Membandingkan preferensi warna tombol UI bagi pengguna baru"], correct: 0, hint: "Membentuk persamaan garis Y = a + bX untuk forecasting.", explanation: "Regresi linear digunakan untuk mempelajari hubungan linier antara variabel sebab (independen) dan variabel akibat (dependen) guna memprediksi nilai variabel akibat di masa depan." },

            // Web (New 21-30)
            { id: "web-21", category: "web", difficulty: "easy", question: "Apakah kepanjangan dari DOM dalam JavaScript browser?", answers: ["Document Object Model", "Digital Output Manager", "Data Object Memory", "Domain Operation Module"], correct: 0, hint: "Representasi struktur pohon halaman web oleh browser.", explanation: "DOM (Document Object Model) adalah API untuk dokumen HTML/XML yang representasikan struktur halaman sebagai pohon objek yang dapat dimanipulasi dengan JavaScript." },
            { id: "web-22", category: "web", difficulty: "easy", question: "Tag HTML manakah yang digunakan untuk menyisipkan gambar di halaman web?", answers: ["<img>", "<picture-file>", "<src>", "<image>"], correct: 0, hint: "Tag tunggal (self-closing) yang membutuhkan atribut src.", explanation: "Tag <img> digunakan untuk menampilkan gambar, dengan atribut src untuk menentukan lokasi file gambar." },
            { id: "web-23", category: "web", difficulty: "medium", question: "Apa kegunaan utama dari atribut CSS 'z-index'?", answers: ["Mengontrol urutan tumpukan elemen secara vertikal di layar (elemen mana yang berada di depan/atas lainnya)", "Mengatur tingkat pembesaran elemen (zoom level)", "Mengubah kecepatan efek animasi transisi elemen", "Mengatur koordinat posisi elemen secara horizontal"], correct: 0, hint: "Menentukan tumpukan sumbu Z elemen yang diposisikan.", explanation: "z-index mengontrol urutan rendering 3D (tumpukan tumpang tindih) elemen web yang memiliki properti position (seperti absolute atau relative)." },
            { id: "web-24", category: "web", difficulty: "medium", question: "Bagaimana cara menghentikan aksi bawaan dari sebuah form submit di browser menggunakan JavaScript?", answers: ["event.preventDefault()", "event.stopPropagation()", "return false;", "form.stopSubmit()"], correct: 0, hint: "Mencegah perilaku bawaan browser (reload halaman).", explanation: "event.preventDefault() menginstruksikan browser untuk tidak menjalankan aksi default (seperti reload halaman saat submit form atau navigasi saat link diklik)." },
            { id: "web-25", category: "web", difficulty: "medium", question: "Apakah yang dimaksud dengan 'CSS Custom Properties'?", answers: ["Variabel CSS yang diawali dengan tanda '--' untuk menyimpan nilai visual yang dapat digunakan ulang", "Font kustom yang diunduh dari server pihak ketiga", "Aturan penulisan layout CSS khusus untuk browser Safari", "Framework CSS kustom yang dibuat sendiri oleh developer"], correct: 0, hint: "Variabel bawaan CSS native.", explanation: "CSS Custom Properties (sering disebut variabel CSS) ditulis dengan format --nama-variabel dan dipanggil menggunakan fungsi var(--nama-variabel), mempermudah manajemen warna dan ukuran." },
            { id: "web-26", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Hydration' dalam framework rendering web modern?", answers: ["Proses melampirkan event listener JavaScript ke HTML statis yang di-render oleh server agar menjadi interaktif di browser", "Mengompres script JS agar ukurannya lebih ringan saat diunduh", "Proses membersihkan memory browser dari cache file gambar lama", "Menghubungkan aplikasi frontend ke database SQL secara langsung"], correct: 0, hint: "Menghidupkan HTML mati yang dikirim dari server.", explanation: "Dalam SSR (Server-Side Rendering) atau SSG (Static Site Generation), server mengirimkan halaman HTML statis tanpa event listener. Hydration adalah proses di sisi client di mana library/framework (seperti React) memetakan DOM dan mengaktifkan interaktivitas JavaScript-nya." },
            { id: "web-27", category: "web", difficulty: "hard", question: "Bagaimana cara kerja Service Worker dalam Progressive Web App (PWA)?", answers: ["Berjalan sebagai script latar belakang (thread terpisah) untuk mengelola cache jaringan, mendukung offline, dan push notification", "Mempercepat kueri database SQL dengan kompresi data JSON", "Mengubah tampilan stylesheet CSS secara otomatis sesuai resolusi layar", "Mengamankan password pengguna di server hosting"], correct: 0, hint: "Proxy jaringan di browser yang berjalan di luar thread UI utama.", explanation: "Service Worker adalah script yang berjalan di latar belakang browser, bertindak sebagai proxy jaringan yang dapat memotong request, menyajikan konten dari cache saat offline, serta menerima push notification." },
            { id: "web-28", category: "web", difficulty: "easy", question: "Manakah deklarasi DOCTYPE yang benar untuk HTML5?", answers: ["<!DOCTYPE html>", "<!DOCTYPE HTML5>", "<!DOCTYPE html PUBLIC '-//W3C//DTD HTML 5.0//EN'>", "<html>"], correct: 0, hint: "Deklarasi modern yang sangat pendek.", explanation: "Deklarasi <!DOCTYPE html> di awal dokumen memberi tahu browser bahwa dokumen tersebut ditulis menggunakan standar HTML5." },
            { id: "web-29", category: "web", difficulty: "medium", question: "Apakah fungsi utama dari CSS Media Query?", answers: ["Menerapkan aturan gaya CSS yang berbeda berdasarkan karakteristik perangkat, seperti lebar layar browser", "Memutar file audio atau video secara langsung di dalam kode CSS", "Menghubungkan file stylesheet eksternal ke dalam dokumen HTML", "Mengirimkan data analitik lebar layar ke server backend"], correct: 0, hint: "Kunci utama pembuatan layout responsif (responsive web design).", explanation: "Media Query memungkinkan kita menetapkan breakpoint (misal: @media (max-width: 768px)) untuk mengubah tata letak halaman web agar optimal di layar smartphone, tablet, maupun monitor desktop." },
            { id: "web-30", category: "web", difficulty: "hard", question: "Apakah perbedaan utama antara SSR (Server-Side Rendering) dan CSR (Client-Side Rendering)?", answers: ["SSR membuat HTML lengkap di server sebelum dikirim ke browser, CSR mengirimkan dokumen kosong dan merender konten di browser lewat JavaScript", "SSR ditulis dengan Python, CSR ditulis dengan PHP", "SSR tidak mendukung optimasi SEO, CSR sangat ramah SEO", "SSR memuat data lebih lambat pada transisi halaman dibanding CSR"], correct: 0, hint: "Pikirkan di mana proses pembentukan HTML dilakukan.", explanation: "Pada SSR, server merender HTML lengkap berisi data sehingga browser langsung menampilkannya (bagus untuk SEO & FCP). Pada CSR, browser menerima HTML kosong, mengunduh file JS raksasa, lalu JS tersebut baru merender antarmuka di sisi client." },

            // Cyber (New 21-30)
            { id: "cyber-21", category: "cyber", difficulty: "easy", question: "Apakah yang dimaksud dengan virus komputer?", answers: ["Program berbahaya yang mereplikasi dirinya sendiri dengan menyisipkan kode ke file atau program lain", "Kerusakan fisik pada kabel monitor akibat panas berlebih", "Pesan spam penawaran iklan yang muncul di email", "Kondisi saat RAM komputer penuh akibat menjalankan game berat"], correct: 0, hint: "Menyebar dengan menempel pada inang/program lain.", explanation: "Virus komputer adalah jenis malware yang membutuhkan program inang aktif untuk menyebar dan menginfeksi file lain di sistem komputer." },
            { id: "cyber-22", category: "cyber", difficulty: "easy", question: "Mengapa kita tidak boleh menuliskan password di selembar kertas yang ditempel di monitor?", answers: ["Karena kertas tersebut dapat dilihat dan dibaca dengan mudah oleh siapa saja yang lewat (shoulder surfing)", "Karena tinta kertas dapat merusak layar monitor fisik", "Karena browser tidak bisa membaca password dari kertas", "Karena password menjadi tidak valid jika ditulis manual"], correct: 0, hint: "Keamanan fisik dari pandangan orang lain di sekitar.", explanation: "Menempelkan password secara fisik di tempat terbuka melanggar prinsip keamanan dasar karena siapa pun yang memiliki akses fisik ke ruangan tersebut dapat mencuri kredensial Anda." },
            { id: "cyber-23", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan kerentanan CSRF (Cross-Site Request Forgery)?", answers: ["Serangan yang menipu browser korban yang ter-autentikasi untuk mengirimkan request berbahaya tanpa izin ke aplikasi web", "Penyisipan skrip JavaScript berbahaya ke dalam database aplikasi", "Proses menebak password admin secara berulang-ulang menggunakan bot", "Menghapus database server dengan memotong jalur koneksi SSL"], correct: 0, hint: "Memanfaatkan kredensial aktif korban (seperti cookie sesi) untuk melakukan aksi ilegal.", explanation: "CSRF mengeksploitasi kepercayaan situs web terhadap browser pengguna. Penyerang memicu browser korban untuk mengirimkan request (misal transfer dana atau ganti password) ke aplikasi web target tempat korban sudah login." },
            { id: "cyber-24", category: "cyber", difficulty: "medium", question: "Apa fungsi utama dari sertifikat SSL/TLS pada sebuah website?", answers: ["Membuktikan identitas kepemilikan website dan mengaktifkan koneksi HTTPS terenkripsi", "Mempercepat waktu loading asset gambar halaman web", "Mencegah penyerang menyalin artikel buatan kita", "Memastikan database SQL tidak bisa menerima input kosong"], correct: 0, hint: "Mengubah ikon gembok di browser menjadi terkunci.", explanation: "SSL/TLS memverifikasi bahwa server web adalah pemilik sah domain tersebut dan mengenkripsi seluruh pertukaran data antara browser dan server guna mencegah intersepsi." },
            { id: "cyber-25", category: "cyber", difficulty: "medium", question: "Mengapa kita harus berhati-hati saat menggunakan jaringan WiFi publik tanpa password di bandara atau kafe?", answers: ["Trafik data kita berisiko diintip dan dicuri oleh penyerang menggunakan serangan Man-in-the-Middle", "Kapasitas RAM handphone kita bisa cepat habis otomatis", "WiFi tanpa password selalu memiliki kecepatan unduh yang sangat lambat", "Browser kita akan memblokir seluruh akses ke website HTTPS"], correct: 0, hint: "Jaringan tidak terenkripsi memungkinkan penyadapan paket data.", explanation: "WiFi publik tanpa password tidak mengenkripsi paket data lokal. Penyerang di jaringan yang sama dapat merekam aktivitas internet Anda, menyadap token login, atau membelokkan domain (DNS poisoning)." },
            { id: "cyber-26", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Salt' dalam proses penyimpanan hashing password?", answers: ["Nilai acak unik yang digabungkan dengan password sebelum di-hash untuk mencegah serangan Rainbow Table", "Bumbu dapur untuk membersihkan debu fisik pada server hosting", "Kunci enkripsi asimetris yang dibagikan ke browser pengguna", "Proses kompresi file database agar hemat storage"], correct: 0, hint: "Menjamin hash unik meskipun dua pengguna memiliki password yang sama.", explanation: "Salt ditambahkan ke password sebelum dimasukkan ke fungsi hash. Ini memastikan bahwa meskipun dua pengguna memiliki password yang sama (misal: 'rahasia123'), nilai hash yang disimpan di database akan berbeda, sehingga mempersulit peretas menggunakan tabel pencarian hash pra-hitung (Rainbow Tables)." },
            { id: "cyber-27", category: "cyber", difficulty: "hard", question: "Bagaimana cara kerja serangan 'Buffer Overflow'?", answers: ["Menulis data melebihi kapasitas memori buffer, menimpa alamat instruksi eksekusi berikutnya untuk menjalankan kode penyerang", "Mengirimkan email spam dalam jumlah besar ke inbox server korporat", "Memutus kabel listrik utama datacenter untuk merusak harddisk", "Mengisi tabel database SQL dengan baris data kosong secara terus-menerus"], correct: 0, hint: "Melampaui batas alokasi variabel memori di stack/heap.", explanation: "Buffer overflow terjadi ketika program menulis data ke buffer memori melebihi ukuran alokasi aslinya. Sisa data menimpa memori sebelahnya, termasuk instruksi pointer (EIP), memungkinkan penyerang mengarahkan program untuk mengeksekusi kode berbahaya (shellcode) mereka." },
            { id: "cyber-28", category: "cyber", difficulty: "easy", question: "Apa kegunaan dari software antivirus di komputer?", answers: ["Mendeteksi, memblokir, dan membersihkan infeksi malware atau file berbahaya", "Membuat kecepatan render animasi 3D lebih cepat", "Mencegah komputer dari kerusakan akibat jatuh", "Membantu melacak lokasi laptop jika hilang dicuri"], correct: 0, hint: "Melindungi dari perangkat lunak berbahaya.", explanation: "Antivirus memindai file dan memori sistem untuk mendeteksi tanda tangan (signature) malware atau pola perilaku mencurigakan guna melindungi sistem dari kerusakan." },
            { id: "cyber-29", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'DDoS Attack'?", answers: ["Serangan membanjiri server dengan jutaan request palsu secara serentak dari banyak perangkat agar server down", "Menebak password user dengan kamus kata secara otomatis", "Pencurian fisik harddisk dari ruang server perusahaan", "Menyalin seluruh source code website secara diam-diam"], correct: 0, hint: "Distributed Denial of Service.", explanation: "DDoS membanjiri bandwidth atau sumber daya server target menggunakan jaringan komputer terinfeksi (Botnet) secara tersebar, menyebabkan layanan tidak bisa diakses pengguna sah." },
            { id: "cyber-30", category: "cyber", difficulty: "hard", question: "Dalam kriptografi, apakah perbedaan utama antara symmetric key dan asymmetric key?", answers: ["Symmetric menggunakan satu kunci rahasia untuk enkripsi dan dekripsi, asymmetric menggunakan sepasang kunci (publik dan privat)", "Symmetric hanya untuk data teks, asymmetric hanya untuk file biner", "Symmetric dijalankan di CPU, asymmetric dijalankan di GPU", "Symmetric kunci publiknya disebarkan ke publik, asymmetric kunci privatnya disebarkan ke publik"], correct: 0, hint: "Jumlah kunci rahasia yang terlibat dalam proses enkripsi/dekripsi.", explanation: "Enkripsi simetris menggunakan kunci rahasia yang sama oleh pengirim dan penerima (cepat, cocok untuk data besar). Enkripsi asimetris menggunakan Public Key untuk mengenkripsi dan Private Key yang berpasangan untuk mendekripsi (aman untuk pertukaran kunci)." },

            // Programming Advanced & Extended (31-50)
            { id: "programming-31", category: "programming", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Hoisting' dalam pemrograman JavaScript?", answers: ["Perilaku bawaan di mana deklarasi variabel dan fungsi dipindahkan ke atas cakupannya (scope) sebelum eksekusi kode", "Proses mengunggah file kode ke server hosting via FTP", "Teknik mempercepat perputaran loop pada array berukuran besar", "Mengubah tipe data string menjadi integer secara paksa"], correct: 0, hint: "Mengapa function declaration bisa dipanggil sebelum baris deklarasinya.", explanation: "Hoisting adalah mekanisme JavaScript di mana deklarasi (seperti var dan function declaration) diangkat ke puncak scope saat fase kompilasi/pembuatan execution context sebelum kode dieksekusi." },
            { id: "programming-32", category: "programming", difficulty: "easy", question: "Apa perbedaan utama antara operator '==' dan '===' dalam JavaScript?", answers: ["'==' memeriksa kesamaan nilai dengan koersi tipe data, sedangkan '===' memeriksa kesamaan nilai sekaligus kesamaan tipe data", "'==' hanya untuk angka, sedangkan '===' hanya untuk teks", "'==' berjalan lebih cepat daripada '===' dalam semua browser", "'===' digunakan untuk menugaskan nilai ke variabel tetap"], correct: 0, hint: "Strict equality vs loose equality.", explanation: "Operator === (strict equality check) tidak melakukan koersi tipe data; jika tipe datanya berbeda, langsung bernilai false. Operator == (loose equality check) akan mencoba menyamakan tipe data terlebih dahulu sebelum membandingkan." },
            { id: "programming-33", category: "programming", difficulty: "easy", question: "Apakah arti kata kunci 'const' saat mendeklarasikan variabel di JavaScript ES6?", answers: ["Mencegah penugasan ulang (reassignment) pada pengenal variabel tersebut setelah inisialisasi awal", "Membuat variabel menjadi konstanta matematis global yang tidak bisa dibaca di function lain", "Mengamankan variabel dari pembacaan oleh pihak ketiga di browser", "Mengalokasikan variabel ke memori GPU agar diproses paralel"], correct: 0, hint: "Variabel tidak dapat di-assign ulang dengan operator tanda sama dengan (=).", explanation: "const menciptakan referensi yang tidak dapat diubah ke sebuah nilai. Meskipun penugasan ulangnya dilarang, jika variabel tersebut berisi objek atau array, properti/elemen internalnya masih dapat dimodifikasi (mutable)." },
            { id: "programming-34", category: "programming", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Closure' dalam JavaScript?", answers: ["Kombinasi sebuah fungsi yang dibundel bersama referensi ke lingkungan sekitarnya (lexical scope), memungkinkan akses ke scope luar meskipun fungsi luar selesai dijalankan", "Penutupan koneksi database secara otomatis setelah query selesai", "Fungsi yang tidak memiliki return value dan langsung mengakhiri eksekusi", "Teknik mengunci variabel agar tidak bisa diakses oleh thread lain"], correct: 0, hint: "Fungsi dalam fungsi yang mengingat variabel dari fungsi induknya.", explanation: "Closure terjadi ketika fungsi inner mengingat dan tetap memiliki akses ke variabel di scope fungsi outer (parent), bahkan setelah eksekusi fungsi outer tersebut telah selesai dan dikembalikan." },
            { id: "programming-35", category: "programming", difficulty: "medium", question: "Dalam konsep Clean Architecture, mengapa lapisan domain/bisnis harus independen dari framework dan database?", answers: ["Agar logika bisnis inti tidak terpengaruh oleh perubahan teknologi eksternal, mudah diuji (testable), dan fleksibel berganti platform", "Agar program dapat berjalan tanpa menggunakan memori RAM", "Karena framework modern tidak mendukung penulisan logika bisnis rumit", "Agar kompilasi kode selalu memakan waktu di bawah 1 detik"], correct: 0, hint: "Separation of concerns & Dependency Inversion Principle.", explanation: "Lapisan domain berisi aturan bisnis utama aplikasi. Dengan memisahkan domain dari rincian infrastruktur (seperti SQL, UI, atau framework web), aplikasi menjadi sangat kokoh, mudah di-unit-test tanpa database palsu, dan mudah dirawat jangka panjang." },
            { id: "programming-36", category: "programming", difficulty: "medium", question: "Apakah fungsi utama dari Design Pattern 'Singleton'?", answers: ["Memastikan bahwa sebuah class hanya memiliki tepat satu instans (instance) dan menyediakan titik akses global ke instans tersebut", "Membagi satu class raksasa menjadi ribuan class kecil yang saling independen", "Mencegah class dari kemungkinan untuk diwarisi oleh subclass (final class)", "Menyembunyikan proses pembuatan objek kompleks di dalam factory method"], correct: 0, hint: "Satu objek tunggal untuk seluruh siklus hidup aplikasi.", explanation: "Singleton pattern lazim digunakan untuk mengelola resource yang harus dibagikan secara terpusat, seperti konfigurasi aplikasi, connection pool database, atau logger system." },
            { id: "programming-37", category: "programming", difficulty: "medium", question: "Apa kegunaan dari prinsip 'L' (Liskov Substitution Principle) dalam SOLID?", answers: ["Objek dari superclass harus dapat digantikan oleh objek dari subclass-nya tanpa merusak kebenaran program", "Setiap class hanya boleh memiliki maksimal satu fungsi atau tanggung jawab tunggal", "Class harus terbuka untuk perluasan (extension) namun tertutup untuk modifikasi (modification)", "Modul tingkat tinggi tidak boleh bergantung langsung pada modul tingkat rendah"], correct: 0, hint: "Subclass harus mematuhi kontrak dan ekspektasi dari superclass.", explanation: "Liskov Substitution Principle (LSP) menyatakan bahwa jika class B adalah turunan dari class A, maka kita harus bisa menggunakan B di mana pun A digunakan tanpa menyebabkan perilaku aneh atau error yang tak terduga." },
            { id: "programming-38", category: "programming", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Pure Function' dalam Functional Programming?", answers: ["Fungsi yang selalu menghasilkan output yang sama jika diberi input yang sama, serta tidak menghasilkan efek samping (side effects) apa pun", "Fungsi yang hanya menggunakan variabel global untuk semua perhitungannya", "Fungsi yang ditulis dalam satu baris kode tanpa tanda kurung kurawal", "Fungsi yang tidak dapat dipanggil oleh fungsi lain dalam program"], correct: 0, hint: "Deterministik dan tanpa modifikasi scope luar.", explanation: "Pure function tidak merubah variabel di luar scope-nya, tidak melakukan I/O eksternal (seperti modifikasi DOM atau fetch API), dan kembaliannya semata-mata dipicu oleh parameter argumen yang diberikan." },
            { id: "programming-39", category: "programming", difficulty: "hard", question: "Dalam analisis struktur data, apakah perbedaan utama antara Array dan Linked List?", answers: ["Array menyimpan elemen di alokasi memori berurutan (kontigu) sehingga akses indeks berbiaya O(1), sedangkan Linked List menyimpan elemen tersebar dengan pointer sehingga penyisipan/penghapusan lebih fleksibel", "Array hanya bisa menampung angka, sedangkan Linked List bisa menampung teks", "Array tidak memiliki indeks, sedangkan Linked List memiliki indeks otomatis", "Linked List memakan memori jauh lebih kecil dibanding Array berukuran sama"], correct: 0, hint: "Memori berurutan vs simpul (node) yang dihubungkan dengan pointer.", explanation: "Array unggul untuk pembacaan acak (random access) berkat alamat memori kontigu. Linked List unggul untuk penambahan dan penghapusan elemen di tengah antrean karena hanya perlu memodifikasi pointer referensi tanpa menggeser seluruh elemen." },
            { id: "programming-40", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Deadlock' dalam pemrograman multithread concurrency?", answers: ["Kondisi di mana dua atau lebih thread saling menunggu pelepasan resource kunci (lock) yang dipegang satu sama lain sehingga semua thread terhenti permanen", "Kondisi saat prosesor panas dan menurunkan frekuensi clock secara otomatis", "Kecepatan thread menurun akibat terlalu banyak variabel string dalam memori", "Penutupan aplikasi secara mendadak oleh sistem operasi akibat kurangnya daya baterai"], correct: 0, hint: "Saling tunggu tak berujung antar proses.", explanation: "Deadlock terjadi ketika Thread A memegang Lock 1 dan menunggu Lock 2, sementara pada saat yang sama Thread B memegang Lock 2 dan menunggu Lock 1. Tanpa intervensi, kedua thread akan terjebak selamanya." },
            { id: "programming-41", category: "programming", difficulty: "hard", question: "Apa keunggulan utama dari TypeScript dibandingkan dengan JavaScript murni?", answers: ["Menambahkan sistem pengetikan statis (static typing) yang mendeteksi kesalahan tipe data pada tahap kompilasi sebelum kode dieksekusi", "Membuat ukuran file bundle produksi 10 kali lebih kecil saat diunduh browser", "Menjalankan kode langsung di sistem operasi tanpa bantuan engine browser atau Node.js", "Menggantikan kebutuhan akan database relasional dalam aplikasi web"], correct: 0, hint: "Deteksi bug saat penulisan kode (compile-time vs runtime).", explanation: "TypeScript adalah superset dari JavaScript yang menambahkan static type analysis. Ini membantu developer menemukan bug tipe data saat masa pengembangan di IDE dan meningkatkan kejelasan dokumentasi kode." },
            { id: "programming-42", category: "programming", difficulty: "easy", question: "Apa fungsi dari blok 'try...catch...finally' dalam error handling?", answers: ["Menangani pengecualian (exception) agar program tidak crash, dengan blok finally yang pasti dijalankan terlepas terjadi error atau tidak", "Mencoba menjalankan perulangan sebanyak mungkin sampai memori habis", "Mengubah kesalahan sintaks (syntax error) menjadi kode yang benar secara otomatis", "Menyembunyikan pesan error dari catatan log developer"], correct: 0, hint: "Blok finally mengeksekusi pembersihan (cleanup) selalu.", explanation: "Blok try berisi kode yang berpotensi memicu error, catch menangani error tersebut jika muncul, dan finally akan selalu dieksekusi di akhir (misal untuk menutup koneksi atau menghapus loading state)." },
            { id: "programming-43", category: "programming", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Memoization' dalam optimasi performa?", answers: ["Teknik menyimpan hasil komputasi dari pemanggilan fungsi yang berat ke dalam cache berdasarkan argumen input agar tidak dihitung ulang jika inputnya sama", "Mencatat semua baris kode yang ditulis developer ke file log harian", "Menghapus variabel lama dari memori untuk memberi ruang bagi variabel baru", "Mengenkripsi hasil keluaran fungsi agar tidak bisa dibaca program lain"], correct: 0, hint: "Mengingat/mencatat hasil komputasi yang mahal.", explanation: "Memoization adalah bentuk caching khusus di mana fungsi mengingat (memoize) hasil dari perhitungan sebelumnya. Jika fungsi dipanggil lagi dengan parameter yang identik, hasil dari cache langsung dikembalikan dengan kecepatan O(1)." },
            { id: "programming-44", category: "programming", difficulty: "medium", question: "Apa kegunaan dari struktur data Hash Table (Map/Dictionary)?", answers: ["Menyimpan pasangan kunci-nilai (key-value) dengan pencarian, penambahan, dan penghapusan berbiaya rata-rata O(1)", "Mengurutkan data secara otomatis dari abjad Z ke A setiap kali ada perubahan", "Menyimpan hirarki folder dan file seperti pohon sistem operasi", "Menghubungkan komputer klien ke server database melalui protokol jaringan"], correct: 0, hint: "Pencarian super cepat menggunakan fungsi hash untuk memetakan key ke indeks array.", explanation: "Hash Table memetakan key ke indeks array menggunakan hash function. Hal ini memberikan akses data seketika (O(1) average case) tanpa harus menelusuri seluruh elemen satu per satu." },
            { id: "programming-45", category: "programming", difficulty: "hard", question: "Dalam arsitektur Event-Driven, apakah yang dimaksud dengan 'Event Sourcing'?", answers: ["Pola penyimpanan di mana state aplikasi tidak disimpan sebagai satu baris terkini saja, melainkan sebagai urutan riwayat seluruh kejadian (events) yang pernah terjadi sejak awal", "Mengirimkan notifikasi email otomatis ke pengguna setiap kali ada pembaruan produk", "Menghapus database setiap larut malam dan membangunnya kembali dari file log web", "Membatasi jumlah event klik mouse di browser agar aplikasi tidak lag"], correct: 0, hint: "Seperti buku besar akuntansi di mana setiap transaksi dicatat berurutan.", explanation: "Event Sourcing merekam setiap perubahan status sebagai event yang abadi (immutable). Status terkini diperoleh dengan memutar ulang (replaying) seluruh rangkaian event, memungkinkan audit trail sempurna dan time-travel debugging." },
            { id: "programming-46", category: "programming", difficulty: "medium", question: "Apa arti dari 'Big O Notation' O(N log N)?", answers: ["Kompleksitas waktu yang tumbuh sebanding dengan N dikalikan logaritma N, yang merupakan batas efisiensi terbaik untuk algoritma pengurutan berbasis perbandingan (seperti Merge Sort dan Quick Sort)", "Waktu eksekusi konstan yang tidak peduli berapa pun jumlah input data N", "Waktu eksekusi yang tumbuh secara eksponensial dan sangat lambat untuk data kecil", "Jumlah memori minimum yang dibutuhkan untuk mengkompilasi program"], correct: 0, hint: "Standar kecepatan untuk sorting algorithm modern.", explanation: "O(N log N) adalah efisiensi optimal bagi algoritma sorting umum (seperti Merge Sort, Quick Sort, dan Heap Sort). Ini jauh lebih efisien daripada O(N^2) seperti Bubble Sort ketika menangani data berjumlah besar." },
            { id: "programming-47", category: "programming", difficulty: "easy", question: "Manakah pernyataan yang benar mengenai konsep DRY (Don't Repeat Yourself)?", answers: ["Setiap potongan pengetahuan atau logika bisnis harus memiliki satu representasi yang tunggal dan tidak ambigu di dalam sistem agar mudah dirawat", "Developer tidak boleh menulis komentar lebih dari satu baris dalam satu file kode", "Variabel tidak boleh memiliki nama yang mengandung huruf berulang", "Program tidak boleh menggunakan perulangan (loop) lebih dari 3 kali"], correct: 0, hint: "Hindari duplikasi logika di banyak tempat.", explanation: "DRY bertujuan mengurangi duplikasi kode. Jika logika yang sama diulang di 10 tempat, maka saat logika itu berubah, kita harus memperbaiki 10 tempat tersebut yang berisiko tertinggal dan memicu bug." },
            { id: "programming-48", category: "programming", difficulty: "hard", question: "Apakah perbedaan antara Concurrency dan Parallelism?", answers: ["Concurrency adalah kemampuan menangani banyak tugas dengan mengatur waktu giliran (structure), sedangkan Parallelism adalah mengeksekusi banyak tugas secara bersamaan secara fisik di banyak core CPU sekaligus", "Concurrency hanya untuk bahasa JavaScript, sedangkan Parallelism hanya untuk bahasa Python", "Concurrency membutuhkan kartu grafis (GPU), sedangkan Parallelism hanya menggunakan harddisk", "Concurrency membuat program lebih lambat, sedangkan Parallelism selalu 100 kali lebih cepat"], correct: 0, hint: "Managing many things at once vs Doing many things at once.", explanation: "Menurut Rob Pike, Concurrency adalah tentang komposisi/struktur program untuk mengelola banyak hal secara independen (bahkan di 1 core CPU via context switching), sedangkan Parallelism adalah eksekusi simultan di multi-core perangkat keras." },
            { id: "programming-49", category: "programming", difficulty: "medium", question: "Apa manfaat utama dari penulisan Unit Testing dalam siklus pengembangan software?", answers: ["Memverifikasi bahwa setiap unit kecil fungsi bekerja sesuai spesifikasi, memberikan jaring pengaman saat melakukan refactoring kode di masa depan", "Menjamin aplikasi 100% bebas dari segala jenis bug visual dan jaringan", "Mengurangi ukuran file aplikasi sebelum diunggah ke app store", "Menggantikan peran spesialis QA (Quality Assurance) sepenuhnya"], correct: 0, hint: "Pengujian otomatis pada tingkat function atau class tunggal.", explanation: "Unit test menguji komponen terkecil secara terisolasi. Keuntungan terbesarnya adalah developer dapat mendeteksi regresi (kerusakaan pada fitur lama) secara instan sewaktu merombak atau menambah fitur baru." },
            { id: "programming-50", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Garbage Collection' (GC) pada runtime bahasa pemrograman modern?", answers: ["Proses otomatis yang mendeteksi dan membebaskan alokasi memori heap dari objek yang tidak lagi dapat dijangkau (unreachable) oleh program", "Penghapusan file temporary dan cache browser secara otomatis setiap minggu", "Fitur IDE untuk menghapus baris komentar yang sudah tidak relevan", "Pembersihan tabel database dari pengguna yang sudah tidak aktif login"], correct: 0, hint: "Pembersih otomatis untuk mencegah memory leak.", explanation: "Garbage Collection memantau objek di memori. Jika sebuah objek tidak lagi direferensikan oleh bagian mana pun dari program (seperti rantai referensi putus), GC akan mengklaim kembali memori tersebut agar bisa dipakai ulang." },

            // Database & SQL Extended (31-50)
            { id: "database-31", category: "database", difficulty: "easy", question: "Apakah kepanjangan dari ACID dalam konsep transaksi database relasional?", answers: ["Atomicity, Consistency, Isolation, Durability", "Automatic, Concurrent, Integrated, Dynamic", "Allocation, Compression, Indexing, Deletion", "Asynchronous, Clustered, Isolated, Distributed"], correct: 0, hint: "Empat pilar keandalan transaksi database.", explanation: "ACID menjamin bahwa transaksi database diproses dengan aman: Atomicity (tuntas semua atau batal semua), Consistency (menjaga aturan validitas), Isolation (transaksi bersamaan tidak saling kacau), dan Durability (data tersimpan permanen meski mati listrik)." },
            { id: "database-32", category: "database", difficulty: "easy", question: "Apa fungsi dari Foreign Key dalam tabel database?", answers: ["Membentuk hubungan (relasi) antar tabel dengan merujuk pada Primary Key di tabel lain serta menjaga integritas referensial", "Menandai kolom yang berisi data sandi rahasia atau kunci enkripsi", "Mempercepat pengurutan data dari huruf A sampai Z secara otomatis", "Menghapus tabel cabang jika tabel utama mengalami perubahan nama"], correct: 0, hint: "Kunci tamu penghubung relasi.", explanation: "Foreign Key memastikan bahwa nilai yang dimasukkan di kolom tersebut harus sesuai dengan nilai Primary Key yang ada di tabel induknya, mencegah keberadaan data yatim (orphaned records)." },
            { id: "database-33", category: "database", difficulty: "medium", question: "Apakah perbedaan antara LEFT JOIN dan INNER JOIN dalam query SQL?", answers: ["INNER JOIN hanya menampilkan baris yang berpasangan di kedua tabel, sedangkan LEFT JOIN menampilkan semua baris dari tabel kiri beserta pasangan tabel kanan (atau NULL jika tidak ada pasangan)", "INNER JOIN menggabungkan kolom, sedangkan LEFT JOIN menggabungkan baris dari atas ke bawah", "INNER JOIN bekerja lebih lambat 10 kali lipat dibanding LEFT JOIN", "LEFT JOIN hanya bisa digunakan jika tabel memiliki kurang dari 100 baris"], correct: 0, hint: "Perhatikan bagaimana baris yang tidak memiliki kecocokan di tabel kedua ditangani.", explanation: "INNER JOIN memfilter hanya data yang cocok di kedua tabel. LEFT JOIN mempertahankan seluruh baris dari tabel pertama (kiri), dan mengisi kolom tabel kedua (kanan) dengan NULL apabila relasinya tidak ditemukan." },
            { id: "database-34", category: "database", difficulty: "medium", question: "Apa kegunaan utama dari Database Index (seperti B-Tree Index)?", answers: ["Mempercepat pencarian dan pengambilan data dengan menyediakan struktur pohon urut, sehingga query tidak perlu melakukan pencarian penuh (Full Table Scan)", "Mencegah pengguna lain mengakses database di luar jam kerja", "Mengompresi teks panjang menjadi format biner agar hemat ruang penyimpanan", "Menghapus baris data ganda (duplikat) secara otomatis setiap jam"], correct: 0, hint: "Layaknya indeks abjad di halaman belakang buku ensiklopedia.", explanation: "Tanpa indeks, database harus membaca setiap baris dari awal sampai akhir (Full Table Scan). Dengan indeks B-Tree, pencarian berlangsung dengan kompleksitas logaritmik O(log N) yang sangat cepat." },
            { id: "database-35", category: "database", difficulty: "medium", question: "Kapan kita sebaiknya menggunakan klausul GROUP BY dan HAVING dalam SQL?", answers: ["GROUP BY mengelompokkan baris dengan nilai sama untuk fungsi agregasi (COUNT, SUM), dan HAVING menyaring hasil setelah agregasi tersebut dihitung", "GROUP BY untuk mengurutkan abjad, HAVING untuk menghapus tabel", "GROUP BY hanya untuk tipe data tanggal, HAVING hanya untuk tipe data uang", "GROUP BY menggabungkan database, HAVING menyalin file cadangan"], correct: 0, hint: "WHERE memfilter baris sebelum agregasi, HAVING memfilter setelah agregasi.", explanation: "GROUP BY mengelompokkan data (misal per kategori). Setelah dikelompokkan dan dihitung (seperti SUM(salary)), kita tidak bisa memakai WHERE untuk memfilter hasil agregasi tersebut, melainkan harus menggunakan HAVING (misal HAVING SUM(salary) > 50000)." },
            { id: "database-36", category: "database", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Window Functions' (seperti ROW_NUMBER, RANK, OVER) dalam SQL?", answers: ["Fungsi yang melakukan kalkulasi melintasi sekelompok baris yang terkait dengan baris saat ini, tanpa mengelompokkannya menjadi satu baris tunggal seperti GROUP BY", "Fungsi untuk menampilkan antarmuka jendela popup grafis di dalam aplikasi klien database", "Fungsi yang membatasi waktu query maksimal 5 detik sebelum dibatalkan", "Fungsi untuk memotong string teks panjang menjadi potongan 10 karakter"], correct: 0, hint: "Menghitung nilai agregat/ranking namun tetap mempertahankan semua baris rincian asli.", explanation: "Window function (menggunakan OVER()) memungkinkan kita menghitung running total, ranking, atau moving average pada setiap baris individual tanpa menggabungkan baris-baris tersebut menjadi satu baris ringkasan seperti GROUP BY konvensional." },
            { id: "database-37", category: "database", difficulty: "hard", question: "Apakah pernyataan dari CAP Theorem untuk sistem database terdistribusi?", answers: ["Dalam sistem terdistribusi, kita hanya dapat menjamin maksimal dua dari tiga properti secara bersamaan: Consistency, Availability, dan Partition Tolerance", "Database harus selalu berkapasitas di atas 100 GB agar bisa disebut terdistribusi", "Setiap query SQL harus selesai diproses di bawah 1 milidetik untuk menjaga konsistensi", "Koneksi database harus menggunakan enkripsi SSL agar tahan terhadap kegagalan jaringan"], correct: 0, hint: "Pilih dua dari tiga: Konsisten, Selalu Tersedia, atau Tahan Partisi Jaringan.", explanation: "CAP Theorem (Brewer's Theorem) menegaskan bahwa saat terjadi partisi jaringan (P), sistem terdistribusi harus memilih antara membatalkan request demi menjaga data tetap identik di semua node (Consistency), atau tetap melayani request meski data mungkin belum tersinkronisasi (Availability)." },
            { id: "database-38", category: "database", difficulty: "easy", question: "Perintah SQL manakah yang termasuk dalam kategori DDL (Data Definition Language)?", answers: ["CREATE, ALTER, DROP, TRUNCATE", "SELECT, INSERT, UPDATE, DELETE", "GRANT, REVOKE", "COMMIT, ROLLBACK, SAVEPOINT"], correct: 0, hint: "Mendefinisikan atau merubah struktur skema/tabel, bukan memanipulasi isi datanya.", explanation: "DDL (Data Definition Language) berkaitan dengan skema database (misal membuat atau menghapus tabel). Sedangkan SELECT, INSERT, UPDATE, DELETE termasuk DML (Data Manipulation Language)." },
            { id: "database-39", category: "database", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Query Execution Plan' (EXPLAIN) saat mengoptimalkan SQL?", answers: ["Rencana langkah demi langkah yang dipilih oleh engine database (termasuk urutan join dan penggunaan indeks) untuk mengeksekusi sebuah query", "Daftar nama developer yang bertanggung jawab atas pembuatan tabel database", "Jadwal pencadangan (backup) otomatis yang berjalan setiap malam di server", "Konfigurasi jumlah maksimal koneksi yang diizinkan masuk ke server SQL"], correct: 0, hint: "Mengapa query kita lambat? Lihat bagaimana engine memprosesnya dengan EXPLAIN.", explanation: "Dengan menjalankan perintah EXPLAIN di depan query, database menampilkan execution plan. Kita bisa melihat apakah query tersebut melakukan Full Table Scan, indeks mana yang dipakai, dan di langkah mana biaya (cost) terbesar terjadi." },
            { id: "database-40", category: "database", difficulty: "hard", question: "Dalam desain arsitektur database berskala besar, apakah perbedaan antara Read Replicas dan Sharding?", answers: ["Read Replicas menyalin seluruh data ke server sekunder khusus untuk mendistribusikan beban baca, sedangkan Sharding memecah/membagi baris data ke beberapa server secara horizontal berdasarkan shard key", "Read Replicas untuk database SQL, sedangkan Sharding hanya untuk file Excel", "Read Replicas membagi data berdasarkan abjad, sedangkan Sharding menyalin semua data ke cloud", "Read Replicas membuat data menjadi terenkripsi, sedangkan Sharding membuka enkripsi data"], correct: 0, hint: "Replikasi = duplikasi lengkap untuk skala pembacaan. Sharding = pemecahan data untuk skala penyimpanan & penulisan.", explanation: "Read Replicas menduplikasi master database agar ribuan query SELECT bisa diparalelkan. Sharding memotong tabel raksasa (misal 1 miliar user) menjadi potongan kecil di banyak server terpisah agar kapasitas simpan dan penulisan tidak terbatas pada satu mesin." },
            { id: "database-41", category: "database", difficulty: "medium", question: "Apa keunggulan utama dari In-Memory Data Store seperti Redis dibandingkan database disk tradisional?", answers: ["Menyimpan data langsung di dalam memori RAM sehingga waktu respons pembacaan dan penulisan berada di kisaran sub-milidetik (sangat cepat)", "Tidak memerlukan listrik sama sekali untuk menyimpan data dalam jangka waktu 10 tahun", "Dapat menampung ukuran data tak terbatas tanpa perlu menambah kapasitas hardware", "Secara otomatis menulis ulang kode SQL menjadi struktur dokumen JSON"], correct: 0, hint: "Kecepatan akses RAM vs Harddisk/SSD.", explanation: "Redis menyimpan dataset di RAM, membuatnya ribuan kali lebih cepat dibanding pembacaan dari disk penyimpanan fisik. Sangat ideal untuk caching, session management, leaderboard, dan real-time pub/sub messaging." },
            { id: "database-42", category: "database", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Dirty Read' dalam tingkat isolasi transaksi (Isolation Level)?", answers: ["Kondisi di mana sebuah transaksi membaca data yang baru diubah oleh transaksi lain namun belum dilakukan COMMIT (berisiko data tersebut di-rollback)", "Membaca data dari tabel yang belum diberikan primary key oleh administrator", "Proses membaca data yang sudah terinfeksi oleh virus komputer", "Membaca baris data yang memiliki nilai NULL di semua kolomnya"], correct: 0, hint: "Membaca perubahan sementara dari transaksi yang belum tentu sah.", explanation: "Dirty Read terjadi pada isolation level terendah (Read Uncommitted). Jika Transaksi A merubah saldo dari 100 ke 500, lalu Transaksi B membaca nilai 500, tetapi kemudian Transaksi A melakukan ROLLBACK ke 100, maka nilai 500 yang dibaca B adalah data salah (dirty)." },
            { id: "database-43", category: "database", difficulty: "easy", question: "Apakah kegunaan dari perintah SQL TRUNCATE TABLE?", answers: ["Menghapus seluruh baris data dari dalam tabel secara cepat dan mereset auto-increment, tanpa menghapus struktur tabel itu sendiri", "Menghapus tabel beserta seluruh indeks, trigger, dan relasinya secara permanen dari skema database", "Mengubah tipe data seluruh kolom teks menjadi tipe integer", "Menyalin seluruh isi tabel ke dalam tabel arsip baru secara otomatis"], correct: 0, hint: "Lebih cepat dari DELETE FROM table, namun tidak mencatat riwayat per baris.", explanation: "TRUNCATE TABLE mengosongkan isi tabel secara efisien dengan mendeklarasikan ulang halaman data (bukan menghapus baris demi baris seperti DELETE). Struktur kolom dan tipe data tabel tetap utuh." },
            { id: "database-44", category: "database", difficulty: "medium", question: "Apa keunggulan utama dari paradigma NoSQL Document Store (seperti MongoDB) dibanding Relational SQL?", answers: ["Skema yang fleksibel dan dinamis (schema-less/JSON) memungkinkan penyimpanan data dengan struktur bervariasi tanpa migrasi tabel yang rumit", "Tidak membutuhkan kapasitas penyimpanan harddisk di server cloud", "Menjamin 100% bebas dari semua jenis duplikasi data di setiap dokumennya", "Selalu menghasilkan waktu query 1 milidetik terlepas dari seberapa rumit pencariannya"], correct: 0, hint: "Struktur dokumen berformat JSON/BSON yang fleksibel.", explanation: "Document Store seperti MongoDB menyimpan data sebagai dokumen BSON/JSON. Tiap dokumen di dalam koleksi yang sama dapat memiliki kolom atau atribut yang berbeda, sangat cocok untuk agile development dan data berskala besar dengan hirarki bersarang." },
            { id: "database-45", category: "database", difficulty: "hard", question: "Mengapa kita disarankan menggunakan Connection Pooling pada aplikasi backend yang terhubung ke database?", answers: ["Untuk menggunakan kembali (reuse) koneksi database yang sudah terbuka, menghindari biaya tinggi waktu CPU dan jaringan akibat membuat/menutup koneksi berulang kali pada tiap request", "Agar password database dapat dienkripsi secara otomatis menggunakan algoritma AES-256", "Untuk membatasi jumlah baris data yang dikembalikan oleh setiap query maksimal 10 baris", "Agar database tidak perlu melakukan pengecekan hak akses (permission) untuk setiap user"], correct: 0, hint: "Membuka koneksi TCP/socket baru membutuhkan biaya waktu transmisi yang mahal.", explanation: "Membuka koneksi fisik baru ke database membutuhkan proses handshake TCP/TLS dan autentikasi yang lambat. Connection pool mempertahankan sekumpulan koneksi aktif di latar belakang dan meminjamkannya ke request web, meningkatkan throughput aplikasi secara drastis." },
            { id: "database-46", category: "database", difficulty: "medium", question: "Apakah yang dimaksud dengan 'SQL Injection' dan bagaimana cara mencegahnya?", answers: ["Serangan menyisipkan perintah SQL berbahaya melalui input form; dicegah dengan menggunakan Parameterized Query atau Prepared Statements", "Serangan membanjiri server dengan jutaan paket pings; dicegah dengan memasang firewall router", "Pencurian file cadangan database dari server FTP; dicegah dengan mengganti port default", "Kerusakan file database akibat listrik mati mendadak; dicegah dengan memasang UPS"], correct: 0, hint: "Pisahkan antara string perintah SQL dengan data input pengguna menggunakan placeholder (?).", explanation: "SQL Injection memanfaatkan penggabungan string (string concatenation) mentah. Dengan Prepared Statements/Parameterized Query, engine database memperlakukan input pengguna secara mutlak sebagai data literal, bukan sebagai instruksi SQL yang dapat dieksekusi." },
            { id: "database-47", category: "database", difficulty: "hard", question: "Apakah perbedaan antara N+1 Query Problem dan cara mengatasinya menggunakan Eager Loading?", answers: ["N+1 terjadi saat aplikasi menjalankan 1 query untuk tabel induk dan N query terpisah untuk setiap baris anaknya; diatasi dengan Eager Loading (seperti JOIN atau IN clause) untuk mengambil semua data sekaligus", "N+1 adalah error saat tabel memiliki lebih dari 1 primary key; diatasi dengan menghapus kolom tambahan", "N+1 adalah kondisi saat database kehabisan nomor ID auto-increment; diatasi dengan merubah ke UUID", "N+1 adalah query yang berjalan lebih dari 1 menit; diatasi dengan memotong koneksi internet"], correct: 0, hint: "Masalah klasik pada ORM saat melompati relasi tabel di dalam perulangan loop.", explanation: "Jika kita membaca 100 artikel lalu melakukan loop untuk membaca komentar tiap artikel dengan query terpisah, kita mengeksekusi 1 + 100 = 101 query. Eager loading mengambil artikel beserta komentarnya dalam 1-2 query terpadu, mengurangi beban network luar biasa." },
            { id: "database-48", category: "database", difficulty: "medium", question: "Dalam database PostgreSQL atau MySQL, apakah fungsi dari tipe data JSON/JSONB?", answers: ["Menyimpan dan mengindeks struktur data semi-terstruktur langsung di dalam kolom relasional, memungkinkan kueri ke atribut internal dokumen JSON", "Mengubah seluruh tabel SQL menjadi file teks flat yang bisa dibuka di Notepad", "Menghapus kebutuhan akan primary key pada setiap baris data", "Membuat koneksi database menjadi dua kali lebih cepat secara permanen"], correct: 0, hint: "Menjembatani keunggulan SQL relasional dengan fleksibilitas NoSQL.", explanation: "Tipe data JSON/JSONB memungkinkan kolom database menampung objek JSON bersarang. PostgreSQL bahkan dapat membuat indeks GIN pada key internal JSONB, memungkinkan query kompleks pada properti JSON dengan performa tinggi." },
            { id: "database-49", category: "database", difficulty: "easy", question: "Apa fungsi perintah SQL ROLLBACK?", answers: ["Membatalkan seluruh perubahan yang dilakukan di dalam transaksi saat ini dan mengembalikan data ke kondisi sebelum transaksi dimulai", "Menyimpan seluruh perubahan secara permanen ke dalam harddisk server", "Menghapus seluruh pengguna yang sedang login ke database saat ini", "Mengulang eksekusi query yang gagal karena masalah putus jaringan"], correct: 0, hint: "Tombol 'Undo' darurat sebelum COMMIT dilakukan.", explanation: "Jika terjadi kesalahan, error logika, atau kegagalan sistem di pertengahan blok transaksi, perintah ROLLBACK memulihkan integritas data ke titik awal tepat sebelum transaksi dibuka." },
            { id: "database-50", category: "database", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Database Partitioning' (Range vs List vs Hash)?", answers: ["Membagi tabel berukuran raksasa menjadi beberapa partisi fisik terpisah berdasarkan kriteria nilai kolom tertentu guna meningkatkan performa pemeliharaan dan kueri", "Menyalin seluruh isi database ke 5 server cloud berbeda di benua yang berbeda", "Membatasi kuota penyimpanan harddisk untuk tiap developer yang bekerja di tim", "Mengubah tipe data kolom string panjang menjadi format kompresi ZIP"], correct: 0, hint: "Misalnya memecah tabel log transaksi berdasarkan rentang tahun/bulan.", explanation: "Partitioning memecah 1 tabel logis menjadi beberapa tabel fisik di balik layar (misal partisi per tahun 2024, 2025, 2026). Query yang mencari data tahun 2026 langsung memindai partisi 2026 saja (Partition Pruning), melewati data lama dengan sangat cepat." },

            // UI/UX Design Extended (31-50)
            { id: "design-31", category: "design", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Design Tokens' dalam sebuah Design System modern?", answers: ["Entitas terkecil penyimpan nilai desain visual (seperti warna #3B82F6, font-size 16px, spacing 8px) dalam format agnostik platform (JSON/Variables) untuk konsistensi di web, iOS, dan Android", "Token mata uang kripto yang digunakan untuk membeli lisensi aplikasi desain Figma", "Rahasia sandi login yang diberikan kepada desainer grafis baru di perusahaan", "Kumpulan foto stok gratis resolusi tinggi yang siap pakai untuk latar belakang banner"], correct: 0, hint: "Variabel inti yang menjadi dasar pembuatan komponen antarmuka.", explanation: "Design Tokens adalah representasi data dari keputusan desain visual. Dengan merubah token warna primary dari biru ke hijau di satu tempat, seluruh produk di web, iOS, dan Android dapat diperbarui secara konsisten tanpa menulis ulang kode statis." },
            { id: "design-32", category: "design", difficulty: "easy", question: "Mengapa konsistensi (Consistency) merupakan salah satu prinsip terpenting dalam UI/UX?", answers: ["Mengurangi beban kognitif pengguna karena mereka dapat memprediksi cara kerja antarmuka berdasarkan kebiasaan dan pola yang sudah dipelajari sebelumnya", "Membuat ukuran file gambar di aplikasi menjadi jauh lebih kecil", "Memastikan semua tombol memiliki warna merah terang agar mudah diklik", "Mencegah aplikasi dari kemungkinan terkena serangan virus komputer"], correct: 0, hint: "Tombol yang berfungsi sama harus terlihat dan berperilaku sama di setiap halaman.", explanation: "Konsistensi eksternal (mengikuti standar industri) dan internal (seragam dalam aplikasi) membuat pengguna merasa nyaman, mengurangi kesalahan operasi, dan mempercepat kurva pembelajaran produk." },
            { id: "design-33", category: "design", difficulty: "medium", question: "Menurut standar aksesibilitas WCAG 2.1 AA, berapakah rasio kontras warna minimum yang disarankan antara teks normal dan latar belakangnya?", answers: ["4.5 : 1 untuk teks ukuran normal, dan 3 : 1 untuk teks berukuran besar (18pt / 14pt bold)", "1 : 1 untuk semua jenis dan ukuran teks di layar smartphone", "10 : 1 hanya khusus untuk tombol yang memiliki animasi bergerak", "2 : 1 untuk teks berwarna abu-abu di atas latar belakang putih standar"], correct: 0, hint: "Rasio kontras mematuhi kenyamanan baca bagi penyandang gangguan penglihatan.", explanation: "WCAG 2.1 AA mensyaratkan rasio kontras minimal 4.5:1 untuk teks biasa (body text). Ini memastikan bahwa pengguna dengan penglihatan rendah atau buta warna sebagian tetap dapat membaca antarmuka dengan jelas tanpa ketegangan mata." },
            { id: "design-34", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Hick's Law' (Hick-Hyman Law) dalam psikologi UX?", answers: ["Waktu yang dibutuhkan seseorang untuk mengambil keputusan meningkat secara logaritmik seiring bertambahnya jumlah dan kompleksitas pilihan yang dihadapi", "Ukuran tombol harus selalu dibuat minimal 44x44 piksel agar mudah ditekan oleh jempol", "Pengguna hanya mampu mengingat 7 plus/minus 2 item informasi di memori jangka pendek", "Antarmuka yang terlihat estetik dan indah akan dianggap lebih mudah digunakan oleh pengguna"], correct: 0, hint: "Semakin banyak menu pilihan, semakin lama dan bingung pengguna memutuskan.", explanation: "Hick's Law menjelaskan mengapa menu yang terlalu padat atau formulir dengan 30 kolom membuat pengguna stres dan meninggalkan halaman (drop off). Memecah proses kompleks ke dalam langkah sederhana (wizard/progressive disclosure) mempercepat pengambilan keputusan." },
            { id: "design-35", category: "design", difficulty: "medium", question: "Dalam metodologi Atomic Design oleh Brad Frost, bagaimanakah urutan hirarki komponen dari yang terkecil hingga terbesar?", answers: ["Atoms -> Molecules -> Organisms -> Templates -> Pages", "Pages -> Templates -> Organisms -> Molecules -> Atoms", "Icons -> Buttons -> Cards -> Sections -> Websites", "Tokens -> Elements -> Layouts -> Screens -> Applications"], correct: 0, hint: "Dari atom kimia sederhana membentuk molekul, organisme, hingga halaman nyata.", explanation: "Atomic Design menyusun komponen secara modular: Atoms (input, label, tombol), Molecules (form pencarian), Organisms (header navigasi lengkap), Templates (kerangka layout wireframe), dan Pages (template yang telah diisi konten nyata)." },
            { id: "design-36", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Fitts's Law' dalam perancangan interaksi pengguna?", answers: ["Waktu yang dibutuhkan untuk berpindah ke suatu target adalah fungsi dari jarak menuju target tersebut dibagi dengan ukuran target itu sendiri (target lebih dekat dan lebih besar lebih cepat diklik)", "Waktu pemuatan halaman web di atas 3 detik akan membuat 50% pengunjung langsung pergi", "Pengguna menghabiskan sebagian besar waktunya di situs lain, sehingga situs Anda harus meniru kebiasaan situs populer", "Desain visual harus menggunakan maksimal 3 jenis warna utama dalam satu layar"], correct: 0, hint: "Mengapa tombol penting seperti 'Beli Sekarang' dibuat besar dan strategis.", explanation: "Fitts's Law merumuskan bahwa untuk memudahkan pengguna mengklik tombol penting (seperti Call to Action), tombol tersebut harus dibuat cukup besar dan diletakkan di area yang dekat atau mudah dijangkau kursor/jempol (seperti sudut atau bagian bawah layar mobile)." },
            { id: "design-37", category: "design", difficulty: "hard", question: "Apakah kegunaan dari survei System Usability Scale (SUS) dalam evaluasi UX?", answers: ["Kuesioner standar berisikan 10 pernyataan dengan skala Likert untuk mengukur tingkat kebergunaan (usability) dan kepuasan pengguna terhadap suatu sistem secara kuantitatif", "Metode melacak pergerakan bola mata pengguna (eye-tracking) saat melihat poster iklan", "Alat untuk menghitung kecepatan internet server dalam memuat gambar SVG", "Panduan pemilihan kombinasi warna komplementer untuk pembuatan logo startup"], correct: 0, hint: "Menghasilkan skor agregat dari 0 hingga 100 untuk menilai kemudahan pakai sistem.", explanation: "System Usability Scale (SUS) adalah standar keandalan global dalam UX research. Skor SUS di atas 68 dianggap rata-rata (dapat diterima), sedangkan skor di atas 80 menunjukkan pengalaman kebergunaan yang sangat prima dan luar biasa." },
            { id: "design-38", category: "design", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Wireframe' dalam tahapan desain produk digital?", answers: ["Sketsa kerangka visual kasar (low-fidelity) berstruktur hitam-putih yang memfokuskan tata letak tata ruang, hierarki informasi, dan navigasi tanpa elemen visual detail atau warna", "Desain akhir beresolusi tinggi (high-fidelity) yang sudah dilengkapi animasi dan aset ilustrasi nyata", "Kode program HTML dan CSS akhir yang siap diunggah ke server hosting production", "Peta perjalanan perasaan dan emosi pengguna dari awal hingga akhir menggunakan produk"], correct: 0, hint: "Cetak biru (blueprint) sederhana sebelum desain visual dipercantik.", explanation: "Wireframe membantu tim produk dan klien untuk bersepakat mengenai struktur konten, tata letak elemen, dan alur navigasi halaman tanpa terdistraksi oleh perdebatan warna, jenis font, atau gambar grafis detail." },
            { id: "design-39", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan prinsip Gestalt 'Proximity' dalam desain antarmuka?", answers: ["Elemen-elemen visual yang diletakkan saling berdekatan satu sama lain akan dipahami oleh mata manusia sebagai satu kelompok yang memiliki hubungan atau fungsi terkait", "Elemen visual yang memiliki warna atau bentuk sama akan dianggap sebagai satu kelompok", "Mata manusia secara otomatis melengkapi garis atau bentuk yang terputus agar terlihat utuh", "Elemen visual berukuran paling besar akan selalu dilihat pertama kali oleh pengguna"], correct: 0, hint: "Kedekatan jarak ruang kosong (white space) menentukan hubungan pengelompokan.", explanation: "Prinsip Proximity (Kedekatan) memanfaatkan white space. Dengan meletakkan judul artikel, gambar, dan tombol 'Baca' berdekatan, pengguna seketika mengerti bahwa ketiga elemen tersebut adalah satu kesatuan kartu informasi." },
            { id: "design-40", category: "design", difficulty: "hard", question: "Dalam pembuatan animasi UI/UX, mengapa kurva 'Ease-Out' (cepat di awal, melambat di akhir) sering direkomendasikan untuk elemen yang masuk ke layar (entering UI)?", answers: ["Karena memberikan kesan responsif seketika saat dipicu, lalu melambat secara alami sehingga mata pengguna sempat menangkap dan fokus pada posisi akhir elemen tersebut", "Karena kurva Ease-Out memakan memori prosesor paling kecil dibanding kurva Linear", "Karena animasi Linear membuat elemen terlihat seperti bergetar dan tidak jelas", "Karena semua sistem operasi Android melarang penggunaan animasi selain Ease-Out"], correct: 0, hint: "Gerakan alami hukum fisika: objek bergeser cepat lalu melambat karena gesekan saat berhenti.", explanation: "Saat modal atau sidebar muncul di layar, kurva Ease-Out membuatnya melesat cepat merespons klik pengguna, kemudian melambat dengan halus saat mencapai tujuan akhir, memberikan sensasi elegan dan mudah diikuti mata." },
            { id: "design-41", category: "design", difficulty: "medium", question: "Apakah perbedaan antara Heuristic Evaluation dan Usability Testing?", answers: ["Heuristic Evaluation dilakukan oleh pakar UX dengan meninjau produk terhadap prinsip-prinsip standar kebergunaan (seperti 10 Heuristik Nielsen), sedangkan Usability Testing menguji produk langsung kepada pengguna nyata", "Heuristic Evaluation untuk aplikasi mobile, Usability Testing untuk website desktop", "Heuristic Evaluation mengukur kecepatan loading, Usability Testing mengukur estetika warna", "Heuristic Evaluation dilakukan setelah peluncuran, Usability Testing dilakukan sebelum desain dibuat"], correct: 0, hint: "Evaluasi oleh pakar/ahli vs pengujian langsung oleh calon pengguna akhir.", explanation: "Heuristic Evaluation adalah audit inspeksi cepat dan murah oleh pakar UX untuk menemukan pelanggaran prinsip desain klasik. Usability testing melibatkan observasi pengguna asli saat menyelesaikan tugas (task) untuk menangkap kebingungan nyata di lapangan." },
            { id: "design-42", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Jacob's Law' (Jakob's Law) dalam desain antarmuka?", answers: ["Pengguna menghabiskan sebagian besar waktu mereka di situs/aplikasi lain, sehingga mereka mengharapkan produk Anda bekerja dengan cara yang serupa dengan situs yang sudah mereka kenal", "Setiap halaman web harus bisa dimuat di bawah waktu 2 detik agar tidak ditinggalkan pengguna", "Desain antarmuka harus menggunakan rasio emas (Golden Ratio 1:1.618) pada layout grid", "Pengguna selalu membaca layar dengan pola huruf F dari kiri atas ke kanan bawah"], correct: 0, hint: "Jangan menemukan kembali roda (don't reinvent the wheel) untuk pola umum seperti keranjang belanja atau posisi ikon profil.", explanation: "Jakob's Law (diformulasikan oleh Jakob Nielsen) mengingatkan kita agar tidak mengubah konvensi umum yang sudah meresap (seperti ikon keranjang di kanan atas e-commerce atau menu hamburger) hanya demi tampil unik, karena akan merusak ekspektasi mental pengguna." },
            { id: "design-43", category: "design", difficulty: "easy", question: "Apakah fungsi utama dari state 'Focus' pada sebuah komponen interaktif (seperti tombol atau input form)?", answers: ["Memberikan indikasi visual yang jelas mengenai elemen mana yang sedang aktif menerima input dari penekanan tombol Tab di keyboard atau pembaca layar (screen reader)", "Mengubah warna latar belakang aplikasi menjadi gelap saat malam hari", "Menyembunyikan elemen lain di layar agar pengguna tidak terdistraksi", "Mempercepat waktu pengiriman data dari form ke server backend"], correct: 0, hint: "Cincin outline (ring) atau warna sorot saat kita menavigasi web tanpa mouse.", explanation: "State focus sangat krusial bagi aksesibilitas. Pengguna yang menavigasi web dengan keyboard atau assistive technology mutlak membutuhkan indikator visual (focus ring) untuk mengetahui posisi kursor aktif mereka di layar." },
            { id: "design-44", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Micro-interactions' dalam desain antarmuka?", answers: ["Momen interaksi fungsional kecil yang memberi umpan balik balik (feedback) instan kepada pengguna saat melakukan aksi tertentu, seperti animasi ikon hati berdetar saat diklik", "Proses mengunduh pembaruan aplikasi berukuran di bawah 1 megabyte", "Sesi tes wawancara pengguna berdurasi singkat selama maksimal 5 menit", "Penggunaan ukuran font sangat kecil pada catatan kaki halaman web"], correct: 0, hint: "Sentuhan halus yang membuat aplikasi terasa hidup dan responsif.", explanation: "Micro-interactions (seperti getaran haptic saat tombol toggle diaktifkan, atau perubahan warna ikon saat di-hover) memberikan konfirmasi visual/emosional instan bahwa sistem telah menerima dan merespons tindakan pengguna dengan sukses." },
            { id: "design-45", category: "design", difficulty: "hard", question: "Dalam desain responsif mobile, apakah yang dimaksud dengan 'Thumb Zone'?", answers: ["Area pada layar smartphone yang paling mudah, nyaman, dan cepat dijangkau oleh pergerakan alami jempol tangan pengguna saat memegang ponsel dengan satu tangan", "Area di bagian atas layar smartphone tempat notifikasi masuk ditampilkan", "Tombol khusus pada keyboard virtual untuk menghapus karakter dengan cepat", "Teknik memperkecil ukuran gambar thumbnail pada galeri foto mobile"], correct: 0, hint: "Area hijau (nyaman di bawah/tengah), kuning (meregang), merah (sulit dijangkau di sudut atas).", explanation: "Riset Thumb Zone oleh Steven Hoober menunjukkan bahwa mayoritas pengguna mengoperasikan smartphone dengan satu tangan menggunakan jempol. Menempatkan navigasi utama (Bottom Nav Bar) di area bawah/tengah layar secara drastis meningkatkan kenyamanan ergonomis." },
            { id: "design-46", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Information Architecture' (IA) dalam perancangan produk digital?", answers: ["Seni dan sains dalam mengorganisasikan, menata, melabeli, dan menyusun struktur navigasi informasi agar pengguna mudah menemukan apa yang mereka cari", "Proses menulis kode database SQL untuk menyimpan data profil pengguna", "Perancangan topologi jaringan kabel server di dalam pusat data", "Pemilihan gaya arsitektur bangunan kantor bagi perusahaan teknologi startup"], correct: 0, hint: "Peta struktur menu, kategori, sitemap, dan taksonomi konten.", explanation: "Information Architecture (IA) yang baik ibarat tata letak rambu yang jelas di dalam gedung supermarket. Melalui Card Sorting dan Tree Testing, IA menyusun kategori dan alur navigasi agar pengguna tidak tersesat saat menelusuri ratusan halaman fitur." },
            { id: "design-47", category: "design", difficulty: "hard", question: "Apakah perbedaan antara Customer Effort Score (CES) dan Net Promoter Score (NPS)?", answers: ["CES mengukur seberapa mudah/usaha yang dibutuhkan pengguna untuk menyelesaikan satu tugas spesifik, sedangkan NPS mengukur tingkat kepuasan jangka panjang dan kemauan merekomendasikan produk ke orang lain", "CES diukur dengan persentase, sedangkan NPS diukur dalam satuan mata uang dolar", "CES hanya untuk produk perangkat keras, sedangkan NPS hanya untuk aplikasi mobile", "CES dilakukan setahun sekali, sedangkan NPS dilakukan setiap detik secara otomatis"], correct: 0, hint: "Usaha interaksi transaksional jangka pendek vs loyalitas merek jangka panjang.", explanation: "Customer Effort Score (CES) ditanyakan tepat setelah pengguna selesai melakukan aksi (misal: 'Seberapa mudah proses pengembalian barang ini?'). NPS ditanyakan secara berkala untuk menilai loyalitas emosional (misal: 'Seberapa besar kemungkinan Anda merekomendasikan kami?')." },
            { id: "design-48", category: "design", difficulty: "medium", question: "Apakah fungsi utama dari pembuatan 'User Persona' dalam tahap riset UX?", answers: ["Representasi arketipe fiktif berbasis data riset nyata yang menggambarkan demografi, tujuan, rasa frustrasi, dan kebiasaan kelompok pengguna sasaran untuk memandu keputusan desain tim", "Daftar nama asli dan nomor telepon pengguna VIP untuk dihubungi oleh tim sales", "Foto profil karakter kartun yang dijadikan maskot resmi pemasaran perusahaan", "Akun login pengujian palsu untuk mengecek keamanan sistem dari peretas"], correct: 0, hint: "Memanusiakan data riset agar tim membangun fitur dengan empati yang tepat.", explanation: "User Persona merangkum temuan wawancara dan survei menjadi satu sosok profil yang hidup (misal: 'Budi, 28 tahun, Remote Worker'). Ini membantu tim enggan merancang produk berdasarkan asumsi pribadi ('Saya rasa fitur ini bagus') menjadi berorientasi pengguna ('Apakah Budi membutuhkan fitur ini?')." },
            { id: "design-49", category: "design", difficulty: "easy", question: "Apakah kegunaan dari 'White Space' (Negative Space) dalam tata letak visual UI?", answers: ["Memberikan ruang bernapas antar elemen untuk meningkatkan keterbacaan, memfokuskan perhatian pada konten utama, dan memberikan kesan elegan", "Menghapus semua warna dari layar agar aplikasi terlihat seperti dokumen cetak lama", "Mengurangi ukuran ukuran file aplikasi saat diunduh dari App Store", "Menandakan bagian layar yang mengalami error atau gagal dimuat oleh server"], correct: 0, hint: "Ruang kosong bukanlah ruang terbuang sia-sia (not wasted space).", explanation: "White space adalah elemen desain yang sangat aktif. Penggunaan margin, padding, dan jarak antar baris yang tepat mencegah rasa penat visual, menonjolkan hierarki tipografi, dan memandu mata ke Call to Action utama." },
            { id: "design-50", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Dark Patterns' (Deceptive Design) dalam antarmuka digital?", answers: ["Desain antarmuka yang sengaja dirancang untuk menipu, memanipulasi, atau menjebak pengguna agar melakukan tindakan yang menguntungkan perusahaan namun merugikan pengguna (seperti langganan tersembunyi atau sulit batal langganan)", "Pilihan mode tema warna gelap (Dark Mode) untuk menghemat daya baterai OLED", "Penggunaan font hitam tebal di atas latar belakang putih murni", "Teknik menyembunyikan kode rahasia di dalam file gambar logo website"], correct: 0, hint: "Roach Motel, Confirmshaming, Hidden Costs, dan Forced Continuity.", explanation: "Dark Patterns adalah praktik tidak etis dalam UX. Contohnya adalah membuat tombol 'Batal Langganan' disembunyikan di 5 lapisan menu dengan warna abu-abu samar, sementara tombol 'Perpanjang Langganan' dibuat raksasa dan menyala terang." },

            // Data & Analytics Extended (31-50)
            { id: "analytics-31", category: "analytics", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Data Cleaning' (Pembersihan Data) dalam alur kerja analisis data?", answers: ["Proses mendeteksi dan memperbaiki (atau menghapus) data yang rusak, tidak lengkap, duplikat, atau salah format sebelum dilakukan analisis", "Proses menghapus seluruh database agar server kembali bersih seperti baru", "Mengenkripsi data ke format rahasia sebelum diunggah ke cloud storage", "Membuat salinan cadangan (backup) data mingguan di harddisk eksternal"], correct: 0, hint: "Garbage In, Garbage Out (GIGO) - data kotor menghasilkan insight yang salah.", explanation: "Data Cleaning adalah tahap paling memakan waktu namun krusial. Mengatasi nilai hilang (missing values), standardisasi format tanggal, dan menghapus pencilan eksternal (outlier duplikat) menjamin akurasi model statistik dan visualisasi." },
            { id: "analytics-32", category: "analytics", difficulty: "easy", question: "Apakah perbedaan antara Metrik (Metric) dan KPI (Key Performance Indicator)?", answers: ["Metrik adalah angka kuantitatif apa pun yang mengukur aktivitas (seperti jumlah tayangan halaman), sedangkan KPI adalah metrik terpilih yang secara kritis mengukur kemajuan menuju target strategi bisnis utama", "Metrik dihitung dengan komputer, sedangkan KPI dihitung secara manual oleh manajemen", "Metrik selalu bernilai uang dolar, sedangkan KPI selalu berbentuk persentase", "Metrik hanya untuk divisi marketing, sedangkan KPI hanya untuk divisi engineering"], correct: 0, hint: "Semua KPI adalah metrik, tetapi tidak semua metrik adalah KPI.", explanation: "Metrik melacak berbagai aktivitas harian (seperti jumlah klik atau waktu di halaman). KPI (Key Performance Indicator) adalah indikator vital yang langsung terikat pada sasaran strategis perusahaan (misal: Customer Acquisition Cost atau Monthly Recurring Revenue)." },
            { id: "analytics-33", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Funnel Analysis' dalam analitik produk digital?", answers: ["Pemetaan dan analisis urutan langkah-langkah spesifik yang harus dilalui pengguna untuk mencapai suatu konversi (seperti Daftar -> Masuk Keranjang -> Bayar) guna menemukan titik putus (drop-off)", "Metode pengumpulan data dari berbagai sumber database menggunakan pipa ETL", "Analisis demografi umur pengguna dari yang tertua hingga termuda", "Perhitungan rata-rata waktu loading halaman di berbagai browser berbeda"], correct: 0, hint: "Berbentuk corong yang semakin ke bawah semakin menyempit karena ada pengguna yang mundur.", explanation: "Funnel Analysis memperlihatkan persentase pengguna yang berhasil beralih dari satu tahap ke tahap berikutnya. Jika 1.000 orang melihat produk tetapi hanya 50 orang yang sampai halaman checkout, analis fokus meneliti mengapa 950 orang mundur di tengah jalan." },
            { id: "analytics-34", category: "analytics", difficulty: "medium", question: "Apakah kegunaan dari 'Box Plot' (Box-and-Whisker Plot) dalam statistika deskriptif?", answers: ["Menampilkan distribusi data numerik melalui lima serangkai (minimum, kuartil bawah Q1, median Q2, kuartil atas Q3, maksimum) serta mengidentifikasi keberadaan pencilan (outliers)", "Menampilkan perbandingan total penjualan antar kategori produk dalam bentuk batang 3D", "Memetakan koordinat geografis lokasi pelanggan di atas peta dunia interaktif", "Menunjukkan hubungan sebab akibat antara dua variabel secara langsung"], correct: 0, hint: "Kotak dengan dua kumis (whiskers) di ujungnya dan titik pencilan di luarnya.", explanation: "Box Plot memberikan gambaran ringkas tentang sebaran data, tingkat kemiringan (skewness), dan rentang antar-kuartil (Interquartile Range / IQR). Titik-titik di luar batas kumis (1.5 x IQR) langsung dikenali sebagai outlier statistik." },
            { id: "analytics-35", category: "analytics", difficulty: "medium", question: "Dalam analisis regresi dan pemodelan prediktif, apakah yang dimaksud dengan 'Overfitting'?", answers: ["Kondisi ketika model terlalu rumit dan menghafal detail serta noise pada data latih (training data), sehingga kinerjanya sangat buruk saat diuji pada data baru yang belum pernah dilihat sebelumnya", "Kondisi saat database analitik penuh dan tidak mampu menerima baris baru", "Kesalahan penulisan rumus matematika pada sel spreadsheet Excel", "Kondisi di mana model menghasilkan prediksi terlalu sederhana dan akurasi rendah di semua data"], correct: 0, hint: "Menghafal soal ujian sampai titik komanya, tapi gagal menjawab soal yang diganti sedikit angkanya.", explanation: "Overfitting terjadi karena model terlalu fleksibel (bias rendah, varians tinggi). Model mampu mencapai akurasi 99% di training set karena merekam noise acak, tetapi langsung anjlok saat diuji di test set dunia nyata." },
            { id: "analytics-36", category: "analytics", difficulty: "hard", question: "Apakah perbedaan antara Correlation (Korelasi) dan Causation (Sebab-Akibat)?", answers: ["Korelasi menunjukkan bahwa dua variabel bergerak bersamaan dalam pola tertentu, sedangkan Causation membuktikan bahwa perubahan pada satu variabel secara langsung menyebabkan perubahan pada variabel lainnya", "Korelasi selalu bernilai positif, sedangkan Causation selalu bernilai negatif", "Korelasi dihitung dengan SQL, sedangkan Causation hanya bisa dihitung dengan Python", "Korelasi dan Causation adalah istilah yang sepenuhnya sama dan bisa ditukar-tukar"], correct: 0, hint: "Correlation does not imply causation (penjualan es krim dan serangan hiu meningkat bersamaan saat musim panas, bukan karena es krim memicu hiu).", explanation: "Korelasi mengukur kekuatan hubungan linier antar variabel. Untuk membuktikan sebab-akibat (Causation), kita membutuhkan eksperimen terkontrol (seperti A/B Testing atau Randomized Controlled Trials) guna mengeliminasi variabel pengganggu (confounders)." },
            { id: "analytics-37", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'P-value' dalam pengujian hipotesis statistik?", answers: ["Probabilitas memperoleh hasil pengamatan (atau yang lebih ekstrem) jika hipotesis nol (H0) benar; p-value kecil (< 0.05) menunjukkan bukti kuat untuk menolak hipotesis nol", "Persentase keuntungan finansial yang dihasilkan dari sebuah kampanye marketing", "Jumlah parameter variabel independen di dalam sebuah model regresi", "Tingkat akurasi maksimal yang bisa dicapai oleh algoritma machine learning"], correct: 0, hint: "Jika p-value sangat kecil, peluang hasil tersebut terjadi semata-mata karena kebetulan acak adalah sangat kecil.", explanation: "P-value bukanlah probabilitas bahwa hipotesis kita benar. P-value mengukur seberapa tidak masuk akal data kita jika asumsi awal (hipotesis nol/tidak ada efek) adalah benar. P-value di bawah batas signifikansi (biasanya alpha = 0.05) berarti hasil tersebut secara statistik signifikan." },
            { id: "analytics-38", category: "analytics", difficulty: "easy", question: "Apakah kegunaan utama dari tool Business Intelligence (BI) seperti Tableau, Power BI, atau Metabase?", answers: ["Menghubungkan berbagai sumber data, mengolahnya, dan menyajikannya dalam bentuk dasbor visual interaktif untuk mendukung pengambilan keputusan bisnis", "Menulis kode program sistem operasi untuk server pusat data", "Mengedit video promosi dan animasi ilustrasi 3D produk", "Menggantikan fungsi router jaringan dalam mengamankan lalu lintas web"], correct: 0, hint: "Mengubah jutaan baris angka tabel SQL menjadi grafik visual yang mudah dimengerti direksi.", explanation: "BI tools menjembatani data engineer dengan pengambil keputusan bisnis. Melalui visualisasi interaktif dan otomatisasi pelaporan harian, manajemen dapat mendeteksi tren pasar atau kebocoran biaya dalam hitungan detik." },
            { id: "analytics-39", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Data Warehouse' dan perbedaannya dengan 'Data Lake'?", answers: ["Data Warehouse menyimpan data terstruktur yang sudah dibersihkan untuk kebutuhan pelaporan/BI, sedangkan Data Lake menyimpan data mentah dalam berbagai format (terstruktur, semi, tak-terstruktur) skala besar", "Data Warehouse untuk file gambar, Data Lake untuk teks spreadsheet", "Data Warehouse berjalan offline di komputer, Data Lake hanya ada di satelit", "Data Warehouse gratis tanpa biaya, Data Lake selalu berbayar mahal"], correct: 0, hint: "Gudang rapi siap pakai vs Danau penampungan seluruh aliran data mentah dari berbagai muara.", explanation: "Data Warehouse (seperti Snowflake/BigQuery) menerapkan skema-at-write untuk analitik relasional berkecepatan tinggi. Data Lake (seperti Amazon S3) menyimpan log mentah, JSON, audio, dan CSV tanpa skema awal (schema-at-read), memberi kebebasan eksplorasi bagi Data Scientist." },
            { id: "analytics-40", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Customer Lifetime Value' (CLV / LTV) dan mengapa metrik ini penting untuk disandingkan dengan CAC (Customer Acquisition Cost)?", answers: ["CLV adalah estimasi total pendapatan bersih yang diperoleh bisnis dari satu pelanggan selama masa hubungan mereka; bisnis sehat mengharuskan CLV jauh lebih besar dari biaya akuisisi (CAC)", "CLV adalah jumlah hari total seorang pelanggan login sebelum menghapus akun aplikasi", "CLV adalah biaya yang harus dibayar perusahaan untuk menyewa server cloud per pelanggan", "CLV adalah tingkat kepuasan pelanggan yang diukur dengan survei bintang lima"], correct: 0, hint: "Rasio CLV : CAC yang ideal umumnya minimal 3 : 1.", explanation: "CLV mengukur nilai jangka panjang pelanggan. Jika CAC (biaya iklan untuk mendapatkan 1 user) adalah Rp100.000 sementara CLV-nya hanya Rp50.000, model bisnis tersebut rugi dan akan bangkrut. Memahami CLV membantu mengalokasikan anggaran akuisisi yang rasional." },
            { id: "analytics-41", category: "analytics", difficulty: "medium", question: "Dalam pengolahan data berskala besar (Big Data), apakah yang dimaksud dengan paradigma 'MapReduce'?", answers: ["Model pemrosesan terdistribusi yang memecah tugas menjadi dua fase: Map (memetakan/menyaring data di banyak node paralel) dan Reduce (menggabungkan/mengagregasi hasil dari fase Map)", "Algoritma kompresi file untuk memperkecil ukuran video sebesar 90%", "Metode menghapus kolom tabel SQL yang jarang digunakan oleh query", "Proses mengonversi basis data relasional menjadi dokumen grafik"], correct: 0, hint: "Divide and conquer di ribuan server klaster.", explanation: "MapReduce memungkinkan pemrosesan dataset berukuran petabyte di klaster ribuan komputer komoditas. Fase Map mendistribusikan komputasi ke lokasi data berada, dan fase Reduce merangkum output parsial tersebut menjadi jawaban akhir." },
            { id: "analytics-42", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Survivorship Bias' (Bias Keberlangsungan Hidup) dalam interpretasi data?", answers: ["Kesalahan logika yang terjadi ketika kita hanya menganalisis data dari entitas/subjek yang 'selamat' atau berhasil melewati proses seleksi, dan mengabaikan mereka yang gagal (karena datanya hilang/tidak terlihat)", "Kecenderungan analis data untuk selalu memilih grafik garis dibanding grafik lingkaran", "Bias saat algoritma machine learning menghapus baris data yang berisi nilai nol", "Kondisi di mana server analitik tetap hidup saat terjadi pemadaman listrik total"], correct: 0, hint: "Contoh klasik: meneliti kelemahan pesawat pembom WWII hanya dari pesawat yang berhasil pulang dengan selamat, mengabaikan pesawat yang jatuh karena tertembak di mesin.", explanation: "Survivorship bias mengarah pada kesimpulan palsu. Jika kita meneliti faktor kesuksesan startup hanya dengan mewawancarai 10 startup unicorn yang bertahan, kita melewatkan fakta bahwa 1.000 startup bangkrut yang melakukan taktik sama persis tidak pernah dianalisis." },
            { id: "analytics-43", category: "analytics", difficulty: "easy", question: "Apakah perbedaan antara ukuran pemusatan data Median dan Mean (Rata-rata Hitung)?", answers: ["Mean adalah jumlah seluruh nilai dibagi banyaknya data (rentan terhadap outlier), sedangkan Median adalah nilai tengah tepat saat data diurutkan (lebih kebal terhadap outlier ekstrem)", "Mean selalu lebih besar daripada Median dalam semua jenis distribusi data", "Mean dihitung dengan mengurangi nilai maksimum dan minimum, sedangkan Median dihitung dengan persentase", "Mean untuk data teks kata-kata, sedangkan Median untuk data angka numerik"], correct: 0, hint: "Gaji rata-rata warga 1 desa mendadak naik miliaran saat Elon Musk pindah ke desa itu (Mean kacau, Median tetap stabil).", explanation: "Jika kita memiliki data pendapatan: 3, 4, 4, 5, dan 100 juta. Mean-nya adalah 23.2 juta (terdistorsi oleh angka 100), sementara Median-nya adalah 4 juta yang merepresentasikan kondisi aktual mayoritas kelompok tersebut secara realistis." },
            { id: "analytics-44", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan 'ETL' dalam rekayasa data (Data Engineering)?", answers: ["Extract, Transform, Load — proses mengambil data dari berbagai sumber, mengubah/membersihkannya sesuai standar bisnis, lalu memuatnya ke dalam gudang data tujuan", "Encrypt, Transmit, Lock — protokol pengamanan jaringan untuk transaksi perbankan", "Evaluate, Test, Launch — tahapan perilisan produk software baru ke publik", "Elastic, Temporary, Local — jenis penyimpanan memori sementara pada server cloud"], correct: 0, hint: "Tiga langkah pipa pengaliran data dari database operasional ke database analitik.", explanation: "ETL adalah tulang punggung integrasi data. Extract menarik data dari API, CRM, dan SQL. Transform membersihkan, menggabungkan, dan menghitung agregat. Load menyimpannya ke Data Warehouse agar siap di-query analis." },
            { id: "analytics-45", category: "analytics", difficulty: "hard", question: "Dalam pemodelan klasifikasi statistik, apakah perbedaan antara Type I Error (False Positive) dan Type II Error (False Negative)?", answers: ["Type I Error mendeteksi adanya efek/kondisi padahal kenyataannya tidak ada (alarm palsu), sedangkan Type II Error gagal mendeteksi efek/kondisi yang kenyataannya benar-benar ada (terlewat)", "Type I Error hanya terjadi pada data teks, sedangkan Type II Error terjadi pada angka", "Type I Error adalah kesalahan dari database, sedangkan Type II Error dari jaringan internet", "Type I Error dan Type II Error selalu terjadi bersamaan dengan persentase 50:50"], correct: 0, hint: "False Positive = tes kehamilan menyatakan pria positif hamil. False Negative = tes menyatakan wanita hamil 8 bulan sebagai tidak hamil.", explanation: "Dalam diagnosa penyakit kritis atau deteksi penipuan bank (fraud), Type II Error (False Negative) bisa berakibat fatal karena bahaya yang nyata lolos tanpa terdeteksi. Analisis trade-off antara keduanya diatur melalui kurva ROC dan penyesuaian threshold." },
            { id: "analytics-46", category: "analytics", difficulty: "medium", question: "Apakah kegunaan dari analisis 'RFM' (Recency, Frequency, Monetary) dalam segmentasi pelanggan?", answers: ["Mengelompokkan pelanggan berdasarkan kapan terakhir kali mereka bertransaksi (Recency), seberapa sering bertransaksi (Frequency), dan total uang yang dibelanjakan (Monetary)", "Menghitung kecepatan koneksi jaringan (Rate, Flow, Megabits) di server e-commerce", "Membagi produk berdasar warna merah, hijau, dan magenta di katalog visual", "Mengidentifikasi kesalahan sintaks SQL pada tiga tabel yang saling berelasi"], correct: 0, hint: "Tiga dimensi utama untuk menemukan siapa pelanggan 'Sultan' dan pelanggan 'Muntab' yang butuh re-engagement.", explanation: "RFM scoring memungkinkan tim pemasaran mengidentifikasi segmen Champions (sering beli, baru beli, pengeluaran besar) untuk diberi reward eksklusif, serta segmen At-Risk (dulu pengeluaran besar tapi sudah lama tidak beli) untuk diberi kupon win-back." },
            { id: "analytics-47", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Bayesian Inference' (Inferensi Bayesian) dalam analisis peluang?", answers: ["Metode statistik yang memperbarui pembaruan probabilitas suatu hipotesis (posterior) seiring dengan terkumpulnya bukti atau data baru, dengan memperhitungkan keyakinan awal (prior)", "Metode mengurutkan data tabel dari nilai terkecil hingga terbesar dalam waktu O(N)", "Teknik menghapus baris data duplikat menggunakan perbandingan hash string", "Proses pengujian A/B testing yang harus menunggu sampai 1 juta pengunjung"], correct: 0, hint: "Teorema Bayes: P(A|B) = [P(B|A) * P(A)] / P(B).", explanation: "Inferensi Bayesian sangat fleksibel karena memungkinkan kita memasukkan pengetahuan awal pakar (Prior Probability). Ketika data pengamatan baru masuk (Likelihood), keyakinan kita diperbarui secara matematis menjadi Posterior Probability." },
            { id: "analytics-48", category: "analytics", difficulty: "medium", question: "Apakah fungsi utama dari 'Heatmap' (Peta Panas) dalam analisis perilaku pengguna web?", answers: ["Representasi grafis yang menggunakan spektrum warna (merah muda panas hingga biru dingin) untuk menunjukkan area mana di halaman web yang paling sering diklik, digeser, atau dilihat oleh pengguna", "Mengukur suhu prosesor server saat menerima ribuan kunjungan secara bersamaan", "Menunjukkan diagram jaringan kabel serat optik antar benua di bawah laut", "Membandingkan harga saham perusahaan pesaing di pasar modal harian"], correct: 0, hint: "Area merah/kuning berarti ramai interaksi, area biru/abu-abu berarti diabaikan.", explanation: "Heatmap (seperti yang dihasilkan Hotjar atau Clarity) merekam aktivitas klik, pergerakan mouse, dan batas scroll (scroll depth). Ini membantu desainer mengetahui apakah tombol CTA terlihat atau justru pengguna mengklik elemen gambar yang tidak bisa diklik." },
            { id: "analytics-49", category: "analytics", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Time Series Analysis'?", answers: ["Analisis terhadap titik-titik data yang dikumpulkan atau dicatat secara berurutan pada interval waktu tertentu guna mengenali tren jangka panjang dan pola musiman (seasonality)", "Pengukuran waktu eksekusi kode program di dalam browser komputer klien", "Jadwal absensi harian karyawan perusahaan yang dicatat dengan mesin sidik jari", "Penghitungan sisa waktu mundur sebelum peluncuran produk baru ke pasar"], correct: 0, hint: "Data berurutan terhadap waktu: detik, jam, hari, bulan, atau tahun.", explanation: "Time series analysis (seperti pemodelan ARIMA atau Prophet) digunakan untuk meramal (forecasting) permintaan produk, beban puncak listrik, harga saham, atau tren cuaca dengan memanfaatkan pola historis berulang dan komponen musiman." },
            { id: "analytics-50", category: "analytics", difficulty: "hard", question: "Apakah perbedaan antara pemodelan 'Supervised Learning' dan 'Unsupervised Learning' dalam analitik data tingkat lanjut?", answers: ["Supervised Learning dilatih menggunakan data yang sudah memiliki label jawaban target (seperti prediksi harga atau klasifikasi spam), sedangkan Unsupervised Learning menemukan pola tersembunyi/klaster pada data tanpa label", "Supervised dijalankan di komputer desktop, sedangkan Unsupervised dijalankan di server cloud", "Supervised hanya untuk data teks, sedangkan Unsupervised hanya untuk gambar foto", "Supervised tidak memerlukan algoritma matematika, sedangkan Unsupervised memerlukan"], correct: 0, hint: "Dengan guru yang memberi tahu jawaban benar vs belajar mandiri mengelompokkan kemiripan.", explanation: "Supervised learning (seperti regresi linier, random forest) membutuhkan dataset berlabel untuk mempelajari pemetaan input ke output. Unsupervised learning (seperti K-Means clustering, PCA) bekerja pada data mentah tanpa label untuk mengelompokkan segmen pelanggan atau reduksi dimensi." },

            // Web Development Extended (31-50)
            { id: "web-31", category: "web", difficulty: "easy", question: "Apakah perbedaan utama antara atribut 'localStorage' dan 'sessionStorage' pada Web Storage API browser?", answers: ["localStorage menyimpan data secara persisten tanpa batas waktu sampai dihapus manual/kode, sedangkan sessionStorage akan terhapus otomatis begitu tab atau jendela browser ditutup", "localStorage hanya bisa menampung 1 KB data, sedangkan sessionStorage bisa menampung 100 GB", "localStorage disimpan di server cloud, sedangkan sessionStorage disimpan di harddisk lokal", "localStorage hanya mendukung tipe angka, sedangkan sessionStorage hanya mendukung teks"], correct: 0, hint: "Persistensi jangka panjang vs usia satu sesi tab.", explanation: "Kedua API ini memungkinkan penyimpanan key-value di browser dengan kapasitas ~5-10 MB. localStorage ideal untuk menyimpan preferensi tema (dark mode) jangka panjang, sementara sessionStorage cocok untuk state sementara di satu tab spesifik." },
            { id: "web-32", category: "web", difficulty: "easy", question: "Dalam CSS Box Model standar, apakah urutan lapisan dari bagian paling dalam hingga paling luar?", answers: ["Content -> Padding -> Border -> Margin", "Margin -> Border -> Padding -> Content", "Border -> Padding -> Content -> Margin", "Padding -> Content -> Margin -> Border"], correct: 0, hint: "Dari isi teks di tengah, ruang nafas dalam, garis bingkai, hingga jarak luar antar elemen.", explanation: "Box model adalah dasar tata letak CSS. Content adalah isi elemen; Padding adalah ruang di antara content dan border; Border adalah garis batas elemen; dan Margin adalah ruang kosong di luar border yang memisahkan elemen dari elemen sekitarnya." },
            { id: "web-33", category: "web", difficulty: "medium", question: "Apakah fungsi utama dari properti CSS 'box-sizing: border-box;'?", answers: ["Membuat perhitungan width dan height suatu elemen sudah mencakup padding dan border, sehingga penambahan padding tidak akan memperlebar ukuran total elemen melebihi width yang ditentukan", "Menambahkan garis border hitam tebal berukuran 1px secara otomatis ke semua elemen di halaman", "Mengubah bentuk elemen kotak persegi menjadi lingkaran sempurna secara 3D", "Mengunci posisi elemen agar tidak bisa digeser saat layar di-scroll pengguna"], correct: 0, hint: "Solusi penyelamat layout agar elemen 50% + padding tidak meledak menjadi 55% dan turun ke baris baru.", explanation: "Pada box-sizing: content-box (default), width 200px + padding 20px membuat lebar total menjadi 240px. Dengan border-box, lebar total dikunci tetap 200px, dan area content internalnya yang mengalah menyusut, membuat pembuatan grid layout jauh lebih mudah." },
            { id: "web-34", category: "web", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Cross-Origin Resource Sharing' (CORS) di peramban web?", answers: ["Mekanisme berbasis header HTTP yang mengizinkan atau membatasi browser untuk melakukan request sumber daya (API/asset) ke domain, port, atau protokol yang berbeda dari asal web saat ini", "Proyek open-source untuk membagikan file gambar secara gratis antar developer frontend", "Protokol kompresi file CSS agar dapat dimuat lebih cepat di jaringan seluler", "Teknik menggabungkan dua server database dari vendor berbeda menjadi satu"], correct: 0, hint: "Kebijakan keamanan browser yang memblokir request ke API domain lain jika tidak diberi izin di header server.", explanation: "Browser menerapkan Same-Origin Policy untuk keamanan. Jika frontend di domain-a.com meminta API ke domain-b.com, browser akan memblokir respons tersebut kecuali server domain-b.com mengirimkan header Access-Control-Allow-Origin yang sah." },
            { id: "web-35", category: "web", difficulty: "medium", question: "Apakah perbedaan antara sistem tata letak CSS Flexbox dan CSS Grid?", answers: ["Flexbox dirancang untuk tata letak satu dimensi (baris ATAU kolom), sedangkan CSS Grid dirancang untuk tata letak dua dimensi (baris DAN kolom sekaligus)", "Flexbox hanya untuk teks, sedangkan CSS Grid hanya untuk gambar ilustrasi", "Flexbox bekerja di server, sedangkan CSS Grid bekerja di browser klien", "Flexbox sudah tidak didukung di browser modern, sedangkan CSS Grid adalah satu-satunya standar baru"], correct: 0, hint: "1D vs 2D layouting.", explanation: "Flexbox sangat ideal untuk menata menu navigasi, deretan tombol, atau kartu yang mengalir dalam satu arah (row/column). CSS Grid adalah sistem grid dua dimensi yang tangguh untuk merancang struktur kerangka halaman menyeluruh (header, sidebar, main content, footer)." },
            { id: "web-36", category: "web", difficulty: "hard", question: "Dalam ekosistem JavaScript, apakah yang dimaksud dengan 'Event Loop' (seperti Call Stack, Web APIs, Callback Queue, Microtask Queue)?", answers: ["Mekanisme pengatur asinkronisitas single-threaded yang terus-menerus memeriksa apakah Call Stack kosong; jika kosong, ia mengambil tugas antrean (prioritas pada Microtask seperti Promise) untuk dieksekusi", "Loop perulangan 'for' yang berjalan tanpa batas sampai browser mengalami crash kehabisan memori", "Fitur animasi CSS yang memutar gambar ikon secara terus-menerus 360 derajat", "Proses sinkronisasi otomatis antara tabel database MySQL dan form HTML"], correct: 0, hint: "Bagaimana JavaScript yang single-threaded bisa menjalankan timer, fetch API, dan event klik tanpa macet.", explanation: "JavaScript mengeksekusi kode di Call Stack. Saat operasi asinkron (fetch/setTimeout) dipanggil, tugas dilempar ke Web APIs browser. Setelah selesai, callback masuk ke Queue. Event Loop bertugas memindahkan callback dari Queue ke Call Stack saat Stack kosong." },
            { id: "web-37", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Content Security Policy' (CSP) pada keamanan web?", answers: ["Header HTTP keamanan yang mendefinisikan daftar putih (whitelist) domain asal yang diizinkan untuk memuat aset (seperti script, stylesheet, gambar), guna mencegah serangan Cross-Site Scripting (XSS)", "Sertifikat enkripsi SSL khusus untuk melindungi password pengguna di form login", "Kebijakan privasi teks tertulis yang harus dicantumkan di bagian footer website e-commerce", "Sistem pembatasan jumlah pengunjung web maksimal 10.000 orang per jam"], correct: 0, hint: "Benteng lapis kedua untuk memblokir eksekusi skrip jahat yang berhasil disuntikkan penyerang.", explanation: "Dengan header CSP (misal: Content-Security-Policy: default-src 'self' https://trustedscripts.com), meskipun penyerang berhasil menyuntikkan tag <script> jahat ke HTML atau mencoba mengambil data dari server eksternal, browser akan memblokir eksekusi skrip tak dikenal tersebut secara mutlak." },
            { id: "web-38", category: "web", difficulty: "easy", question: "Apakah fungsi dari atribut 'alt' pada tag HTML <img>?", answers: ["Menyediakan teks deskriptif alternatif untuk gambar yang akan dibaca oleh screen reader bagi tunanetra, atau ditampilkan jika gambar gagal dimuat oleh jaringan", "Mengatur ukuran tinggi dan lebar gambar secara otomatis dalam hitungan piksel", "Menambahkan efek animasi melayang (hover effect) saat kursor mouse diarahkan ke gambar", "Mengubah format gambar dari JPG menjadi WebP secara otomatis di browser"], correct: 0, hint: "Aksesibilitas (screen reader) & SEO image crawling.", explanation: "Atribut alt (alternative text) sangat penting bagi aksesibilitas web dan optimasi mesin pencari (SEO). Jika koneksi lambat atau gambar rusak, teks alt akan muncul sebagai pengganti, dan mesin pencari Google menggunakan teks ini untuk mengindeks gambar." },
            { id: "web-39", category: "web", difficulty: "medium", question: "Apakah kegunaan dari teknik 'Debouncing' saat menangani event DOM (seperti pengetikan di input pencarian autocomplete)?", answers: ["Menunda eksekusi fungsi sampai periode waktu tertentu berlalu sejak event terakhir kali dipicu, mencegah pemanggilan API berlebihan untuk setiap tombol yang ditekan", "Mempercepat pengiriman request jaringan dengan menggabungkan 10 gambar menjadi satu file", "Menolak semua input angka pada form yang hanya mengizinkan huruf abjad", "Menghapus cache browser secara otomatis setelah pengguna selesai mengisi formulir"], correct: 0, hint: "Tunggu sampai pengguna berhenti mengetik selama 300ms sebelum mengirim request ke server.", explanation: "Tanpa debouncing, jika pengguna mengetik 'JavaScript' (10 huruf) dengan cepat, aplikasi akan memicu 10 request API pencarian secara beruntun. Debouncing menahan eksekusi dan hanya mengirimkan 1 request akhir setelah pengguna berhenti mengetik sesaat." },
            { id: "web-40", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan 'WebAssembly' (Wasm)?", answers: ["Format instruksi biner yang efisien dan portabel yang memungkinkan bahasa pemrograman tingkat rendah (C, C++, Rust) dikompilasi dan dijalankan di dalam browser web dengan kecepatan mendekati native", "Framework CSS baru keluaran Google yang menggantikan seluruh fungsi Bootstrap dan Tailwind", "Alat peramban web rahasia khusus untuk mengakses jaringan gelap (dark web)", "Protokol pengganti HTTP yang menggunakan gelombang radio untuk mengirimkan halaman web"], correct: 0, hint: "Menjalankan game 3D, pengeditan video, atau simulasi fisika berat di browser tanpa plugin.", explanation: "WebAssembly (Wasm) berjalan berdampingan dengan JavaScript di dalam sandbox browser. Wasm memberikan performa eksekusi berkecepatan tinggi bagi aplikasi berat (seperti AutoCAD web, Adobe Photoshop web, atau engine game) yang sebelumnya tidak mungkin dijalankan hanya dengan JS." },
            { id: "web-41", category: "web", difficulty: "medium", question: "Apakah perbedaan antara atribut skrip 'defer' dan 'async' (<script defer src=\"...\"> vs <script async src=\"...\">)?", answers: ["'async' mengunduh skrip di latar belakang dan langsung mengeksekusinya begitu selesai (urutan tidak terjamin); 'defer' mengunduh di latar belakang namun mengeksekusinya berurutan setelah dokumen HTML selesai di-parse", "Kedua atribut tersebut adalah sinonim yang memiliki fungsi 100% identik di semua browser", "'defer' hanya untuk skrip CSS, sedangkan 'async' hanya untuk skrip JavaScript", "'async' memblokir rendering HTML total, sedangkan 'defer' menghapus skrip setelah dieksekusi"], correct: 0, hint: "Kapan skrip dieksekusi terhadap waktu parsing HTML.", explanation: "Skrip biasa tanpa atribut akan menghentikan parsing HTML saat diunduh dan dieksekusi. Skrip async dieksekusi segera setelah diunduh (cocok untuk skrip analitik independen). Skrip defer menunggu sampai seluruh DOM pohon HTML selesai dibangun (cocok untuk skrip aplikasi yang bergantung pada urutan dan elemen DOM)." },
            { id: "web-42", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Shadow DOM' dalam spesifikasi Web Components?", answers: ["Sub-pohon DOM terisolasi (encapsulated) yang terlampir pada elemen web kustom, menjaga agar gaya CSS internalnya tidak bocor keluar dan gaya CSS global luar tidak merusak tampilan internalnya", "Elemen DOM berbayang transparan yang digunakan khusus untuk membuat efek animasi bayangan 3D", "Salinan cadangan dari struktur halaman yang disimpan di memori RAM untuk kecepatan mundur tombol Back browser", "Tag HTML tersembunyi yang hanya bisa dilihat oleh mesin robot pencari (search crawler)"], correct: 0, hint: "Rahasia di balik mengapa tampilan kontrol input <video> atau <input type='range'> bawaan browser tidak rusak oleh CSS global Anda.", explanation: "Shadow DOM memberikan enkapsulasi nyata bagi Web Components. Dengan Shadow DOM, kita bisa menulis aturan CSS sederhana seperti h1 { color: red; } di dalam komponen kita, tanpa khawatir aturan itu akan merubah warna semua tag <h1> lain di seluruh halaman web." },
            { id: "web-43", category: "web", difficulty: "easy", question: "Apakah kepanjangan dari URL dan apa fungsi utamanya di internet?", answers: ["Uniform Resource Locator — alamat referensi string standar untuk menemukan dan mengakses suatu sumber daya spesifik (seperti halaman web, gambar, atau file) di jaringan internet", "Universal Router Link — kabel fisik penghubung antar router di pusat data", "Unified Relay Logic — bahasa pemrograman khusus untuk server email", "User Registration Login — formulir pendaftaran akun pengguna baru di website"], correct: 0, hint: "Alamat web yang Anda ketik di address bar browser.", explanation: "URL terdiri dari beberapa komponen penting: protokol (https://), nama domain/host (example.com), nomor port opsional (:443), jalur/path ke file (/articles/index.html), dan parameter query string (?id=123)." },
            { id: "web-44", category: "web", difficulty: "medium", question: "Apakah yang dimaksud dengan metrik 'LCP' (Largest Contentful Paint) dalam Core Web Vitals Google?", answers: ["Metrik performa yang mengukur waktu yang dibutuhkan untuk merender elemen konten visual terbesar (seperti gambar hero atau blok teks utama) di area pandang layar pengguna sejak halaman mulai dimuat", "Total ukuran file seluruh gambar PNG dan JPG yang ada di dalam sebuah website", "Persentase pengunjung yang mengklik iklan banner di halaman utama website", "Jumlah maksimal kata yang diizinkan dalam satu paragraf artikel blog"], correct: 0, hint: "Target LCP yang baik menurut standar Google adalah di bawah 2,5 detik.", explanation: "LCP adalah salah satu dari 3 metrik Core Web Vitals utama (bersama CLS dan INP). LCP mengukur persepsi kecepatan pemuatan oleh pengguna. Jika gambar hero raksasa baru muncul setelah 6 detik, pengguna akan menganggap website tersebut sangat lambat." },
            { id: "web-45", category: "web", difficulty: "hard", question: "Dalam komunikasi real-time web, apakah perbedaan utama antara 'WebSockets' dan 'Server-Sent Events' (SSE)?", answers: ["WebSockets menyediakan koneksi komunikasi dua arah (bi-directional) penuh via satu socket TCP (klien & server bisa saling kirim kapan saja); SSE adalah komunikasi satu arah (mono-directional) dari server push ke klien via HTTP biasa", "WebSockets hanya untuk data suara, sedangkan SSE hanya untuk data teks", "WebSockets berjalan di atas UDP yang tidak akurat, sedangkan SSE berjalan di atas kabel optik khusus", "WebSockets memerlukan plugin Flash eksternal, sedangkan SSE didukung langsung oleh browser modern"], correct: 0, hint: "Dua arah (Chat/Game multiplayer) vs Satu arah (Live ticker saham/Feed notifikasi).", explanation: "WebSockets ideal untuk aplikasi interaktif dua arah intensif seperti game multiplayer online atau aplikasi chat live. SSE (Server-Sent Events) sangat ringan, bekerja via HTTP/2, dan ideal untuk kasus di mana hanya server yang secara berkesinambungan mengalirkan data baru ke klien (seperti update skor bola langsung atau log dasbor)." },
            { id: "web-46", category: "web", difficulty: "medium", question: "Apakah kegunaan dari tag semantik HTML5 seperti <header>, <main>, <article>, <section>, dan <footer> dibanding menggunakan <div> untuk semuanya?", answers: ["Memberikan makna struktural yang jelas bagi pembaca layar (accessibility), membantu mesin pencari (SEO) memahami kontur dokumen, serta membuat kode lebih mudah dibaca developer", "Membuat halaman web secara otomatis berjalan 50% lebih cepat tanpa perlu optimasi gambar", "Mencegah website dari kemungkinan diretas melalui serangan SQL Injection", "Mengubah warna latar belakang setiap bagian secara otomatis menjadi warna pastel berbeda"], correct: 0, hint: "<div> adalah kontainer generik tanpa makna, tag semantik menceritakan fungsi bagian halaman.", explanation: "Penggunaan tag semantik membantu teknologi bantu (seperti screen reader) menavigasi langsung ke bagian <main> atau melewati navigasi header. Mesin pencari juga mengutamakan kata kunci yang berada di dalam tag <article> atau <header> dibanding div sembarangan." },
            { id: "web-47", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Virtual DOM' pada library antarmuka seperti React?", answers: ["Representasi ringan dari struktur DOM nyata dalam bentuk pohon objek JavaScript di memori; saat terjadi perubahan state, ia membandingkan (diffing) pohon lama dan baru lalu hanya memperbarui (patching) elemen DOM nyata yang berubah", "Browser web virtual yang berjalan di dalam server cloud untuk keperluan pengujian otomatis", "Memori cadangan harddisk yang digunakan browser jika RAM komputer kehabisan kapasitas", "Kacamata realitas maya (VR) yang dihubungkan ke komputer untuk menjelajahi website 3D"], correct: 0, hint: "Teknik rekonsiliasi (reconciliation) untuk meminimalkan manipulasi DOM fisik yang mahal dan lambat.", explanation: "Manipulasi DOM fisik langsung (seperti menambah/menghapus node) membutuhkan biaya kalkulasi layout ulang (reflow) dan pengecatan ulang (repaint) oleh browser yang mahal. Virtual DOM membatasi biaya ini dengan menghitung perbedaan (diff) di memori JS yang cepat terlebih dahulu, lalu menerapkan perubahan DOM minimum dalam satu batch efisien." },
            { id: "web-48", category: "web", difficulty: "medium", question: "Apakah fungsi dari protokol HTTPS (Hypertext Transfer Protocol Secure) dibandingkan HTTP biasa?", answers: ["Mengenyam dan mengenkripsi seluruh lalu lintas data antara browser klien dan server web menggunakan lapisan SSL/TLS, mencegah penyadapan (eavesdropping) dan manipulasi data di tengah jalan", "Membuat ukuran halaman web menjadi 10 kali lebih kecil saat dikirim melalui internet", "Menjamin bahwa website tidak akan pernah mengalami downtime atau mati server selamanya", "Membuka akses ke website terblokir di negara yang menerapkan penyaringan internet ketat"], correct: 0, hint: "Ikon gembok hijau terkunci di sebelah alamat URL browser Anda.", explanation: "Pada HTTP biasa, semua data (termasuk password, nomor kartu kredit, dan cookie sesi) dikirim dalam bentuk teks polos (plaintext) yang mudah disadap di jaringan WiFi. HTTPS mengenkripsi paket data sehingga hanya server yang memiliki Private Key sah yang dapat mendeskripsi isi pesannya." },
            { id: "web-49", category: "web", difficulty: "easy", question: "Apakah kegunaan dari properti CSS 'position: absolute;'?", answers: ["Memposisikan elemen secara mutlak di luar alur dokumen normal (normal flow), relatif terhadap elemen induk terdekatnya yang memiliki posisi selain static (atau terhadap root halaman jika tidak ada)", "Mengunci elemen di posisi layar yang sama persis meskipun pengguna melakukan scroll halaman ke bawah", "Membuat elemen berada tepat di tengah-tengah layar baik secara horizontal maupun vertikal otomatis", "Menyembunyikan elemen secara total dari tampilan layar dan dari pembaca layar tunanetra"], correct: 0, hint: "Elemen ini 'melayang' di atas elemen lain dan posisinya diatur dengan top, right, bottom, left.", explanation: "Saat elemen diberi position: absolute;, ruang yang sebelumnya ia tempati di alur dokumen langsung ditutup oleh elemen lain. Elemen tersebut kemudian mencari container terdekat yang memiliki position: relative/absolute/fixed sebagai titik acuan koordinat 0,0-nya." },
            { id: "web-50", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan serangan 'Cross-Site Scripting' (XSS) (Stored vs Reflected vs DOM-based)?", answers: ["Kerentanan keamanan di mana penyerang berhasil menyuntikkan skrip JavaScript berbahaya ke dalam halaman web yang sah, sehingga skrip tersebut dieksekusi oleh browser korban lain untuk mencuri token/cookie sesi", "Serangan memutus kabel internet server web menggunakan perangkat keras pemancar sinyal kuat", "Proses menebak sandi login administrator web dengan mencoba jutaan kombinasi kata sandi", "Kesalahan penulisan kode CSS yang membuat tampilan website berantakan di browser Safari"], correct: 0, hint: "Jangan pernah mempercayai input pengguna mentah (never trust user input without sanitization/escaping).", explanation: "Stored XSS terjadi saat skrip jahat disimpan di database (misal di kolom komentar blog) dan dieksekusi oleh setiap pengunjung yang membaca halaman itu. Pencegahan utama XSS adalah dengan selalu melakukan HTML escaping (mengubah <script> menjadi &lt;script&gt;) saat menampilkan data dinamis ke DOM." },

            // Cyber Security Extended (31-50)
            { id: "cyber-31", category: "cyber", difficulty: "easy", question: "Apakah yang dimaksud dengan teknik serangan 'Phishing'?", answers: ["Upaya penipuan rekayasa sosial (social engineering) di mana penyerang menyamar sebagai entitas terpercaya (seperti bank atau layanan populer) via email/situs palsu untuk memancing korban menyerahkan data sensitif", "Serangan membanjiri server website dengan jutaan paket ping jaringan sampai server mati", "Pencurian fisik laptop atau harddisk eksternal dari dalam kantor perusahaan", "Penggunaan virus komputer untuk menghapus seluruh file foto dan video di dalam ponsel"], correct: 0, hint: "Memancing (fishing) korban dengan umpan situs web palsu yang terlihat sangat meyakinkan.", explanation: "Phishing mengeksploitasi kelengahan psikologis manusia, bukan kelemahan sistem teknis. Korban dipicu rasa panik atau darurat ('Akun bank Anda akan diblokir dalam 24 jam! Klik link ini sekarang') sehingga mengisi username dan password di halaman web tiruan milik peretas." },
            { id: "cyber-32", category: "cyber", difficulty: "easy", question: "Apakah kegunaan utama dari penerapan Multi-Factor Authentication (MFA / 2FA)?", answers: ["Menambahkan lapisan verifikasi keamanan ekstra di luar password (seperti kode OTP dari aplikasi Authenticator, biometrik sidik jari, atau token perangkat keras fisik) untuk mencegah akses ilegal meski password bocor", "Membuat proses login otomatis langsung terbuka tanpa perlu mengetikkan kata sandi apa pun", "Mengubah warna tema antarmuka website menjadi hijau saat sistem dirasa aman dari hacker", "Menghapus akun pengguna secara otomatis jika mereka lupa login selama lebih dari 30 hari"], correct: 0, hint: "Sesuatu yang Anda tahu (Password) + Sesuatu yang Anda miliki (Ponsel/Token) + Sesuatu pada diri Anda (Biometrik).", explanation: "Jika database password sebuah website bocor dan dicuri peretas, akun yang telah mengaktifkan MFA tetap aman karena peretas tidak memiliki akses fisik ke ponsel korban untuk melihat kode verifikasi 6 angka yang berubah setiap 30 detik." },
            { id: "cyber-33", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Ransomware'?", answers: ["Jenis perangkat lunak berbahaya (malware) yang menyusup ke sistem dan mengenkripsi seluruh file penting korban, lalu menuntut pembayaran uang tebusan (biasanya dalam mata uang kripto) untuk mendapatkan kunci dekripsinya", "Program antivirus gratis palsu yang sebenarnya tidak melakukan pemindai virus sama sekali", "Pesan pop-up iklan yang muncul terus-menerus di pojok kanan bawah layar browser komputer", "Perangkat keras router jaringan yang sengaja dirusak oleh karyawan yang tidak puas"], correct: 0, hint: "Menyandera data berharga perusahaan sampai tebusan dibayar.", explanation: "Ransomware (seperti WannaCry, LockBit, atau Conti) adalah ancaman siber paling merusak bagi organisasi digital modern. Cara mitigasi terbaik adalah menjaga cadangan data offline abadi (immutable backups) yang terisolasi dari jaringan utama (air-gapped)." },
            { id: "cyber-34", category: "cyber", difficulty: "medium", question: "Apakah perbedaan antara enkripsi 'Hashing' (seperti SHA-256) dan enkripsi konvensional (seperti AES)?", answers: ["Hashing adalah fungsi satu arah (one-way) yang mengubah data menjadi sidik jari string berukuran tetap dan TIDAK BISA dikembalikan ke data asal; sedangkan Enkripsi adalah fungsi dua arah yang BISA didekripsi kembali jika memiliki kunci", "Hashing hanya untuk file gambar, sedangkan Enkripsi hanya untuk teks dokumen", "Hashing berjalan lambat memakan waktu jam, sedangkan Enkripsi selesai dalam 1 milidetik", "Hashing menggunakan 2 pasang kunci, sedangkan Enkripsi tidak membutuhkan kunci sama sekali"], correct: 0, hint: "Password disimpan dengan Hash (tidak bisa diubah balik), pesan chat disimpan dengan Enkripsi (bisa dibaca kembali penerima).", explanation: "Hashing menghasilkan cryptographic digest yang unik. Jika kita mengubah 1 huruf saja pada file 10 GB, nilai hash SHA-256-nya akan berubah total. Ini ideal untuk verifikasi integritas file dan penyimpanan password. Enkripsi (AES) dirancang agar data bisa dipulihkan kembali ke bentuk aslinya oleh pemegang kunci sah." },
            { id: "cyber-35", category: "cyber", difficulty: "medium", question: "Apakah fungsi dari 'Firewall' dalam infrastruktur keamanan jaringan?", answers: ["Perangkat lunak atau perangkat keras yang memantau, menyaring, serta mengizinkan atau memblokir lalu lintas jaringan masuk dan keluar berdasarkan seperangkat aturan keamanan yang telah ditentukan", "Alat pemadam kebakaran otomatis yang dipasang di atap ruang server pusat data komputer", "Program untuk mempercepat koneksi internet WiFi dengan memotong jalur data server lain", "Kabel fisik khusus yang tahan terhadap gigitan tikus dan induksi elektromagnetik tinggi"], correct: 0, hint: "Dinding api pengaman antara jaringan internal terpercaya dengan internet luar yang berbahaya.", explanation: "Firewall bertindak sebagai satpam gerbang jaringan. Ia memeriksa setiap paket data yang lewat, memblokir port yang berbahaya atau tidak diizinkan (seperti port database SQL 3306 dari internet publik), serta mencegah koneksi dari IP address yang masuk daftar hitam." },
            { id: "cyber-36", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Zero-Day Vulnerability' dalam dunia keamanan siber?", answers: ["Celah kerentanan keamanan baru di dalam software yang belum diketahui oleh vendor pembuat software tersebut (atau belum ada patch perbaikannya), sehingga peretas memiliki waktu eksploitasi bebas hambatan sebelum ditambal", "Hari di mana seluruh server perusahaan dimatikan secara serentak untuk perawatan rutin tahunan", "Serangan siber yang dilancarkan tepat pada pukul 00:00 tengah malam saat pergantian tahun baru", "Kondisi saat harddisk komputer mengalami kerusakan total sehingga kapasitas datanya menjadi 0 byte"], correct: 0, hint: "Vendor memiliki 'nol hari' (zero days) untuk memperbaikinya karena serangan sudah terjadi di lapangan.", explanation: "Eksploitasi Zero-Day sangat berharga dan berbahaya karena sistem pertahanan tradisional (seperti antivirus berbasis signature) belum memiliki catatan tanda tangan serangan tersebut, sehingga dapat menembus sistem pertahanan dengan mudah." },
            { id: "cyber-37", category: "cyber", difficulty: "hard", question: "Dalam kriptografi asimetris, apakah fungsi dari 'Digital Signature' (Tanda Tangan Digital)?", answers: ["Membuktikan keaslian identitas pengirim pesan (Authentication), menjamin integritas bahwa pesan tidak diubah di jalan (Integrity), serta mencegah pengirim menyangkal telah mengirim pesan tersebut (Non-repudiation)", "Mengubah gambar tanda tangan tangan basah dari kertas menjadi file gambar format PNG transparan", "Menyembunyikan isi dokumen rahasia agar tidak bisa dibaca oleh siapa pun di dunia", "Membayar bea materai pajak secara elektronik kepada pemerintah melalui situs web resmi"], correct: 0, hint: "Dibuat menggunakan Private Key pengirim, dan diverifikasi oleh siapa pun menggunakan Public Key pengirim.", explanation: "Untuk menandatangani dokumen digital, pengirim membuat nilai hash dokumen tersebut lalu mengenkripsinya dengan Private Key miliknya. Penerima dapat mendekripsi hash itu menggunakan Public Key pengirim dan mencocokkannya dengan hash dokumen yang diterima, membuktikan dokumen itu asli dan tidak dimodifikasi." },
            { id: "cyber-38", category: "cyber", difficulty: "easy", question: "Mengapa menggunakan password yang sama persis untuk semua akun online kita (seperti email, media sosial, dan bank) sangat berbahaya?", answers: ["Jika satu situs web kecil mengalami kebocoran data (data breach), peretas akan menggunakan kombinasi email dan password tersebut untuk mengambil alih seluruh akun penting Anda di situs lain (Credential Stuffing)", "Karena komputer akan mengalami kebingungan memori dan otomatis menghapus akun Anda", "Karena browser internet melarang penggunaan kata sandi yang berulang lebih dari 3 kali", "Karena kecepatan internet akan menurun drastis saat membuka situs web yang memiliki kata sandi sama"], correct: 0, hint: "Jangan menaruh semua telur Anda di dalam satu keranjang (atau satu kunci rumah untuk membuka semua bank).", explanation: "Serangan Credential Stuffing menggunakan bot otomatis untuk mencoba daftar email dan password yang bocor dari satu situs e-commerce ke ribuan situs lain seperti Gmail, PayPal, dan Netflix. Gunakan Password Manager (seperti Bitwarden atau 1Password) untuk membuat password acak unik bagi setiap situs." },
            { id: "cyber-39", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Man-in-the-Middle Attack' (MitM)?", answers: ["Serangan di mana pelaku secara diam-diam menyusup, menyadap, atau memanipulasi komunikasi pertukaran data antara dua pihak yang saling percaya (misalnya antara browser klien dan router WiFi), tanpa disadari oleh keduanya", "Serangan fisik di mana seorang peretas duduk tepat di kursi tengah antara dua karyawan di kantor", "Proses menghentikan eksekusi program di tengah jalan menggunakan fitur breakpoint debugger IDE", "Serangan memutus kabel internet tepat di tengah samudera menggunakan kapal selam khusus"], correct: 0, hint: "Penyadap yang berada di tengah-tengah jalur lalu lintas informasi.", explanation: "Dalam serangan MitM (seperti ARP Spoofing di jaringan WiFi publik atau DNS Poisoning), korban mengira sedang berbicara langsung dengan server resmi bank, padahal seluruh paket datanya mengalir melewati laptop penyerang yang dapat merekam password atau mengubah nomor rekening tujuan transfer." },
            { id: "cyber-40", category: "cyber", difficulty: "hard", question: "Apakah perbedaan antara 'Penetration Testing' (Pen-Test) dan 'Vulnerability Assessment'?", answers: ["Vulnerability Assessment adalah pemindaian otomatis untuk mendata daftar potensi kelemahan sistem tanpa mengeksploitasinya; sedangkan Pen-Test adalah simulasi serangan siber aktif oleh ethical hacker untuk membuktikan seberapa dalam kelemahan itu bisa ditembus", "Pen-Test dilakukan oleh komputer, sedangkan Vulnerability Assessment dilakukan oleh manusia", "Pen-Test hanya untuk perangkat keras router, sedangkan Vulnerability Assessment hanya untuk software", "Pen-Test adalah serangan ilegal oleh kriminal, sedangkan Vulnerability Assessment adalah perbaikan sistem"], correct: 0, hint: "Mendiagnosa daftar pintu dan jendela yang lupa dikunci vs meminta spesialis keamanan mencoba membobol masuk ke dalam rumah untuk menguji alarm.", explanation: "Vulnerability Assessment memberikan laporan keluaran alat scanner (seperti Nessus/OpenVAS). Penetration Testing melangkah lebih jauh: tim Red Team merangkai (chaining) beberapa celah kecil yang ditemukan untuk merebut hak akses root/admin, menunjukkan dampak kerugian nyata secara konkret kepada manajemen." },
            { id: "cyber-41", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan konsep 'Least Privilege' dalam manajemen hak akses keamanan?", answers: ["Prinsip bahwa setiap pengguna, program, atau sistem hanya boleh diberikan hak akses minimum yang benar-benar dibutuhkan untuk menjalankan tugas spesifiknya, dan tidak lebih", "Memberikan hak akses Administrator penuh (Root) kepada seluruh karyawan agar pekerjaan mereka lebih cepat selesai", "Membatasi waktu kerja developer maksimal hanya 4 jam sehari di depan monitor komputer", "Menghapus seluruh akun pengguna setiap akhir bulan untuk menjaga kebersihan database"], correct: 0, hint: "Jangan berikan kunci ruang brankas utama kepada staf magang yang hanya bertugas di resepsionis depan.", explanation: "Prinsip Least Privilege membatasi radius ledakan (blast radius) jika terjadi insiden. Jika akun seorang staf marketing berhasil diretas, peretas hanya bisa melihat data brosur pemasaran, dan tidak bisa mengakses database gaji karyawan atau menghapus server produksi di cloud." },
            { id: "cyber-42", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan 'SQL Injection Blind' (Time-Based vs Boolean-Based)?", answers: ["Varian serangan SQL Injection di mana aplikasi tidak menampilkan pesan error database di layar, sehingga penyerang menyimpulkan kebenaran query dari ada/tidaknya jeda waktu respons (SLEEP) atau perubahan tampilan halaman (True/False)", "Serangan mematikan lampu indikator monitor server fisik sehingga administrator menjadi buta situasi", "Pencurian data yang dilakukan oleh malware rahasia saat layar komputer dalam kondisi screensaver gelap", "Serangan yang secara otomatis mengubah seluruh kata di dalam database SQL menjadi huruf aksara buta huruf (Braille)"], correct: 0, hint: "Menarik data rahasia dari database secara perlahan, huruf demi huruf, melalui pertanyaan bertipe Ya atau Tidak.", explanation: "Pada Blind SQLi, jika penyerang menyuntikkan query: AND IF(SUBSTRING(password,1,1)='A', SLEEP(5), 0), dan server baru merespons setelah 5 detik, penyerang tahu pasti bahwa huruf pertama password admin adalah 'A'. Teknik ini mengulangi pengecekan tersebut sampai seluruh string terungkap." },
            { id: "cyber-43", category: "cyber", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Social Engineering' (Rekayasa Sosial) dalam kejahatan siber?", answers: ["Manipulasi psikologis terhadap manusia untuk memperdaya mereka agar melakukan tindakan yang mengabaikan prosedur keamanan atau menyerahkan informasi rahasia", "Rekayasa struktur bangunan fisik kantor perusahaan agar tahan terhadap gempa bumi dan kebakaran", "Pembuatan jaringan media sosial baru yang khusus ditujukan untuk para programmer komputer", "Teknik mempercepat pengunduhan file dari internet dengan membagi jalur koneksi menjadi banyak partisi"], correct: 0, hint: "Lebih mudah menipu manusia agar membukakan pintu dibanding mendobrak tembok beton firewall 10 lapis.", explanation: "Social engineering (seperti Pretexting, Baiting, Quid Pro Quo, dan Tailgating) memanfaatkan sifat alami manusia: rasa percaya, rasa takut, keinginan membantu, atau keserakahan. Pelatihan kesadaran keamanan siber (Security Awareness Training) berkala adalah satu-satunya obat penangkal efektif." },
            { id: "cyber-44", category: "cyber", difficulty: "medium", question: "Apakah fungsi dari 'Security Information and Event Management' (SIEM)?", answers: ["Platform sistem terpusat yang mengumpulkan, mengagregasi, dan menganalisis log aktivitas dari seluruh perangkat jaringan, server, dan aplikasi secara real-time untuk mendeteksi ancaman dan insiden keamanan", "Software gratis untuk mendesain tampilan tata letak visual halaman web e-commerce secara drag-and-drop", "Kabel power khusus yang dilengkapi pelindung lonjakan tegangan listrik (surge protector) otomatis", "Prosedur hukum standar untuk mendaftarkan hak paten merek dagang perangkat lunak ke negara"], correct: 0, hint: "Pusat kendali intelijen (Security Operations Center / SOC) yang mengawasi seluruh aktivitas aneh di perusahaan.", explanation: "SIEM (seperti Splunk, IBM QRadar, atau ELK Stack) menghubungkan titik-titik data terpisah. Jika ada 5 kali kegagalan login di VPN dari Rusia, diikuti oleh pembukaan port firewall 1 menit kemudian, aturan korelasi SIEM langsung membunyikan alarm bahaya kritis bagi tim SOC." },
            { id: "cyber-45", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan serangan 'SSRF' (Server-Side Request Forgery)?", answers: ["Kerentanan di mana penyerang memanipulasi aplikasi server agar melakukan request HTTP/jaringan ke lokasi arbitrer (sering kali ke layanan internal tertutup seperti cloud metadata 169.254.169.254 atau database lokal)", "Serangan memalsukan tanda tangan digital pada email agar terlihat seperti dikirim oleh CEO perusahaan", "Proses menghapus tabel database SQL dari jarak jauh menggunakan skrip otomatis peramban web", "Serangan membanjiri jaringan lokal dengan permintaan alamat IP baru ke server DHCP sampai penuh"], correct: 0, hint: "Menjadikan server web sah sebagai 'boneka proxy' untuk menyerang jaringan internal di belakang firewall.", explanation: "Pada SSRF, jika aplikasi memiliki fitur unduh gambar dari URL inputan user (misal: ?url=http://example.com/image.png), penyerang mengganti URL tersebut menjadi ?url=http://localhost:8080/admin atau ke URL metadata cloud AWS (http://169.254.169.254/latest/meta-data/) untuk mencuri kredensial server cloud." },
            { id: "cyber-46", category: "cyber", difficulty: "medium", question: "Apakah kegunaan dari 'Sandboxing' dalam analisis malware dan keamanan sistem operasi?", answers: ["Lingkungan eksekusi terisolasi yang dibatasi secara ketat, di mana program atau file yang mencurigakan dapat dijalankan secara aman tanpa risiko merusak sistem operasi asli atau mengakses data sensitif di luar kotak", "Tempat menyimpan pasir fisik untuk memadamkan kebakaran perangkat keras di ruang server pusat", "Metode membersihkan debu dari dalam kipas pendingin prosesor laptop menggunakan semprotan udara kering", "Teknik mempercepat kinerja harddisk SSD dengan menghapus blok memori yang rusak secara berkala"], correct: 0, hint: "Seperti bermain di bak pasir anak-anak: apa pun yang dibangun atau dihancurkan di dalam bak, lantai rumah di luarnya tetap aman dan bersih.", explanation: "Sandboxing digunakan oleh browser modern (untuk memisahkan proses antar tab), program antivirus (untuk meledakkan malware di mesin virtual terisolasi guna meneliti perilakunya), serta sistem operasi mobile (di mana aplikasi Android/iOS tidak bisa mengakses file aplikasi lain tanpa izin eksplisit melalui mekanisme IPC atau content provider)." },
            { id: "cyber-47", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan konsep 'Defense in Depth' (Pertahanan Berlapis) dalam arsitektur keamanan?", answers: ["Strategi menerapkan banyak lapisan kontrol keamanan yang saling melengkapi di seluruh sistem (seperti firewall, MFA, enkripsi, IDS/IPS, dan pelatihan staf), sehingga bila satu lapisan bobol, lapisan berikutnya tetap menahan penyerang", "Memasang satu buah software antivirus super mahal yang diklaim mampu memblokir 100% semua jenis serangan", "Menyembunyikan server perusahaan di ruang bawah tanah rahasia yang kedalamannya minimal 10 meter di bawah tanah", "Menggunakan password berukuran sangat panjang minimal 100 karakter untuk akun administrator tunggal"], correct: 0, hint: "Ibarat kastil abad pertengahan yang memiliki parit air, jembatan angkat, gerbang besi tebal, tembok tinggi, dan menara pemanah.", explanation: "Tidak ada satu pun teknologi keamanan yang sempurna (silver bullet). Defense in Depth memastikan bahwa jika peretas berhasil menembus firewall perimeter eksternal, mereka masih harus berhadapan dengan segmentasi jaringan internal, enkripsi database, monitoring EDR di endpoint, dan pembatasan hak akses IAM." },
            { id: "cyber-48", category: "cyber", difficulty: "medium", question: "Apakah perbedaan antara enkripsi 'At-Rest' dan enkripsi 'In-Transit'?", answers: ["Enkripsi At-Rest melindungi data statis yang disimpan dalam media penyimpanan (seperti harddisk, SSD, atau database); sedangkan Enkripsi In-Transit melindungi data saat sedang dikirim melalui jaringan (seperti HTTPS/TLS)", "Enkripsi At-Rest hanya untuk komputer kantor, sedangkan Enkripsi In-Transit hanya untuk ponsel mobile", "Enkripsi At-Rest bekerja di malam hari saat server istirahat, sedangkan Enkripsi In-Transit bekerja di siang hari", "Enkripsi At-Rest tidak memerlukan password kunci, sedangkan Enkripsi In-Transit memerlukan 10 kunci berbeda"], correct: 0, hint: "Melindungi barang saat tersimpan di dalam gudang brankas vs melindungi barang saat sedang diangkut oleh truk pengantar di jalan raya.", explanation: "Keamanan data yang menyeluruh menuntut perlindungan di kedua status. Enkripsi At-Rest (seperti BitLocker atau AWS KMS) memastikan jika harddisk dicuri secara fisik dari server, datanya tidak bisa dibaca. Enkripsi In-Transit (SSL/TLS/IPsec) memastikan data tidak disadap saat melintasi kabel jaringan atau internet terbuka menuju klien." },
            { id: "cyber-49", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Zero-Day Vulnerability' dan mengapa celah ini sangat berbahaya?", answers: ["Celah keamanan baru pada perangkat lunak atau perangkat keras yang belum diketahui oleh pihak pengembang atau belum memiliki patch/tambalan resmi, sehingga penyerang dapat mengeksploitasinya tanpa ada deteksi awal", "Virus komputer yang langsung menghapus seluruh data harddisk dalam waktu nol hari (langsung saat diunduh)", "Serangan siber yang dilakukan tepat pada hari tahun baru atau hari libur nasional saat kantor tutup", "Mekanisme reset kata sandi otomatis yang wajib dilakukan oleh karyawan setiap nol hari sekali"], correct: 0, hint: "Disebut 'Zero-Day' karena pengembang memiliki tepat 0 hari untuk memperbaikinya sejak celah itu mulai diserang oleh peretas di dunia nyata.", explanation: "Zero-Day Eksploit adalah mimpi buruk bagi praktisi keamanan siber karena sistem pertahanan tradisional (seperti antivirus berbasis signature) belum memiliki catatan sidik jarinya. Satu-satunya cara mendeteksi eksploitasi zero-day sebelum patch tersedia adalah melalui pemantauan perilaku anomali (Heuristics/Behavioral Analysis) dan segmentasi jaringan yang ketat." },
            { id: "cyber-50", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Cross-Site Request Forgery' (CSRF) token dan bagaimana ia melindungi aplikasi web?", answers: ["Nilai rahasia acak unik yang dihasilkan oleh server dan disisipkan ke dalam setiap form/request sah pengguna; server menolak request jika token ini hilang atau tidak cocok, memblokir request palsu dari situs pihak ketiga", "Token mata uang digital kripto yang harus dibayar pengguna setiap kali mereka ingin mengirim form di website", "Program pembaca kartu pintar fisik yang dicolokkan ke port USB komputer untuk verifikasi login admin", "Algoritma kompresi gambar otomatis untuk mempercepat waktu render halaman web di peramban mobile"], correct: 0, hint: "Tiket rahasia sekali pakai yang membuktikan bahwa Anda benar-benar mengklik tombol submit itu dari dalam website resmi, bukan dari link jebakan di situs lain.", explanation: "Karena browser secara otomatis melampirkan cookie sesi ke setiap request yang menuju domain tersebut, serangan CSRF memanfaatkan cookie ini dari situs jahat eksternal. Anti-CSRF token (yang tidak disimpan di cookie dan tidak bisa dibaca oleh situs lain) memastikan bahwa request benar-benar berasal dari antarmuka DOM web kita sendiri." },

            // AI & Machine Learning (1-30)
            { id: "ai-1", category: "ai", difficulty: "easy", question: "Apakah perbedaan utama antara Artificial Intelligence (AI), Machine Learning (ML), dan Deep Learning (DL)?", answers: ["AI adalah konsep luas kecerdasan buatan, ML adalah bagian dari AI di mana mesin belajar dari data, dan DL adalah bagian dari ML yang menggunakan jaringan saraf tiruan (neural networks) berlapis banyak", "AI hanya untuk robot fisik, ML untuk spreadsheet komputer, dan DL untuk animasi video di browser", "DL ditemukan tahun 1950, sedangkan AI dan ML baru diciptakan pada tahun 2020", "AI, ML, dan DL adalah tiga istilah yang 100% sama dan tidak memiliki perbedaan definisi di dunia akademik"], correct: 0, hint: "Lingkaran bersarang: AI mencakup ML, dan ML mencakup DL.", explanation: "Artificial Intelligence adalah payung besar untuk semua sistem yang meniru kecerdasan manusia. Machine Learning berfokus pada algoritma statistik agar sistem bisa belajar mandiri dari data tanpa diprogram eksplisit. Deep Learning menggunakan arsitektur Neural Network multi-layer (seperti CNN, RNN, Transformer) untuk menangani data kompleks seperti gambar, suara, dan bahasa alami." },
            { id: "ai-2", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Natural Language Processing' (NLP)?", answers: ["Cabang AI yang memberi kemampuan pada komputer untuk memahami, menafsirkan, dan menghasilkan bahasa manusia secara alami baik tertulis maupun lisan", "Proses mempercepat kecepatan pemrosesan CPU komputer secara alami tanpa kipas pendingin tambahan", "Bahasa pemrograman baru yang menggunakan instruksi berupa gambar ikon alami", "Protokol jaringan untuk mengirim pesan suara antar server di pusat data cloud"], correct: 0, hint: "Teknologi di balik chatbot, penerjemah otomatis, dan analisis sentimen komentar.", explanation: "NLP menggabungkan linguistik komputasi dengan pemodelan statistik dan deep learning. Contoh aplikasi NLP mencakup Google Translate, pemahaman perintah suara pada Siri/Alexa, pendeteksi spam email, serta Large Language Models (LLM)." },
            { id: "ai-3", category: "ai", difficulty: "easy", question: "Apakah fungsi dari 'Activation Function' (seperti ReLU, Sigmoid, Softmax) dalam Artificial Neural Network?", answers: ["Memperkenalkan sifat non-linieritas ke dalam model saraf tiruan, memungkinkan jaringan untuk mempelajari pola yang kompleks dari data", "Menyala-matikan aliran listrik pada perangkat keras kartu grafis (GPU) server AI", "Menghapus baris data duplikat secara otomatis sebelum dilatih ke dalam model", "Mengubah warna tema antarmuka visual dasbor dari terang menjadi gelap"], correct: 0, hint: "Tanpa fungsi non-linier ini, seratus lapisan neural network hanya akan setara dengan satu regresi linier sederhana.", explanation: "Jika neuron hanya melakukan perkalian bobot dan penambahan bias (W*X + b), maka seluruh jaringan hanya berupa transformasi linier. Activation Function seperti ReLU (Rectified Linear Unit) memungkinkan neural network memodelkan hubungan non-linier yang rumit seperti klasifikasi gambar wajah atau pemahaman teks." },
            { id: "ai-4", category: "ai", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Large Language Model' (LLM) dan arsitektur 'Transformer'?", answers: ["Model AI yang dilatih dengan korpus teks sangat besar berbasis arsitektur Transformer yang menggunakan mekanisme 'Self-Attention' untuk memahami konteks dan hubungan antar kata secara paralel", "Sistem database relasional raksasa untuk menyimpan kamus seluruh bahasa daerah di dunia", "Robot perangkat lunak yang secara otomatis mengubah struktur halaman web HTML lama menjadi baru", "Algoritma kompresi file teks agar berukuran 99% lebih kecil di harddisk lokal"], correct: 0, hint: "Huruf 'T' pada GPT (Generative Pre-trained Transformer) dan mekanisme perhatian (Attention is All You Need).", explanation: "Arsitektur Transformer (diperkenalkan tahun 2017) merevolusi AI karena mampu memproses seluruh urutan kata secara bersamaan (paralel) dan memberi bobot perhatian (Self-Attention) pada kata-kata penting yang saling berhubungan jauh di dalam kalimat, mengatasi kelemahan RNN lama." },
            { id: "ai-5", category: "ai", difficulty: "medium", question: "Apakah perbedaan antara teknik 'Fine-Tuning' dan 'Prompt Engineering' dalam pemanfaatan model AI?", answers: ["Fine-Tuning melatih ulang sebagian bobot model dasar menggunakan dataset spesifik baru; Prompt Engineering mendesain instruksi teks input optimal tanpa mengubah parameter bobot model", "Fine-Tuning dilakukan di browser telepon, sedangkan Prompt Engineering hanya di superkomputer", "Fine-Tuning selalu gratis tanpa biaya komputasi, sedangkan Prompt Engineering memerlukan ribuan GPU", "Fine-Tuning untuk menghasilkan gambar foto, sedangkan Prompt Engineering hanya untuk audio suara"], correct: 0, hint: "Mengubah parameter otak AI (Fine-Tuning) vs menyusun pertanyaan/instruksi yang jelas agar AI memberi jawaban terbaik (Prompt Engineering).", explanation: "Prompt engineering memanfaatkan kemampuan in-context learning LLM dengan teknik seperti Few-Shot Prompting atau Chain-of-Thought. Fine-Tuning dibutuhkan ketika model harus menguasai domain keahlian mendalam, gaya bahasa khusus, atau format output ketat yang tidak bisa dicapai hanya dengan instruksi prompt." },
            { id: "ai-6", category: "ai", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Overfitting' dan 'Underfitting' dalam pelatihan model Machine Learning?", answers: ["Overfitting terjadi saat model terlalu menghafal data latih dan gagal generalisasi ke data baru; Underfitting terjadi saat model terlalu sederhana sehingga tidak mampu menangkap pola dasar data latih", "Overfitting adalah memori GPU penuh, sedangkan Underfitting adalah harddisk server kosong", "Overfitting membuat model berjalan sangat lambat di peramban, Underfitting membuat aplikasi tertutup otomatis", "Overfitting adalah kesalahan sintaks Python, sedangkan Underfitting adalah kesalahan koneksi API cloud"], correct: 0, hint: "Menghafal jawaban ujian sampai titik komanya vs tidak belajar sama sekali sehingga tidak tahu materi.", explanation: "Model ideal berada pada titik keseimbangan bias-variance trade-off. Untuk mengatasi overfitting, engineer menggunakan teknik seperti Regularisasi (L1/L2), Dropout pada neural network, Cross-Validation, atau menambah variasi data latih (Data Augmentation)." },
            { id: "ai-7", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Gradient Descent' dalam optimasi model neural network?", answers: ["Algoritma optimasi iteratif yang menyesuaikan parameter (bobot/bias) ke arah kemiringan negatif dari fungsi kerugian (loss function) guna mencari nilai kesalahan minimum", "Metode mengurutkan baris data di dalam database SQL dari abjad terbesar ke terkecil", "Proses menurunkan tegangan listrik GPU secara bertahap untuk mencegah overheat saat training AI", "Teknik menghapus lapisan terluar neural network secara otomatis untuk mempercepat inferensi"], correct: 0, hint: "Ibarat mendaki turun dari puncak gunung di tengah kabut gelap dengan langkah demi langkah menuju lembah terendah.", explanation: "Gradient Descent menghitung turunan parsial (gradien) dari Loss Function terhadap setiap bobot menggunakan teknik Backpropagation. Bobot kemudian diperbarui sedikit demi sedikit sesuai Learning Rate sampai model mencapai titik konvergensi dengan kesalahan terkecil." },
            { id: "ai-8", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Reinforcement Learning' (RL) dan komponen utamanya (Agent, Environment, State, Action, Reward)?", answers: ["Paradigma pembelajaran di mana sebuah agen (agent) belajar mengambil keputusan berurutan melalui uji coba (trial-and-error) berinteraksi dengan lingkungan (environment) demi memaksimalkan kumulatif imbalan (reward)", "Pembelajaran AI menggunakan dataset gambar berlabel ganda yang diverifikasi oleh 10 orang manusia", "Sistem cadangan otomatis yang melatih ulang model AI setiap malam saat tidak ada traffic pengguna", "Metode kompresi model deep learning menjadi ukuran super kecil untuk berjalan di mikrokontroler"], correct: 0, hint: "Cara kerja AI mengalahkan juara dunia catur, Go (AlphaGo), atau melatih robot berjalan seimbang.", explanation: "Dalam Reinforcement Learning, agen tidak diberi tahu langkah apa yang benar atau salah secara langsung. Agen mengeksplorasi tindakan di dalam lingkungan, menerima reward (jika bagus) atau penalti (jika buruk), dan menggunakan kebijakan (Policy) yang terus diperbarui untuk memaksimalkan hasil jangka panjang." },
            { id: "ai-9", category: "ai", difficulty: "medium", question: "Apakah kegunaan utama dari 'Convolutional Neural Network' (CNN)?", answers: ["Arsitektur jaringan saraf yang berspesialisasi dalam mengekstraksi fitur spasial (seperti tepi, tekstur, dan bentuk) dari data grid struktural seperti gambar dan video untuk klasifikasi atau deteksi objek", "Mengubah data teks dokumen panjang menjadi tabel ringkasan database secara real-time", "Menghitung rute tercepat pengiriman barang kurir di atas peta jalan perkotaan", "Menerjemahkan kode bahasa C++ lawas menjadi kode JavaScript modern secara otomatis"], correct: 0, hint: "Menggunakan filter konvolusi yang menggeser (sliding window) di atas piksel gambar.", explanation: "CNN menggunakan operasi konvolusi dan pooling (seperti Max Pooling) untuk mereduksi dimensi gambar sambil mempertahankan informasi spasial penting. Hal ini membuat CNN sangat tangguh dan efisien untuk pengenalan wajah, diagnosa medis lewat sinar-X, dan kendali mobil otonom." },
            { id: "ai-10", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'RAG' (Retrieval-Augmented Generation) dalam aplikasi Large Language Model?", answers: ["Teknik yang menggabungkan kemampuan pencarian informasi eksternal (biasanya dari vector database) dengan kemampuan generasi teks LLM, sehingga jawaban AI lebih faktual, terkini, dan berbasis sumber internal", "Metode menghapus kata-kata kasar dan berbahaya dari dalam output model bahasa sebelum ditampilkan", "Proyek pengembangan robotika otomatis berbasis algoritma genetika dan jaringan saraf bersarang", "Sistem penghematan penggunaan token API LLM dengan memotong kalimat pertanyaan yang terlalu panjang"], correct: 0, hint: "Memberi LLM 'buku catatan terbuka' eksternal (Open-book exam) sebelum ia menjawab pertanyaan Anda.", explanation: "LLM memiliki keterbatasan pengetahuan statis pada data latihannya (knowledge cutoff) dan rentan mengalami halusinasi. RAG mengatasi hal ini: saat pengguna bertanya, sistem terlebih dahulu mengambil dokumen relevan dari database vektor (Retrieval), lalu menyisipkan konteks tersebut ke dalam prompt LLM untuk menyusun jawaban akurat (Generation)." },
            { id: "ai-11", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Hallucination' (Halusinasi) pada Generative AI?", answers: ["Fenomena ketika model AI menghasilkan informasi yang terdengar sangat meyakinkan dan fasih, namun sesungguhnya keliru, tidak akurat, atau sepenuhnya fiktif (mengarang bebas)", "Kondisi di mana monitor layar komputer menampilkan efek bayangan ganda karena gangguan kartu grafis", "Kapasitas model AI yang berhasil melampaui kecerdasan manusia dalam semua aspek ilmiah", "Sistem keamanan AI yang menolak menjawab pertanyaan sensitif terkait privasi atau hukum"], correct: 0, hint: "Menjawab dengan sangat percaya diri padahal jawabannya salah total.", explanation: "LLM pada dasarnya adalah model probabilitas yang memprediksi kata berikutnya yang paling masuk akal secara statistik, bukan database fakta rasional. Jika konteks tidak cukup, AI bisa 'berhalusinasi' mengarang nama jurnal ilmiah palsu, undang-undang fiktif, atau peristiwa yang tidak pernah terjadi." },
            { id: "ai-12", category: "ai", difficulty: "medium", question: "Apakah fungsi dari 'Vector Database' (seperti Pinecone, Chroma, Qdrant, atau pgvector) dalam ekosistem AI modern?", answers: ["Menyimpan data dalam bentuk representasi angka multi-dimensi (embedding vectors) untuk memungkinkan pencarian kesamaan makna/semantik (semantic similarity search) berkecepatan tinggi", "Menyimpan file gambar vektor format SVG khusus untuk keperluan animasi grafis website", "Menggantikan peran database SQL dalam menangani transaksi perbankan harian berstempel waktu", "Menyimpan log error server dalam bentuk diagram grafik vektor garis vertikal dan horizontal"], correct: 0, hint: "Mencari dokumen berdasarkan 'kemiripan arti/makna kalimat', bukan sekadar pencarian kata kunci huruf persis.", explanation: "Model embedding mengubah teks, gambar, atau audio menjadi deretan angka numerik (vektor). Kalimat dengan makna mirip akan berada dekat di dalam ruang vektor. Vector database dirancang khusus untuk melakukan pencarian tetangga terdekat (Nearest Neighbor Search) dalam hitungan milidetik guna mendukung arsitektur RAG." },
            { id: "ai-13", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Recurrent Neural Network' (RNN) dan mengapa ia digantikan oleh Transformer untuk urutan data panjang?", answers: ["RNN memproses data berurutan langkah demi langkah (menggunakan hidden state), namun mengalami masalah 'Vanishing/Exploding Gradient' sehingga lupa pada konteks awal kalimat panjang; Transformer mengatasi ini dengan pemrosesan paralel dan Self-Attention", "RNN hanya bekerja di komputer lama tahun 1990, sedangkan Transformer bekerja di komputer modern", "RNN adalah bahasa pemrograman AI, sedangkan Transformer adalah perangkat keras kartu grafis", "RNN menghasilkan output suara audio, sedangkan Transformer hanya menghasilkan output teks angka"], correct: 0, hint: "Membaca kata per kata secara urut (mudah lupa awal kalimat panjang) vs melihat seluruh paragraf sekaligus dengan perhatian langsung.", explanation: "Meskipun varian RNN seperti LSTM dan GRU mencoba memperbaiki memori jangka panjang, arsitekturnya yang sekuensial tidak bisa diparalelkan di GPU secara optimal saat training. Transformer memproses seluruh urutan kata secara simultan dan menghitung bobot keterhubungan antar kata secara langsung, menghasilkan performa dan efisiensi yang jauh lebih unggul." },
            { id: "ai-14", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Computer Vision'?", answers: ["Bidang AI yang melatih komputer untuk menafsirkan, memahami, dan mengekstraksi informasi bermakna dari dunia visual digital seperti foto, video, dan kamera langsung", "Kacamata realitas maya (VR) terbaru yang dilengkapi layar resolusi tinggi 8K untuk bermain game", "Program pemindai virus yang mendeteksi kerusakan pada berkas gambar JPG di harddisk eksternal", "Teknik memperbesar ukuran monitor komputer agar tidak melelahkan mata developer saat menulis kode"], correct: 0, hint: "Memberikan mata dan otak visual kepada komputer untuk mendeteksi wajah, plat nomor, atau tumor di foto medis.", explanation: "Computer Vision mengubah matriks angka piksel menjadi pemahaman tingkat tinggi. Contoh aplikasinya meliputi Optical Character Recognition (OCR), pendeteksi pejalan kaki pada mobil otonom, kendali mutu otomatis di pabrik, serta filter wajah dinamis di media sosial." },
            { id: "ai-15", category: "ai", difficulty: "medium", question: "Apakah perbedaan antara 'Generative AI' dan 'Discriminative AI'?", answers: ["Generative AI mempelajari distribusi data untuk menghasilkan konten/data baru (teks, gambar, musik); Discriminative AI membedakan atau mengklasifikasikan data yang sudah ada ke dalam kategori/label tertentu", "Generative AI untuk analisis statistik keuangan, Discriminative AI untuk membuat lukisan digital 3D", "Generative AI berjalan tanpa internet, sedangkan Discriminative AI wajib terhubung ke server cloud", "Generative AI dan Discriminative AI adalah nama lain dari regresi linier sederhana dan regresi logistik"], correct: 0, hint: "Menciptakan lukisan baru (Generators/DALL-E) vs membedakan apakah lukisan itu asli atau palsu / foto kucing atau anjing (Classifiers).", explanation: "Model diskriminatif (seperti klasifikasi spam atau detektor objek CNN) memetakan input X langsung ke label Y. Model generatif (seperti GANs, Diffusion Models, dan LLM) mempelajari probabilitas bersama P(X,Y) sehingga mampu mensintesis instance X baru yang realistis dari prompt sederhana." },
            { id: "ai-16", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Diffusion Model' (seperti Stable Diffusion atau Midjourney) dalam sintesis gambar AI?", answers: ["Model generatif yang dilatih dengan cara menambahkan noise acak ke gambar secara bertahap sampai hancur, lalu belajar membalikkan proses tersebut (denoising) untuk merekonstruksi gambar jernih dari noise acak berpandu teks", "Model AI yang menyalin potongan kecil dari jutaan gambar di internet lalu menempelkannya kembali seperti kolase", "Algoritma pewarnaan otomatis pada foto hitam-putih kuno menggunakan interpolasi warna RGB dasar", "Sistem transmisi video streaming tanpa putus yang menyesuaikan resolusi gambar dengan kecepatan internet"], correct: 0, hint: "Mengubah kabut asap noise acak menjadi mahakarya lukisan detail langkah demi langkah.", explanation: "Selama pelatihan, Diffusion Model mempelajari bagaimana noise merusak gambar di setiap langkah waktu (Forward Diffusion). Saat inferensi, model memulai dari kanvas noise murni dan secara iteratif membersihkannya (Reverse Diffusion) di bawah bimbingan vektor teks (dari CLIP/text encoder) sampai terbentuk gambar baru." },
            { id: "ai-17", category: "ai", difficulty: "medium", question: "Apakah kegunaan dari teknik 'Transfer Learning' dalam Machine Learning?", answers: ["Mengambil model yang sudah dilatih pada dataset raksasa untuk tugas umum (seperti ImageNet), lalu menyesuaikannya dengan sedikit data dan pelatihan tambahan untuk tugas spesifik baru", "Mtransfer seluruh file database AI dari satu server cloud di Amerika ke server lain di Asia", "Mengubah model AI berbasis Python agar bisa berjalan di dalam kode JavaScript frontend peramban", "Menyalin bobot neural network dari komputer satu ke komputer lain menggunakan kabel USB-C"], correct: 0, hint: "Mengapa mulai membangun roda dari nol jika Anda bisa memanfaatkan mesin Ferrari yang sudah ada dan tinggal mengganti ban mobilnya?", explanation: "Transfer Learning menghemat ribuan jam komputasi GPU dan jutaan rupiah. Sebagai contoh, alih-alih melatih model deteksi rontgen paru-paru dari nol dengan ribuan gambar, kita bisa menggunakan model ResNet/BERT yang sudah memahami pola umum, lalu melakukan fine-tuning pada lapisan terakhirnya saja dengan beberapa ratus gambar medis." },
            { id: "ai-18", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Bias' dan 'Fairness' dalam etika kecerdasan buatan?", answers: ["Kecenderungan model AI menghasilkan keputusan yang tidak adil, diskriminatif, atau merugikan kelompok demografi tertentu karena mewarisi ketimpangan atau prasangka yang ada di dalam data latihnya", "Kesalahan teknis saat GPU server AI kekurangan daya listrik sehingga kalkulasi angkanya meleset", "Preferensi model AI untuk memilih warna tema antarmuka gelap dibandingkan tema terang", "Peraturan hukum pemerintah yang melarang penggunaan AI untuk keperluan komersial di sekolah"], correct: 0, hint: "Jika data rekrutmen masa lalu didominasi satu kelompok, AI rekrutmen akan menolak pelamar dari kelompok lain secara otomatis.", explanation: "AI adalah cermin data latihannya. Jika sistem pengenalan wajah dilatih terutama dengan foto satu ras tertentu, akurasinya akan anjlok saat mengenali ras lain. Memastikan fairness melibatkan audit dataset, pemantauan metrik kesetaraan, dan mitigasi bias sebelum model diterjunkan ke masyarakat." },
            { id: "ai-19", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Zero-Shot Prompting' dan 'Few-Shot Prompting'?", answers: ["Zero-Shot adalah memberi instruksi ke AI tanpa contoh jawaban sama sekali; Few-Shot adalah menyertakan beberapa contoh pasangan input-output di dalam prompt agar AI meniru pola tersebut", "Zero-Shot adalah model AI tanpa parameter bobot, Few-Shot adalah model AI dengan 10 parameter bobot", "Zero-Shot menghasilkan jawaban dalam 0 milidetik, Few-Shot membutuhkan waktu beberapa menit", "Zero-Shot hanya untuk gambar foto, sedangkan Few-Shot hanya untuk teks dokumen panjang"], correct: 0, hint: "Langsung suruh vs beri 2-3 contoh terlebih dahulu agar pola formatnya ditiru akurat.", explanation: "Pada Zero-Shot: 'Terjemahkan ke bahasa Prancis: Halo dunia'. Pada Few-Shot, kita memberi panduan format: 'Terjemahkan ke bahasa Prancis.\nInggris: Good morning -> Prancis: Bonjour\nInggris: Thank you -> Prancis: Merci\nInggris: Halo dunia -> Prancis: ...'. Few-Shot secara signifikan meningkatkan akurasi dan konsistensi format output LLM." },
            { id: "ai-20", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Quantization' (Kuantisasi) dalam optimasi model Deep Learning?", answers: ["Teknik mengurangi presisi numerik bobot model (misalnya dari floating-point 32-bit FP32 menjadi integer 8-bit INT8 atau 4-bit INT4) guna memperkecil ukuran memori dan mempercepat eksekusi tanpa banyak mengorbankan akurasi", "Proses menghapus 50% neuron secara acak dari dalam jaringan saat inferensi berlangsung", "Membagi satu model AI raksasa menjadi 10 model kecil yang berjalan di 10 server terpisah", "Mengubah seluruh kata dalam kamus LLM menjadi nomor indeks angka biner 0 dan 1"], correct: 0, hint: "Rahasia mengapa model Llama 70B yang aslinya butuh VRAM 140 GB bisa dijalankan di laptop lokal dengan VRAM 32 GB saja.", explanation: "Kuantisasi memungkinkan model AI besar berjalan pada perangkat keras edge atau GPU konsumen. Dengan memetakan bobot FP32 ke representasi INT8/INT4 (seperti teknik QLoRA atau GGUF), ukuran file model berkurang drastis hingga 75% dan kecepatan komputasi meningkat berkat dukungan instruksi integer perangkat keras." },
            { id: "ai-21", category: "ai", difficulty: "medium", question: "Apakah perbedaan antara 'Supervised Learning', 'Unsupervised Learning', dan 'Self-Supervised Learning'?", answers: ["Supervised butuh label manusia, Unsupervised mencari klaster tanpa label, dan Self-Supervised menciptakan label sendiri dari bagian data yang ada (seperti menebak kata yang disembunyikan dalam kalimat)", "Supervised untuk gambar, Unsupervised untuk teks, Self-Supervised untuk suara audio", "Supervised gratis, Unsupervised berbayar mahal, Self-Supervised hanya di superkomputer", "Ketiganya adalah nama fungsi matematika yang sama dalam regresi linier berganda"], correct: 0, hint: "Self-Supervised Learning adalah rahasia di balik pelatihan BERT dan GPT pada milyaran halaman web tanpa manusia harus melabeli setiap katanya.", explanation: "Pada Self-Supervised Learning, model mengambil data mentah tanpa label (seperti artikel Wikipedia), menyembunyikan sebagian kata (Masking), lalu melatih dirinya untuk memprediksi kata yang hilang berdasarkan konteks kata di sekitarnya. Ini membuka jalan bagi Foundation Models skala raksasa." },
            { id: "ai-22", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'AI Agent' (Agen AI Autonom)?", answers: ["Sistem AI yang mampu merencanakan langkah-langkah, menggunakan alat bantu (tools/API), mengingat konteks, dan mengeksekusi tugas kompleks secara mandiri demi mencapai tujuan yang ditentukan pengguna", "Robot fisik yang bisa berjalan dan berbicara layaknya manusia di dalam kantor", "Program chatbot sederhana yang hanya bisa menjawab satu pertanyaan dengan satu jawaban statis", "Sistem operasi komputer baru yang sepenuhnya menggantikan Windows dan macOS"], correct: 0, hint: "Bukan sekadar menjawab chat, melainkan mampu berpikir: 'Saya butuh cari data web -> panggil API -> simpan file -> laporkan hasil'.", explanation: "AI Agent (seperti AutoGPT atau sub-agent coding modern) melangkah melampaui tanya-jawab pasif. Dengan dilengkapi memori, kemampuan pemanggilan fungsi (Function Calling), dan siklus observasi-aksi, agen dapat meneliti codebase, menjalankan perintah terminal, dan menyelesaikan proyek software secara mandiri." },
            { id: "ai-23", category: "ai", difficulty: "medium", question: "Apakah yang dimaksud dengan parameter 'Temperature' pada inferensi Large Language Model (misal: Temperature = 0.0 vs 0.8)?", answers: ["Parameter yang mengontrol tingkat keacakan/kreativitas probabilitas pilihan kata berikutnya; nilai rendah (0.0) menghasilkan jawaban yang sangat deterministik dan fokus, nilai tinggi (0.8+) menghasilkan jawaban yang lebih kreatif dan bervariasi", "Suhu panas prosesor GPU yang dibatasi oleh sistem cloud saat menjalankan model AI", "Jumlah maksimal kata atau token yang boleh dikembalikan oleh model dalam satu respons", "Kecepatan waktu respons server diukur dalam hitungan detik untuk setiap request API"], correct: 0, hint: "0.0 untuk coding dan ekstraksi fakta yang presisi, 0.8 untuk menulis puisi dan brainstorming ide kreatif.", explanation: "Saat LLM memprediksi kata berikutnya, ia memiliki daftar distribusi probabilitas. Temperature menyesuaikan ketajaman distribusi ini. Pada Temperature 0.0, model selalu mengambil kata dengan probabilitas tertinggi (Greedy Decoding). Pada Temperature tinggi, kata-kata berprobabilitas lebih rendah memiliki peluang lebih besar untuk dipilih." },
            { id: "ai-24", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'LoRA' (Low-Rank Adaptation) dalam fine-tuning model LLM?", answers: ["Teknik fine-tuning efisien yang membekukan bobot model dasar asli dan hanya melatih matriks adaptor berperingkat rendah (low-rank matrices) berukuran kecil yang disisipkan ke dalam lapisan jaringan", "Algoritma kompresi gambar dan video otomatis untuk mempercepat koneksi internet satelit", "Protokol keamanan komunikasi radio nirkabel jarak jauh berdaya super rendah", "Metode menghapus seluruh lapisan transformer yang tidak aktif untuk menghemat daya VRAM"], correct: 0, hint: "Alih-alih memperbarui 70 milyar parameter model asli, kita cukup melatih adaptor kecil berukuran 50 MB yang ditempelkan padanya.", explanation: "Melatih ulang seluruh parameter (Full Fine-Tuning) pada model LLM berukuran puluhan gigabyte membutuhkan klaster GPU super mahal. LoRA (dan QLoRA) memecahkan masalah ini dengan mereduksi jumlah parameter yang dilatih hingga 99%, memungkinkan fine-tuning model besar di satu GPU konsumen dengan hasil akurasi setara." },
            { id: "ai-25", category: "ai", difficulty: "medium", question: "Apakah kegunaan dari 'Confusion Matrix' dalam evaluasi model klasifikasi Machine Learning?", answers: ["Tabel ringkasan yang membandingkan prediksi model dengan label kebenaran aktual, memecahnya menjadi empat kategori: True Positive, True Negative, False Positive, dan False Negative", "Matriks matematika rumit yang digunakan untuk membingungkan peretas agar tidak bisa mencuri model AI", "Tabel daftar kata-kata yang sering disalahpahami oleh model chatbot bahasa alami", "Diagram visual yang menunjukkan konsumsi memori RAM server saat proses training berlangsung"], correct: 0, hint: "Peta empat kuadran untuk melihat di mana tepatnya model Anda melakukan kesalahan diagnosis.", explanation: "Dari Confusion Matrix, kita dapat menghitung berbagai metrik evaluasi krusial seperti Accuracy (ketepatan umum), Precision (seberapa akurat prediksi positif model), Recall/Sensitivity (seberapa banyak kasus positif aktual yang berhasil ditebak), dan F1-Score (rata-rata harmonis antara precision dan recall)." },
            { id: "ai-26", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Token' dalam pemrosesan Large Language Model?", answers: ["Satuan dasar teks pecahan (bisa berupa karakter tunggal, sebagian kata, atau satu kata penuh) yang diubah oleh tokenizer menjadi angka numerik sebelum diproses oleh model AI", "Mata uang kripto digital yang harus dibayarkan setiap kali melakukan login ke website AI", "Kartu pintar fisik yang digunakan oleh engineer untuk membuka pintu ruang server superkomputer", "Sandi rahasia yang dikirimkan melalui SMS untuk memverifikasi akun pengguna baru"], correct: 0, hint: "1.000 token dalam bahasa Inggris kira-kira setara dengan sekitar 750 kata.", explanation: "LLM tidak membaca huruf abjad seperti manusia; mereka memotong kalimat menjadi sub-word tokens menggunakan algoritma seperti Byte-Pair Encoding (BPE). Kata umum seperti 'apple' bisa menjadi 1 token, sementara kata asing atau panjang dalam bahasa Indonesia bisa dipecah menjadi 2-4 token." },
            { id: "ai-27", category: "ai", difficulty: "medium", question: "Apakah yang dimaksud dengan teknik 'Chain-of-Thought' (CoT) Prompting?", answers: ["Strategi prompting yang mendorong LLM untuk menguraikan proses berpikir langkah demi langkah secara logis sebelum memberikan jawaban akhir, guna meningkatkan akurasi pada soal matematika atau logika kompleks", "Menyambungkan 10 komputer server secara berantai untuk mempercepat waktu render video", "Menulis kode program AI dalam satu baris panjang tanpa menggunakan spasi atau enter", "Metode menghapus riwayat obrolan chatbot secara otomatis setelah 24 jam berlalu"], correct: 0, hint: "Menambahkan instruksi magis: 'Mari kita pikirkan langkah demi langkah' (Let's think step by step).", explanation: "Tanpa CoT, LLM sering gagal menjawab soal penalaran multilingkah karena langsung mencoba melompat ke jawaban akhir dalam satu langkah kalkulasi probabilitas. Dengan meminta uraian langkah berpikir (CoT), model memecah masalah besar menjadi urutan sub-langkah kecil yang jauh lebih mudah dihitung dengan benar." },
            { id: "ai-28", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Generative Adversarial Network' (GAN)?", answers: ["Arsitektur AI yang mengadu dua neural network yang saling bersaing: Generator bertugas menciptakan data palsu yang realistis, sementara Discriminator bertugas membedakan mana data asli dan mana data palsu hasil ciptaan Generator", "Jaringan server komputer terdistribusi yang bekerja sama untuk memadamkan serangan siber global", "Model AI tunggal yang dilatih khusus untuk menerjemahkan bahasa daerah yang hampir punah", "Algoritma pengamanan database vektor menggunakan enkripsi kuantum tingkat tinggi"], correct: 0, hint: "Ibarat pemalsu uang (Generator) yang terus belajar membuat uang palsu lebih sempurna karena terus dideteksi oleh detektif polisi (Discriminator).", explanation: "Diperkenalkan oleh Ian Goodfellow pada 2014, GAN menciptakan dinamika permainan zero-sum game. Seiring berjalannya waktu, persaingan sengit ini memaksa Generator menghasilkan gambar wajah, suara, atau lukisan yang begitu realistis sampai Discriminator (dan mata manusia) tidak mampu lagi membedakannya dari yang asli." },
            { id: "ai-29", category: "ai", difficulty: "easy", question: "Apakah yang dimaksud dengan 'AI Alignment' dan mengapa isu ini sangat krusial bagi masa depan AI?", answers: ["Upaya riset dan teknik untuk memastikan bahwa tujuan, perilaku, dan output sistem AI sejalan dengan nilai, etika, dan keselamatan umat manusia, mencegah dampak merugikan yang tidak disengaja", "Proses meluruskan susunan kabel fisik pada rak server komputer di dalam pusat data", "Sinkronisasi otomatis antara jam sistem di komputer klien dan jam server di cloud", "Menyesuaikan ukuran font dan warna tombol pada antarmuka aplikasi AI agar rapi"], correct: 0, hint: "Memastikan super-AI tidak salah menafsirkan perintah manusia yang berakibat fatal.", explanation: "Isu AI Alignment berfokus pada masalah spesifikasi tujuan (Specification Gaming). Jika kita menyuruh AI super kuat untuk 'menghilangkan kanker dari bumi', tanpa alignment yang benar, AI mungkin menyimpulkan bahwa cara paling efisien adalah dengan menghapus seluruh manusia dari bumi. Alignment memastikan batasan moral dan empati terjaga." },
            { id: "ai-30", category: "ai", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Multi-Agent System' dalam pengembangan AI modern?", answers: ["Arsitektur di mana beberapa agen AI dengan peran dan keahlian spesifik (seperti Arsitek, Programmer, Reviewer, dan Tester) saling berkomunikasi, berkolaborasi, dan mengkritisi untuk menyelesaikan proyek berskala besar", "Sistem login yang memerlukan persetujuan dari minimal 3 orang manajer manusia sebelum dibuka", "Penggunaan 5 merk antivirus berbeda yang dijalankan bersamaan di dalam satu komputer desktop", "Sistem backup cloud yang mereplikasi satu database ke 10 pusat data di benua berbeda"], correct: 0, hint: "Tim kerja virtual autonomous di mana satu agen menulis kode dan agen lain melakukan code review serta otomatisasi tes.", explanation: "Multi-Agent System mengatasi keterbatasan konteks dan fokus dari satu LLM tunggal. Dengan membagi beban kerja ke agen-agen spesialis yang memiliki system prompt, tools, dan alur kerja tersendiri, proyek yang kompleks dapat didekomposisi, dikerjakan secara paralel, dan diuji secara ketat seperti tim pengembangan software manusia di dunia nyata." },

            // Cloud & DevOps (1-30)
            { id: "cloud-1", category: "cloud", difficulty: "easy", question: "Apakah perbedaan utama antara model layanan cloud IaaS (Infrastructure as a Service), PaaS (Platform as a Service), dan SaaS (Software as a Service)?", answers: ["IaaS menyewakan infrastruktur mentah (server/VM/storage), PaaS menyediakan platform pengembangan siap pakai tanpa kelola OS, dan SaaS menyediakan aplikasi perangkat lunak langsung pakai oleh pengguna akhir", "IaaS hanya untuk database lokal, PaaS hanya untuk game online, dan SaaS hanya untuk email kantor", "IaaS berbiaya gratis, PaaS berbiaya sekali bayar, dan SaaS berbiaya bulanan berdasarkan bandwidth", "Ketiganya adalah nama merek perangkat keras server fisik yang diproduksi oleh AWS, Azure, dan GCP"], correct: 0, hint: "IaaS = Sewa lahan & pondasi; PaaS = Sewa gedung siap interior; SaaS = Sewa kamar hotel siap tinggal.", explanation: "Dalam IaaS (misal: AWS EC2), Anda bertanggung jawab menginstal OS dan patch keamanan. Dalam PaaS (misal: Heroku, Google App Engine), Anda cukup fokus mengunggah kode aplikasi. Dalam SaaS (misal: Google Workspace, Slack), Anda langsung menggunakan fitur aplikasi tanpa memikirkan server atau kode." },
            { id: "cloud-2", category: "cloud", difficulty: "easy", question: "Apakah yang dimaksud dengan teknologi 'Containerization' (seperti Docker)?", answers: ["Metode pengemasan aplikasi beserta seluruh dependensi, pustaka (library), dan konfigurasi ke dalam satu unit standar (kontainer) terisolasi yang dapat berjalan konsisten di lingkungan OS manapun", "Proses mengemas kabel fisik server pusat data ke dalam kotak kontainer besi tahan api", "Teknik menggabungkan 10 harddisk fisik menjadi satu volume virtual besar", "Sistem pencadangan otomatis yang mengompresi database ke file berukuran kecil setiap malam"], correct: 0, hint: "Solusi abadi untuk masalah klasik programmer: 'Bisa jalan di laptop saya kok, tapi kenapa di server production error?'", explanation: "Berbeda dengan Virtual Machine (VM) yang menduplikasi seluruh Sistem Operasi tamu (Guest OS) dan berukuran ber-gigabyte, kontainer berbagi kernel OS host dan hanya membungkus aplikasi beserta pustakanya. Hasilnya, kontainer sangat ringan, menyala dalam hitungan milidetik, dan dijamin berjalan identik di laptop lokal maupun cluster cloud." },
            { id: "cloud-3", category: "cloud", difficulty: "medium", question: "Apakah fungsi utama dari 'Kubernetes' (K8s) dalam ekosistem DevOps?", answers: ["Platform orkestrasi kontainer open-source untuk mengotomatiskan penerapan (deployment), penskalaan (scaling), auto-healing, dan manajemen aplikasi berbasis kontainer secara terdistribusi", "Bahasa pemrograman baru untuk menulis skrip otomatisasi terminal di sistem operasi Linux", "Perangkat lunak antivirus yang memindai kerentanan kode pada repositori Git sebelum diunggah", "Database relasional dalam memori yang dirancang khusus untuk menampung log server mikroservis"], correct: 0, hint: "Sang kapten atau dirigen yang memimpin dan mengatur ribuan kontainer Docker agar selalu stabil dan seimbang.", explanation: "Ketika Anda memiliki ratusan kontainer yang berjalan di puluhan server, manajemen manual menjadi mustahil. Kubernetes bertindak sebagai orkestrator yang memantau kesehatan kontainer (merestart otomatis jika mati), membagi beban lalu lintas (Load Balancing), dan menambah/mengurangi instans sesuai lonjakan traffic." },
            { id: "cloud-4", category: "cloud", difficulty: "medium", question: "Apakah perbedaan antara 'Continuous Integration' (CI) dan 'Continuous Deployment/Delivery' (CD)?", answers: ["CI menguji dan menggabungkan perubahan kode secara otomatis ke repositori utama setiap kali commit; CD mengotomatiskan proses rilis dan pengiriman kode yang sudah lulus uji tersebut ke lingkungan staging atau production", "CI untuk menulis kode program, sedangkan CD untuk mendesain antarmuka grafis Figma", "CI dijalankan di komputer developer, sedangkan CD hanya bisa dijalankan di smartphone", "CI dan CD adalah nama protokol transfer file berkecepatan tinggi pengganti FTP dan SSH"], correct: 0, hint: "CI = Otomatisasi build & run unit tests saat git push; CD = Otomatisasi deploy/rilis ke server cloud.", explanation: "CI/CD Pipeline adalah jantung praktik DevOps modern. Dengan CI, bug terdeteksi lebih awal karena tes dijalankan otomatis pada setiap Pull Request. Dengan CD, rilis software dapat dilakukan puluhan kali sehari secara mulus tanpa downtime atau intervensi manual yang rentan kesalahan." },
            { id: "cloud-5", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Infrastructure as Code' (IaC) dan apa contoh alat populernya?", answers: ["Praktik mengelola dan menyediakan infrastruktur komputasi cloud (server, jaringan, load balancer, firewall) melalui file definisi kode yang dapat divarsi (seperti menggunakan Terraform atau Ansible), bukan konfigurasi manual lewat dasbor web", "Teknik mengubah perangkat keras server fisik menjadi kode biner agar bisa disimpan di dalam harddisk", "Memodifikasi BIOS motherboard server menggunakan bahasa assembly secara remote", "Sistem pemantauan server yang mengirimkan laporan kode error melalui SMS ke engineer"], correct: 0, hint: "Menulis spesifikasi server dalam file teks (misal .tf) yang bisa disimpan di Git, direview, dan dieksekusi otomatis dalam 5 menit.", explanation: "IaC menghilangkan masalah 'configuration drift' (ketidakcocokan spesifikasi antar lingkungan server). Dengan Terraform atau AWS CloudFormation, kita bisa mereplikasi seluruh infrastruktur staging yang kompleks ke production hanya dengan satu perintah terminal (terraform apply) yang konsisten, berulang, dan terdokumentasi sempurna." },
            { id: "cloud-6", category: "cloud", difficulty: "easy", question: "Apakah yang dimaksud dengan arsitektur 'Serverless' (misalnya AWS Lambda atau Google Cloud Functions)?", answers: ["Model komputasi cloud di mana pengembang dapat menjalankan fungsi kode tanpa perlu menyewa, mengonfigurasi, atau mengelola server fisik/virtual sama sekali, serta hanya membayar saat kode dijalankan", "Aplikasi web modern yang berjalan sepenuhnya offline tanpa koneksi internet sama sekali", "Pusat data cloud yang tidak memiliki perangkat keras server, melainkan menggunakan memori optik satelit", "Metode pengembangan aplikasi lokal yang tidak membutuhkan database untuk menyimpan data pengguna"], correct: 0, hint: "Bukan berarti tidak ada server sama sekali, melainkan penyedia cloud (AWS/Google) yang mengurus servernya 100% di belakang layar.", explanation: "Dalam arsitektur Serverless (FaaS - Function as a Service), Anda mengunggah potongan fungsi kode yang dipicu oleh event (misal: ada gambar baru diunggah ke S3, atau ada request HTTP datang). Server menyala dalam milidetik, mengeksekusi kode, lalu mati kembali. Jika tidak ada traffic, biaya Anda adalah $0." },
            { id: "cloud-7", category: "cloud", difficulty: "medium", question: "Apakah perbedaan antara penskalaan 'Horizontal Scaling' (Scale Out/In) dan 'Vertical Scaling' (Scale Up/Down)?", answers: ["Horizontal Scaling menambah/mengurangi jumlah instans server dalam cluster; Vertical Scaling menambah/mengurangi spesifikasi kapasitas (CPU, RAM, Storage) pada satu server fisik/virtual yang sama", "Horizontal Scaling hanya untuk database, Vertical Scaling hanya untuk server web frontend", "Horizontal Scaling selalu menyebabkan downtime total, Vertical Scaling tidak pernah downtime", "Horizontal Scaling adalah memperluas layar monitor, Vertical Scaling adalah mendirikan server rak tinggi"], correct: 0, hint: "Membeli 5 mobil kecil untuk mengangkut banyak orang bersamaan (Horizontal) vs mengganti mesin mobil Anda dengan mesin truk raksasa (Vertical).", explanation: "Vertical Scaling memiliki batas fisik (Anda tidak bisa menambah RAM satu server sampai tak terhingga) dan sering membutuhkan reboot server. Horizontal Scaling adalah standar cloud modern karena berpasangan sempurna dengan Load Balancer dan Auto Scaling Group untuk menangani traffic tak terbatas tanpa single point of failure." },
            { id: "cloud-8", category: "cloud", difficulty: "medium", question: "Apakah fungsi dari 'Load Balancer' dalam arsitektur cloud terdistribusi?", answers: ["Perangkat atau layanan jaringan yang mendistribusikan lalu lintas lalu lintas jaringan/HTTP masuk secara merata ke beberapa server backend guna mencegah kelebihan beban pada satu server dan menjamin ketersediaan tinggi (High Availability)", "Alat penstabil tegangan listrik otomatis untuk server fisik di pusat data agar tidak korsleting", "Software pemampat ukuran database SQL agar seimbang dengan kapasitas harddisk lokal", "Protokol enkripsi yang menyamakan panjang karakter sandi pengguna sebelum disimpan ke database"], correct: 0, hint: "Ibarat petugas lalu lintas di gerbang tol yang membagi antrean kendaraan secara merata ke 5 loket pembayaran yang tersedia.", explanation: "Load Balancer (seperti AWS ALB atau NGINX) juga melakukan pengecekan kesehatan (Health Check) secara kontinu. Jika salah satu server backend mati atau hang, Load Balancer otomatis mengalihkan seluruh request pengguna ke server lain yang sehat tanpa terasa oleh pengguna akhir." },
            { id: "cloud-9", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Blue-Green Deployment' dan apa keunggulannya?", answers: ["Strategi rilis aplikasi dengan memelihara dua lingkungan produksi identik (Blue yang aktif saat ini dan Green yang berisi versi baru); lalu pengalihan lalu lintas dilakukan seketika lewat load balancer/DNS untuk rilis tanpa downtime dan rollback instan jika ada bug", "Mengganti tema warna antarmuka website dari biru menjadi hijau sesuai waktu siang dan malam", "Memisahkan server untuk tim developer junior (biru) dan tim developer senior (hijau) agar tidak bentrok", "Metode menguji efisiensi konsumsi listrik server cloud antara mode hemat daya (hijau) dan mode performa (biru)"], correct: 0, hint: "Menyiapkan panggung baru yang sudah siap 100% di sebelah panggung lama, lalu cukup memindahkan sorot lampu utama ke panggung baru dalam satu detik.", explanation: "Jika pada saat peluncuran versi baru di lingkungan Green ditemukan bug kritis yang merusak aplikasi, engineer tidak perlu melakukan build ulang yang memakan waktu. Mereka cukup mengalihkan kembali rute load balancer ke lingkungan Blue yang masih menyala sempurna dalam hitungan detik (Zero-downtime rollback)." },
            { id: "cloud-10", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Service Mesh' (seperti Istio atau Linkerd) dalam arsitektur microservices?", answers: ["Lapisan infrastruktur khusus yang mengelola komunikasi antar-mikroservis (service-to-service), menyediakan observabilitas, enkripsi mTLS otomatis, routing traffic pintar, dan circuit breaking tanpa mengubah kode aplikasi", "Jaringan kabel serat optik fisik yang menghubungkan antar rak server di dalam pusat data cloud", "Antarmuka grafis web untuk menggambar diagram hubungan antar database SQL", "Protokol kompresi file untuk pengiriman data log server yang berukuran besar ke cloud storage"], correct: 0, hint: "Memasang 'satpam dan agen pengirim surat pribadi' (sidecar proxy) di sebelah setiap kontainer mikroservis Anda.", explanation: "Dalam sistem dengan 200 mikroservis, mengatur keamanan (siapa boleh panggil siapa), enkripsi lalu lintas antar servis, retry logic, dan tracing latensi di dalam kode aplikasi adalah mimpi buruk. Service Mesh menyuntikkan kontainer proxy (sidecar seperti Envoy) ke setiap pod untuk mengurus seluruh komunikasi jaringan secara transparan." },
            { id: "cloud-11", category: "cloud", difficulty: "easy", question: "Apakah fungsi dari 'Content Delivery Network' (CDN) seperti Cloudflare atau AWS CloudFront?", answers: ["Jaringan server terdistribusi global yang menyimpan salinan cache konten statis (gambar, CSS, JS, video) di lokasi geografis yang dekat dengan pengguna untuk mempercepat waktu muat dan mengurangi beban server asal", "Sistem pengantaran barang fisik ke rumah pengguna yang memesan produk melalui website toko online", "Antarmuka pemrograman untuk mengirim pesan SMS dan WhatsApp notifikasi secara massal", "Software pengamanan jaringan lokal untuk memblokir akses internet dari komputer karyawan pada jam kerja"], correct: 0, hint: "Mengapa pengguna di Jakarta bisa membuka website yang server utamanya di Amerika dalam waktu di bawah 1 detik?", explanation: "Tanpa CDN, setiap request dari seluruh dunia harus menempuh jarak ribuan kilometer menuju Origin Server. Dengan CDN, salinan halaman dan aset statis tersimpan di puluhan Edge Location di seluruh dunia. Pengguna di Indonesia akan dilayani oleh server CDN di Jakarta atau Singapura, memangkas latensi hingga 80%." },
            { id: "cloud-12", category: "cloud", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Zero Trust Architecture' dalam keamanan cloud?", answers: ["Paradigma keamanan yang berprinsip 'Jangan pernah percaya, selalu verifikasi' (Never Trust, Always Verify); setiap permintaan akses baik dari luar maupun dalam jaringan diperlakukan seolah-olah berasal dari jaringan yang tidak aman dan wajib divalidasi otentikasi serta otorisasi ketatnya", "Sistem jaringan cloud yang tidak memerlukan kata sandi sama sekali karena menggunakan pengenalan wajah", "Kebijakan perusahaan yang melarang karyawan membawa perangkat pribadi (BYOD) ke kantor", "Arsitektur database yang tidak mempercayakan penyimpanan data pada satu server, melainkan di 100 node blockchain"], correct: 0, hint: "Sudah berada di dalam jaringan kantor atau VPN tidak lagi otomatis membuat Anda dianggap aman dan dipercaya.", explanation: "Pada model keamanan perimeter kuno, sekali peretas berhasil menembus firewall atau mendapatkan VPN internal, mereka bisa leluasa menjelajahi seluruh server kantor. Zero Trust menghapus konsep 'jaringan internal terpercaya': setiap mikroservis, API, dan pengguna harus melakukan autentikasi ulang secara bertahap dengan hak akses paling minimal (Least Privilege)." },
            { id: "cloud-13", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Circuit Breaker Pattern' dalam arsitektur sistem terdistribusi/microservices?", answers: ["Pola desain ketahanan yang mendeteksi kegagalan berulang saat memanggil layanan eksternal/backend, dan secara otomatis 'memutus sirkuit' untuk langsung mengembalikan error atau fallback cepat tanpa membebani layanan yang sedang mati/down", "Alat pemutus arus listrik fisik yang dipasang pada panel listrik server pusat data saat terjadi petir", "Algoritma untuk menghentikan loop tak terhingga (infinite loop) di dalam kode program JavaScript secara otomatis", "Metode membagi satu database raksasa menjadi beberapa partisi kecil saat terjadi lonjakan traffic ekstrim"], correct: 0, hint: "Sama seperti sekering listrik di rumah Anda: memutuskan aliran sementara agar kebakaran tidak menyebar ke seluruh rumah.", explanation: "Jika Mikroservis A memanggil Mikroservis B yang sedang mengalami gangguan dan merespons sangat lambat, Mikroservis A akan terus menunggu (blocking) sampai kehabisan thread/memori dan ikut lumpuh (Cascading Failure). Circuit Breaker (seperti Resilience4j) memantau error rate; jika melampaui batas, sirkuit 'terbuka' (Open) dan langsung memberi fallback cepat tanpa mencoba memanggil B selama beberapa detik." },
            { id: "cloud-14", category: "cloud", difficulty: "easy", question: "Apakah kegunaan utama dari 'Git' dalam proses pengembangan perangkat lunak (DevOps)?", answers: ["Sistem pengontrol versi terdistribusi (Distributed Version Control System) untuk melacak setiap riwayat perubahan kode source, memungkinkan kolaborasi tim tanpa bentrok, pencabangan (branching), dan penggabungan (merging)", "Platform cloud hosting berbayar untuk menjalankan aplikasi web dengan satu klik", "Bahasa pemrograman tingkat tinggi untuk mengelola basis data NoSQL secara real-time", "Alat pengukur kecepatan koneksi internet dan pemantau bandwidth jaringan server"], correct: 0, hint: "Penyelamat hidup developer yang memungkinkan Anda melihat siapa yang mengubah baris kode apa, kapan, mengapa, dan bisa undo kapan saja.", explanation: "Sebelum Git (diciptakan oleh Linus Torvalds), tim programmer mengelola kode dengan nama file seperti `project-final-v2-revisi3.zip`. Git mencatat setiap snapshot perubahan secara kriptografis, memungkinkan ribuan engineer bekerja paralel di branch masing-masing dan menggabungkannya ke branch `main` dengan aman." },
            { id: "cloud-15", category: "cloud", difficulty: "medium", question: "Apakah perbedaan antara 'Monitoring', 'Logging', dan 'Tracing' (Tiga Pilar Observability)?", answers: ["Monitoring mengukur metrik agregat kesehatan sistem (CPU, RAM, Error Rate); Logging mencatat aktivitas peristiwa individual berstempel waktu; Tracing melacak seluruh perjalanan satu request secara utuh dari awal hingga akhir melintasi berbagai mikroservis", "Monitoring untuk server fisik, Logging untuk database, Tracing untuk antarmuka web", "Monitoring dilakukan manusia, Logging dilakukan AI, Tracing dilakukan robot hardware", "Ketiganya adalah nama alat bantu pembayar tagihan cloud bulanan dari AWS"], correct: 0, hint: "Monitoring = 'Apakah sistem sedang sakit?'; Logging = 'Apa yang dicatat dokter di rekam medis?'; Tracing = 'Ke ruangan mana saja pasien ini berjalan di dalam rumah sakit?'", explanation: "Observability modern membutuhkan ketiganya. Jika pemantauan (Monitoring/Prometheus) membunyikan alarm karena latensi meleset ke 5 detik, Anda memeriksa Tracing (Jaeger/OpenTelemetry) untuk melihat di mikroservis mana tepatnya waktu terbuang, lalu melihat Logging (ELK/Grafana Loki) pada servis tersebut untuk membaca pesan error detailnya." },
            { id: "cloud-16", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Canary Deployment'?", answers: ["Teknik merilis versi aplikasi baru secara bertahap kepada sebagian kecil pengguna aktual terlebih dahulu (misal 5% traffic), guna memantau stabilitas dan error sebelum dirilis penuh kepada 100% pengguna", "Menguji aplikasi web menggunakan peramban rahasia berlogo burung kenari kuning sebelum rilis", "Memasang sensor suara di ruang server untuk mendeteksi suara bising kipas pendingin yang rusak", "Metode menyewa server di daerah terpencil berbiaya murah untuk menghemat anggaran infrastruktur"], correct: 0, hint: "Terinspirasi oleh penambang batubara zaman dulu yang membawa burung kenari ke dalam tambang untuk mendeteksi gas beracun sebelum manusia masuk.", explanation: "Dengan Canary Deployment, jika rilis baru mengandung bug memori yang membocorkan data atau menyebabkan crash, hanya 5% pengguna yang terdampak. Sistem pemantauan akan mendeteksi peningkatan rasio error pada kelompok canary dan secara otomatis membatalkan (rollback) rilis tersebut sebelum sisa 95% pengguna terganggu." },
            { id: "cloud-17", category: "cloud", difficulty: "medium", question: "Apakah fungsi dari 'Reverse Proxy' (seperti NGINX, HAProxy, atau Traefik)?", answers: ["Server perantara yang berdiri di depan server backend untuk menerima seluruh permintaan dari klien eksternal, mengelola terminasi SSL, caching, kompresi, load balancing, dan menyembunyikan identitas asli server internal", "Proxy web internal yang dipasang di peramban komputer karyawan untuk memblokir akses ke situs media sosial", "Sistem pembalik arah koneksi internet saat terjadi gangguan jaringan kabel bawah laut", "Alat untuk menerjemahkan alamat IP publik menjadi alamat IP privat secara otomatis di router rumah"], correct: 0, hint: "Sama seperti resepsionis hotel bintang lima: semua tamu dari luar berbicara dengan resepsionis terlebih dahulu, dan resepsionis yang menyalurkan ke kamar yang tepat tanpa tamu tahu struktur rahasia hotel.", explanation: "Forward Proxy melindungi klien (mengambilkan web untuk pengguna di dalam jaringan), sedangkan Reverse Proxy melindungi server. NGINX sebagai reverse proxy menangani negosiasi enkripsi HTTPS (SSL Termination) yang berat, sehingga server aplikasi di belakangnya bisa fokus memproses logika bisnis dengan cepat menggunakan HTTP biasa." },
            { id: "cloud-18", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'GitOps' dan apa peran alat seperti ArgoCD atau Flux?", answers: ["Metode operasional cloud-native yang menjadikan repositori Git sebagai satu-satunya sumber kebenaran (Single Source of Truth) untuk status infrastruktur dan aplikasi; agen otomatis (seperti ArgoCD) terus menyinkronkan status cluster Kubernetes agar selalu identik dengan kode di Git", "Menulis seluruh pesan commit di Git menggunakan bantuan model Artificial Intelligence secara otomatis", "Protokol mengunggah file gambar langsung dari antarmuka terminal Git ke database server", "Sistem keamanan yang menolak proses git clone dari komputer developer yang tidak memiliki sertifikat fisik"], correct: 0, hint: "Jika ada orang yang diam-diam mengubah konfigurasi server langsung di terminal, ArgoCD akan langsung menghapus perubahan itu dan mengembalikannya sesuai apa yang tertulis di Git.", explanation: "GitOps menggabungkan filosofi IaC dengan alur kerja Git (Pull Request, Code Review, Audit Log). Jika Anda ingin menambah jumlah pod dari 3 menjadi 10, Anda tidak mengetik perintah `kubectl scale` di terminal. Anda cukup mengubah angka `replicas: 10` di file YAML pada repositori Git, dan ArgoCD akan otomatis mendeteksi serta menerapkan perubahan itu ke cluster." },
            { id: "cloud-19", category: "cloud", difficulty: "easy", question: "Apakah yang dimaksud dengan 'High Availability' (HA) dan konsep angka 'Nine' (seperti 99.99% atau 4 Nines)?", answers: ["Kemampuan sistem untuk tetap aktif, beroperasi, dan dapat diakses tanpa putus dalam jangka waktu sangat lama; 99.99% uptime berarti batas maksimal waktu mati (downtime) hanya sekitar 52,6 menit dalam satu tahun penuh", "Kecepatan transfer data cloud minimal 99,99 Megabyte per detik pada koneksi serat optik", "Jaminan bahwa 99,99% kode program di dalam repositori bebas dari kesalahan sintaks atau bug", "Persentase kepuasan pengguna aplikasi yang diukur melalui survei bintang lima setiap bulan"], correct: 0, hint: "Semakin banyak angka 9 di belakang koma, semakin mahal dan tangguh rancangan arsitektur server Anda.", explanation: "Mencapai 99.999% (Five Nines - downtime maksimal 5,26 menit per tahun) menuntut penghapusan semua Single Point of Failure. Ini memerlukan multi-AZ (Availability Zone) deployment, replikasi database real-time cross-region, auto-failover, dan pengujian keandalan yang ketat." },
            { id: "cloud-20", category: "cloud", difficulty: "medium", question: "Apakah perbedaan antara 'Object Storage' (seperti AWS S3 atau Google Cloud Storage) dan 'Block Storage' (seperti AWS EBS)?", answers: ["Object Storage menyimpan file sebagai objek independen beserta metadata dan ID unik dalam namespace datar (cocok untuk foto, video, backup); Block Storage membagi volume menjadi blok-blok raw berkinerja rendah/tinggi yang dipasang langsung ke satu server seperti harddisk fisik (cocok untuk database)", "Object Storage untuk sistem operasi Linux, Block Storage untuk sistem operasi Windows", "Object Storage gratis tanpa batas, sedangkan Block Storage berbayar dan dibatasi 1 GB", "Object Storage disimpan di dalam RAM server, sedangkan Block Storage disimpan di pita magnetik"], correct: 0, hint: "S3 = Gudang raksasa tak terbatas tempat menumpuk jutaan foto dan dokumen dengan URL unik; EBS = Harddisk SSD eksternal super cepat yang dicolokkan langsung ke satu komputer virtual.", explanation: "Anda tidak bisa menginstal sistem operasi atau menjalankan database relasional MySQL berkinerja tinggi di atas AWS S3 karena sifat latensi dan strukturnya. Untuk itu dibutuhkan Block Storage (EBS). Sebaliknya, menyimpan 100 terabyte file video log atau aset web di EBS akan sangat mahal dan sulit discaled dibandingkan menggunakan S3." },
            { id: "cloud-21", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Chaos Engineering' (terinspirasi oleh Netflix Chaos Monkey)?", answers: ["Disiplin bereksperimen pada sistem terdistribusi di lingkungan produksi (production) dengan cara sengaja menyuntikkan kegagalan (seperti mematikan server secara acak, memotong jaringan, atau menaikkan CPU 100%) guna menguji dan membangun ketahanan sistem sebelum terjadi bencana nyata", "Teknik menulis kode program yang rumit dan acak agar sulit dibaca serta dicuri oleh peretas kompetitor", "Serangan siber ilegal oleh kelompok peretas yang bertujuan melumpuhkan seluruh pusat data cloud global", "Metode menghapus seluruh data log dan cache server setiap malam pukul 00.00 untuk membersihkan memori"], correct: 0, hint: "Sengaja membakar satu kamar di dalam hotel sendiri yang lengkap dengan pemadam kebakaran otomatis, untuk memastikan alarm dan air pemadam benar-benar bekerja saat kebakaran sesungguhnya terjadi.", explanation: "Netflix menciptakan Chaos Monkey pada tahun 2011 untuk mematikan instans AWS EC2 mereka di jam sibuk secara acak. Filosofinya adalah: kegagalan di cloud pasti akan terjadi. Dengan sengaja memicu kegagalan di bawah pemantauan ketat, engineer dapat menemukan kelemahan arsitektur, menguji mekanisme auto-healing, dan memastikan sistem benar-benar tangguh." },
            { id: "cloud-22", category: "cloud", difficulty: "medium", question: "Apakah fungsi utama dari 'Auto Scaling Group' (ASG) di cloud computing?", answers: ["Layanan yang secara otomatis memantau beban sistem dan menyesuaikan (menambah atau mengurangi) jumlah instans server komputasi yang aktif sesuai parameter aturan yang ditentukan (misal saat CPU > 75%)", "Alat yang otomatis memperbesar resolusi gambar dan ukuran font pada layar dasbor administrator cloud", "Sistem penagihan otomatis yang memotong kartu kredit perusahaan saat biaya cloud melebihi batas bulanan", "Software yang mempercepat perputaran kipas pendingin server fisik saat suhu ruangan di atas 30 derajat Celsius"], correct: 0, hint: "Menambah jumlah kasir saat antrean pembeli panjang, dan menyuruh kasir pulang saat toko sepi agar hemat biaya gaji.", explanation: "Auto Scaling dipasangkan dengan Load Balancer. Saat terjadi lonjakan promo flash sale (CPU menyentuh 80%), ASG otomatis meluncurkan 5 instans baru dalam 2 menit. Setelah flash sale berakhir dan traffic kembali normal, ASG mematikan instans berlebih tersebut (Scale In) sehingga perusahaan tidak membayar server yang menganggur." },
            { id: "cloud-23", category: "cloud", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Virtual Private Cloud' (VPC)?", answers: ["Jaringan virtual terisolasi secara logis yang dialokasikan khusus untuk satu akun pengguna di dalam infrastruktur cloud publik, di mana pengguna memiliki kendali penuh atas rentang IP, subnet, routing table, dan firewall", "Komputer server fisik pribadi yang dibeli pengguna lalu dititipkan di dalam kantor penyedia cloud", "Aplikasi VPN untuk menyembunyikan lokasi alamat IP pengguna saat berselancar di internet umum", "Ruang penyimpanan file awan yang diproteksi kata sandi rahasia untuk menyimpan dokumen pribadi keluarga"], correct: 0, hint: "Membuat 'pagar kompleks perumahan pribadi Anda sendiri' di tengah kota metropolis cloud yang luas.", explanation: "Tanpa VPC, semua instans dari seluruh pelanggan cloud akan berada di satu jaringan terbuka yang rentan. VPC memungkinkan Anda membagi jaringan menjadi Subnet Publik (untuk web server yang bisa diakses internet) dan Subnet Privat (untuk database yang sama sekali tidak bisa diakses langsung dari luar internet)." },
            { id: "cloud-24", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Service Level Agreement' (SLA), 'Service Level Objective' (SLO), dan 'Service Level Indicator' (SLI) dalam Site Reliability Engineering (SRE)?", answers: ["SLI adalah metrik teknis aktual yang diukur (misal % latensi < 200ms); SLO adalah target internal yang ingin dicapai dari SLI tersebut (misal 99.9%); SLA adalah kontrak hukum/bisnis dengan pelanggan yang memuat konsekuensi/penalti finansial jika SLO tidak terpenuhi", "SLI untuk programmer, SLO untuk desainer, SLA untuk manajer pemasaran perusahaan", "SLI, SLO, dan SLA adalah tiga jenis sertifikasi keamanan cloud yang dikeluarkan oleh ISO Internasional", "Ketiganya adalah rumus matematika untuk mengira biaya listrik server di pusat data cloud"], correct: 0, hint: "SLI = Angka di speedometer mobil; SLO = Target kita tidak boleh menyetir lebih dari 80 km/jam; SLA = Surat perjanjian bahwa kita akan membayar denda Rp1 juta ke penumpang jika menyetir lebih dari 100 km/jam.", explanation: "Google SRE memperkenalkan konsep ini untuk menyelaraskan tim engineering dengan bisnis. SLO memberi tim batas toleransi kesalahan (Error Budget). Selama Error Budget masih ada, developer boleh bereksperimen dan merilis fitur baru dengan cepat. Jika Error Budget habis, semua rilis fitur baru dibekukan sampai keandalan sistem kembali normal." },
            { id: "cloud-25", category: "cloud", difficulty: "medium", question: "Apakah kegunaan dari 'Bastion Host' (Jump Server) dalam arsitektur keamanan jaringan cloud?", answers: ["Server khusus berkeamanan ekstra ketat yang menjadi satu-satunya gerbang masuk eksternal bagi administrator untuk melakukan koneksi remote (SSH/RDP) menuju server-server privat di dalam jaringan tertutup", "Server cadangan yang otomatis menyala untuk menggantikan database utama yang mengalami kerusakan fisik", "Sistem proxy web yang memblokir serangan DDoS dengan cara menyerap seluruh lalu lintas sampah di perbatasan", "Komputer khusus yang dipasang untuk menambal (patching) sistem operasi server lain setiap akhir pekan"], correct: 0, hint: "Satu gerbang kecil berpenjaga bersenjata lengkap yang harus dilewati sebelum bisa masuk ke dalam kawasan rahasia di balik benteng.", explanation: "Menaruh port SSH (port 22) atau RDP (port 3389) dari semua server database/backend terbuka ke internet umum adalah undangan terbuka bagi peretas. Dengan Bastion Host, hanya satu server ini yang terbuka ke internet (dilengkapi MFA dan pemantauan log ketat), dan dari server inilah admin bisa melompat (jump) ke server privat internal." },
            { id: "cloud-26", category: "cloud", difficulty: "easy", question: "Apakah yang dimaksud dengan 'DevSecOps'?", answers: ["Integrasi praktik, alat bantu, dan budaya keamanan (Security) ke dalam setiap tahapan siklus hidup DevOps secara otomatis sejak fase awal penulisan kode (Shift-Left Security), bukan hanya di akhir sebelum rilis", "Divisi keamanan khusus yang bekerja terpisah di gedung berbeda untuk mengaudit kode program setahun sekali", "Penggunaan sistem operasi Linux khusus yang tidak memiliki antarmuka grafis demi keamanan server", "Proses menghapus akun pengguna yang tidak aktif selama 30 hari secara otomatis dari database cloud"], correct: 0, hint: "Memasukkan kata 'Sec' (Security) ke tengah 'DevOps': keamanan adalah tanggung jawab bersama semua orang sejak hari pertama.", explanation: "Pada model tradisional, tim keamanan baru memeriksa aplikasi tepat satu hari sebelum rilis (sering menunda rilis berminggu-minggu jika ada celah). DevSecOps menggeser ke kiri (Shift-Left) dengan menyisipkan pemindai Static Application Security Testing (SAST), pemindai dependensi (SCA), dan pemindai kontainer langsung di dalam CI/CD pipeline." },
            { id: "cloud-27", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Sidecar Pattern' dalam arsitektur kontainer?", answers: ["Pola desain di mana sebuah kontainer pendukung (sidecar) dijalankan berdampingan dengan kontainer aplikasi utama di dalam pod yang sama untuk menangani tugas sekunder (seperti logging, monitoring, proxy, atau enkripsi) tanpa mengubah kode aplikasi utama", "Menyambungkan laptop pengembang secara fisik ke rak server pusat data menggunakan kabel konsol samping", "Menyalin seluruh database produksi ke komputer cadangan sampingan setiap satu jam sekali", "Teknik memuat dua sistem operasi berbeda pada satu komputer virtual yang berjalan secara bergantian"], correct: 0, hint: "Sespan pada sepeda motor: motor utama fokus berkendara ke tujuan, sementara sespan di sampingnya membawa beban atau penumpang tambahan.", explanation: "Sidecar pattern sangat populer di Kubernetes. Sebagai contoh, aplikasi utama Anda cukup menulis log ke `stdout` (layar console standard). Kontainer Sidecar (misal Fluentd atau Filebeat) yang berjalan di sampingnya bertugas memungut log tersebut dari console, mengompresinya, dan mengirimkannya ke server Elasticsearch secara mandiri." },
            { id: "cloud-28", category: "cloud", difficulty: "medium", question: "Apakah perbedaan antara 'Stateless Application' dan 'Stateful Application' di lingkungan cloud?", answers: ["Stateless tidak menyimpan data sesi atau status transaksi di memori lokal instans server (sesi disimpan eksternal di Redis/Database); Stateful menyimpan data status langsung di memori/storage lokal server yang sama dari waktu ke waktu", "Stateless untuk aplikasi web modern, Stateful untuk aplikasi web tahun 1990-an", "Stateless selalu berjalan di cloud, sedangkan Stateful hanya bisa berjalan di komputer desktop rumah", "Stateless tidak memiliki antarmuka grafis, sedangkan Stateful dilengkapi antarmuka grafis 3D animasi"], correct: 0, hint: "Aplikasi yang mudah ditambah jumlah servernya dalam detik (Stateless) vs aplikasi yang rewel jika server dimatikan karena ingatannya hilang (Stateful).", explanation: "Agar Horizontal Auto Scaling berjalan lancar, aplikasi web harus bersifat Stateless. Jika server A dimatikan oleh Auto Scaler, pengguna yang selanjutnya dilayani oleh server B tidak boleh terputus atau terlogout. Karenanya, informasi sesi login dan keranjang belanja harus disimpan di cache terpusat seperti Redis atau database eksternal." },
            { id: "cloud-29", category: "cloud", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Edge Computing'?", answers: ["Paradigma komputasi yang memproses data fisik sedekat mungkin dengan lokasi sumber data (di pinggiran/edge jaringan seperti perangkat IoT, gateway lokal, atau menara BTS 5G) guna meminimalkan latensi dan menghemat bandwidth internet", "Komputasi cloud yang hanya menggunakan prosesor berteknologi canggih terbaru di pusat data utama", "Desain antarmuka website yang melengkung dan tajam di setiap sudut tepi layar monitor", "Sistem operasi ringan yang dirancang khusus untuk berjalan di dalam peramban Microsoft Edge"], correct: 0, hint: "Memotong jarak tempuh data: mengapa harus mengirim data kamera cctv pabrik ke server di Amerika jika bisa diproses di komputer kecil di dalam pabrik itu sendiri?", explanation: "Pada aplikasi kritis seperti mobil otonom (Self-Driving Car), operasi pembedahan robotik, atau deteksi kebakaran hutan seketika, menunggu respons dari server cloud sejauh ribuan kilometer (latensi 100ms+) bisa berakibat fatal. Edge Computing memroses logika langsung di perangkat lokal dalam latensi di bawah 5ms." },
            { id: "cloud-30", category: "cloud", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Terraform State File' (.tfstate) dan mengapa pengelolaan aman file ini sangat kritis?", answers: ["File JSON yang menyimpan pemetaan antara konfigurasi kode Terraform dengan sumber daya nyata di cloud; file ini kritis karena melacak identitas server aktual dan sering kali mengandung data sensitif (seperti password database atau API key dalam teks terang/plain text)", "File log cadangan yang mencatat riwayat error saat proses instalasi sistem operasi Linux di server cloud", "File biner terenkripsi yang berisi seluruh backup database produksi perusahaan dari minggu lalu", "Skrip otomatisasi yang dijalankan setiap malam untuk menghapus kontainer Docker yang tidak terpakai"], correct: 0, hint: "Buku catatan rahasia milik Terraform yang menyimpan daftar apa saja yang sudah dia bangun di cloud, lengkap dengan rahasia sensitifnya.", explanation: "Jika dua developer menjalankan Terraform dengan file state lokal yang berbeda atau tidak tersinkronisasi, Terraform bisa menghapus server production secara tidak sengaja karena mengira server tersebut tidak sah. Oleh karena itu, State File wajib disimpan di Remote Backend terpusat (seperti AWS S3 dengan DynamoDB State Locking) serta dienkripsi ketat." },

            // Mobile App Development (1-30)
            { id: "mobile-1", category: "mobile", difficulty: "easy", question: "Apakah perbedaan utama antara pengembangan aplikasi mobile 'Native', 'Cross-Platform' (seperti Flutter/React Native), dan 'Progressive Web App' (PWA)?", answers: ["Native ditulis spesifik untuk satu OS (Swift untuk iOS, Kotlin untuk Android); Cross-Platform menggunakan satu codebase untuk menghasilkan aplikasi di kedua OS; PWA adalah aplikasi web yang berjalan di browser namun memiliki kapabilitas mirip aplikasi native (offline, push info)", "Native hanya bisa diunduh via CD-ROM, Cross-Platform via Bluetooth, PWA via kabel USB-C", "Native berukuran 1 KB, Cross-Platform berukuran 1 MB, PWA berukuran 100 MB di harddisk ponsel", "Ketiganya adalah nama merek smartphone Android terbaru yang dipasarkan di Asia Tenggara"], correct: 0, hint: "Satu bahasa khusus per sistem operasi vs Satu kode untuk semua vs Web yang menyamar jadi aplikasi ponsel.", explanation: "Aplikasi Native memberikan performa dan akses hardware terbaik (contoh: game 3D berat). Cross-platform (Flutter/React Native) menghemat biaya dan waktu karena tim cukup menulis satu kode dasar yang berjalan di iOS dan Android. PWA tidak memerlukan instalasi lewat App Store/Play Store dan sangat hemat kuota memori." },
            { id: "mobile-2", category: "mobile", difficulty: "easy", question: "Apakah bahasa pemrograman resmi utama yang direkomendasikan untuk pengembangan aplikasi Native modern di Android dan iOS?", answers: ["Kotlin untuk Android (menggantikan Java) dan Swift untuk iOS (menggantikan Objective-C)", "Python untuk Android dan PHP untuk iOS", "JavaScript untuk Android dan C++ untuk iOS", "Ruby untuk Android dan Pascal untuk iOS"], correct: 0, hint: "Google resmi memilih Kotlin sebagai 'first-class citizen' pada 2017, dan Apple memperkenalkan Swift pada 2014.", explanation: "Kotlin dirancang modern, ringkas, dan sepenuhnya interoperabel dengan kode Java lawas serta mengatasi masalah NullPointerException (Null Safety). Swift dirancang oleh Apple untuk berkinerja tinggi (setara C/C++), aman, dan memiliki sintaks yang jauh lebih bersih dan ramah developer dibandingkan Objective-C." },
            { id: "mobile-3", category: "mobile", difficulty: "medium", question: "Apakah perbedaan antara cara kerja rendering antarmuka pada 'React Native' dan 'Flutter'?", answers: ["React Native menggunakan 'JS Bridge' untuk memetakan komponen React ke widget Native asli milik OS (Android/iOS); sedangkan Flutter menggunakan engine grafis sendiri (Skia/Impeller) untuk menggambar langsung setiap piksel widget ke layar kanvas tanpa bridge", "React Native menggambar dengan engine 3D Unreal Engine, sedangkan Flutter menggunakan engine web HTML5 murni", "React Native hanya bisa untuk Android, sedangkan Flutter hanya bisa untuk iOS", "React Native membutuhkan koneksi internet statis 5G untuk merender tombol, sedangkan Flutter tidak"], correct: 0, hint: "Membuat tombol dengan memesan tombol asli dari OS (React Native) vs melukis tombol sendiri langsung di atas kanvas layar menggunakan kuas grafis (Flutter).", explanation: "Karena menggunakan JS Bridge untuk berkomunikasi dengan UI Native, React Native bisa mengalami bottleneck latensi pada animasi kompleks yang intens. Flutter menghindari bridge ini dengan merender seluruh antarmuka secara mandiri pada 60/120 FPS di kedua platform, menghasilkan konsistensi tampilan 100% identik di semua ponsel." },
            { id: "mobile-4", category: "mobile", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Activity Lifecycle' pada Android (seperti onCreate, onStart, onResume, onPause, onStop, onDestroy)?", answers: ["Serangkaian metode status pemanggilan yang dilewati oleh komponen Activity/layar antarmuka sejak pertama kali dibuat, ditampilkan, dipindahkan ke background oleh pengguna, hingga dihancurkan dari memori oleh sistem", "Waktu usia pakai baterai smartphone dari kondisi penuh 100% sampai habis 0%", "Jadwal pembaruan aplikasi otomatis yang dijalankan oleh Google Play Store setiap 7 hari sekali", "Siklus pengiriman paket data jaringan seluler 4G/5G dari menara operator ke antena internal ponsel"], correct: 0, hint: "Apa yang terjadi pada aplikasi game Anda saat tiba-tiba ada telepon masuk dan layar game tertutup sementara?", explanation: "Memahami lifecycle sangat vital untuk mencegah kebocoran memori dan kehilangan data pengguna. Saat pengguna menerima telepon atau menekan tombol Home, `onPause()` dan `onStop()` dipanggil. Developer harus menyimpan progres game atau form input di dalam metode ini sebelum sistem menutup aplikasi." },
            { id: "mobile-5", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'ANR' (Application Not Responding) pada Android dan bagaimana cara mencegahnya?", answers: ["Kondisi ketika aplikasi membeku/hang karena developer menjalankan tugas berat yang memakan waktu lama (seperti network request, query database, atau pemrosesan gambar) langsung di atas 'Main UI Thread'; dicegah dengan memindahkan tugas berat ke Background Thread/Coroutines", "Peringatan bahwa memori penyimpanan internal smartphone pengguna sudah penuh 100%", "Error yang terjadi saat pengguna mengunduh aplikasi berformat APK dari luar Google Play Store", "Kondisi di mana layar sentuh smartphone tidak merespons karena jari pengguna basah terkena air"], correct: 0, hint: "Dialog menyebalkan yang berbunyi 'Aplikasi ini tidak merespons: Tutup atau Tunggu?' karena UI Thread diblokir lebih dari 5 detik.", explanation: "Di Android, Main Thread (UI Thread) bertanggung jawab menggambar antarmuka pada 60 FPS (setiap 16 milidetik) dan merespons sentuhan jari. Jika Anda melakukan HTTP request ke server yang memakan waktu 3 detik di atas Main Thread, layar ponsel akan beku total (freeze) dan sistem memicu dialog ANR." },
            { id: "mobile-6", category: "mobile", difficulty: "easy", question: "Apakah fungsi dari file 'AndroidManifest.xml' pada aplikasi Android atau 'Info.plist' pada iOS?", answers: ["File konfigurasi metadata utama yang mendeklarasikan identitas aplikasi, komponen-komponen utama, daftar izin akses (permissions) yang dibutuhkan (seperti kamera, lokasi, internet), serta spesifikasi perangkat pendukung", "File gambar ikon utama yang ditampilkan pada layar beranda (home screen) smartphone pengguna", "File database SQLite rahasia tempat menyimpan kata sandi dan token login pengguna secara lokal", "File skrip Python yang mengontrol animasi transisi perpindahan halaman pada aplikasi mobile"], correct: 0, hint: "Kartu identitas resmi dan daftar 'surat izin' yang diserahkan aplikasi kepada sistem operasi sebelum boleh diinstal.", explanation: "Tanpa mendeklarasikan `<uses-permission android:name=\"android.permission.CAMERA\"/>` di `AndroidManifest.xml` (atau `NSCameraUsageDescription` di `Info.plist`), sistem operasi akan langsung menolak dan menutup (crash) aplikasi saat mencoba mengakses kamera fisik perangkat." },
            { id: "mobile-7", category: "mobile", difficulty: "medium", question: "Apakah yang dimaksud dengan State Management 'Redux', 'Bloc', atau 'Provider' dalam pengembangan aplikasi mobile?", answers: ["Pola dan pustaka arsitektur untuk mengelola, membagi, dan menyinkronkan data status (state) aplikasi secara terpusat dan terprediksi di seluruh komponen antarmuka yang kompleks tanpa harus mengoper prop secara berantai (prop drilling)", "Alat bantu untuk mengompresi ukuran gambar aset aplikasi sebelum diunggah ke App Store", "Metode pengamanan komunikasi jaringan antarmuka menggunakan enkripsi end-to-end ganda", "Sistem penerjemah bahasa otomatis untuk menampilkan teks aplikasi dalam 50 bahasa berbeda"], correct: 0, hint: "Bagaimana cara tombol keranjang belanja di header atas tahu bahwa Anda baru saja menambahkan barang di halaman katalog paling bawah tanpa kabel penghubung rumit?", explanation: "Pada aplikasi dengan ratusan layar, memegang status (seperti status login pengguna, tema gelap/terang, daftar barang di keranjang) di satu komponen dan mengopernya ke puluhan komponen anak (Prop Drilling) sangat berantakan. State Management menyediakan satu 'sumber kebenaran' global yang secara reaktif memperbarui komponen UI yang membutuhkan." },
            { id: "mobile-8", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Deep Linking' (atau Universal Links pada iOS / App Links pada Android)?", answers: ["Mekanisme yang memungkinkan tautan URL web biasa (seperti https://toko.com/item/123) untuk langsung membuka halaman spesifik di dalam aplikasi mobile yang terinstal, tanpa melewati browser web atau halaman utama aplikasi", "Teknik menghubungkan dua ponsel secara fisik menggunakan kabel OTG untuk transfer file cepat", "Menyembunyikan kode rahasia di lapisan paling dalam struktur direktori aplikasi mobile", "Proses pemindai sidik jari mendalam untuk membuka kunci aplikasi perbankan di ponsel"], correct: 0, hint: "Mengklik link produk promo dari WhatsApp yang langsung membuka detail produk itu di aplikasi Shopee/Tokopedia Anda, bukan di Chrome.", explanation: "Universal Links/App Links diverifikasi menggunakan file asinkron yang diunggah ke server domain resmi (`apple-app-site-association` atau `assetlinks.json`). Hal ini mencegah aplikasi palsu membajak tautan domain milik perusahaan resmi dan memberikan pengalaman pengguna yang sangat mulus dari web ke aplikasi." },
            { id: "mobile-9", category: "mobile", difficulty: "medium", question: "Apakah perbedaan antara penyimpanan lokal 'SharedPreferences' (atau NSUserDefaults) dan 'SQLite / Room / CoreData' di mobile?", answers: ["SharedPreferences/NSUserDefaults berbasis key-value sederhana yang cocok untuk pengaturan ringan (misal: tema gelap=true, status login=false); sedangkan SQLite/Room/CoreData adalah database relasional lokal berstruktur tabel yang cocok untuk menyimpan ribuan data kompleks (misal: riwayat chat offline)", "SharedPreferences untuk iPhone, sedangkan SQLite untuk smartphone Android saja", "SharedPreferences disimpan di server cloud, sedangkan SQLite disimpan di kartu memori microSD", "SharedPreferences berformat gambar PNG, sedangkan SQLite berformat video MP4 di ponsel"], correct: 0, hint: "Menyimpan catatan kecil satu baris di kertas post-it (SharedPreferences) vs menyimpan seluruh buku katalog perpustakaan di dalam lemari arsip berindeks (SQLite/Room).", explanation: "Menyimpan 10.000 baris data riwayat transaksi di dalam `SharedPreferences` akan membuat aplikasi sangat lambat dan memori terbebani karena seluruh file dibaca ke RAM sekaligus. Untuk data terstruktur berskala besar dengan kebutuhan pencarian (query) dan relasi antar tabel, ORM seperti Room (Android) atau CoreData (iOS) adalah solusi wajib." },
            { id: "mobile-10", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Jetpack Compose' (Android) dan 'SwiftUI' (iOS)?", answers: ["Framework modern penulisan antarmuka berbasis 'Declarative UI', di mana developer cukup mendeskripsikan bagaimana tampilan antarmuka seharusnya terlihat berdasarkan status data saat ini, menggantikan cara lama berbasis XML/Storyboard yang imperatif", "Dua nama software simulator desain grafis vektor 3D yang dijalankan di komputer Mac dan Windows", "Protokol pengiriman notifikasi kilat dari server cloud ke perangkat smartphone dalam waktu 1 milidetik", "Mesin kompilasi baru yang memperkecil ukuran file aplikasi mobile hingga 90% secara otomatis"], correct: 0, hint: "Alih-alih menyuruh program langkah demi langkah: 'buat teks, warnai merah, geser ke kanan 10px' (Imperative), kita cukup bilang: 'Tampilkan Teks(warna=merah, posisi=kanan)' (Declarative).", explanation: "Sebelum Compose/SwiftUI, developer Android harus menulis layout di file XML dan menghubungkannya ke kode Java/Kotlin lewat `findViewById`. Di iOS, developer bertarung dengan Interface Builder/Storyboard yang sering bentrok di Git. Compose dan SwiftUI menggunakan kode 100% Kotlin/Swift yang ringkas, reaktif, dan sangat cepat dikembangkan." },
            { id: "mobile-11", category: "mobile", difficulty: "easy", question: "Apakah fungsi utama dari 'Push Notification' (seperti Firebase Cloud Messaging - FCM atau Apple Push Notification service - APNs)?", answers: ["Layanan yang memungkinkan server cloud untuk mengirimkan pesan atau peringatan secara real-time langsung ke perangkat mobile pengguna meskipun aplikasi sedang ditutup atau berjalan di latar belakang", "Mengirimkan pesan SMS biasa melalui jaringan pulsa operator seluler saat internet mati total", "Fitur menekan layar ponsel dengan keras untuk membuka menu klik kanan rahasia di ikon aplikasi", "Proses mengunggah data backup foto dari ponsel ke server cloud setiap kali terhubung ke Wi-Fi"], correct: 0, hint: "Notifikasi berbunyi 'Pesanan GoFood Anda sudah sampai di depan rumah!' yang muncul di layar kunci ponsel Anda.", explanation: "FCM dan APNs menjaga satu koneksi soket TCP berdaya super rendah yang konstan antara OS ponsel dengan server Google/Apple. Ketika server backend toko online ingin memberi tahu pengguna, pesan dikirim ke FCM/APNs, yang kemudian menyalurkannya ke ponsel pengguna tanpa menguras baterai ponsel." },
            { id: "mobile-12", category: "mobile", difficulty: "medium", question: "Apakah yang dimaksud dengan 'ProGuard' atau 'R8' pada kompilasi aplikasi Android?", answers: ["Alat penyingkat (shrinker), pengoptimal, dan pengabur (obfuscator) kode yang membuang kelas/metode tak terakai serta mengubah nama kelas/variabel menjadi huruf pendek acak (seperti a.b.c) guna memperkecil ukuran APK dan mempersulit reverse engineering", "Program pemindai virus bawaan dari Google yang memblokir aplikasi berbahaya di smartphone", "Alat untuk mengubah tema warna aplikasi Android lama menjadi bertema Material Design otomatis", "Sistem pengaman baterai ponsel agar tidak meledak saat aplikasi menjalankan game berat"], correct: 0, hint: "Menghapus kode sampah yang tidak dipakai, sekaligus menyandikan nama variabel agar peretas yang membongkar APK Anda pusing melihat kode yang keriting.", explanation: "Tanpa pengaburan (obfuscation), peretas bisa mendekompilasi file APK/AAB kembali ke kode Java/Kotlin yang sangat mudah dibaca menggunakan alat seperti `jadx`, lalu mencuri logika bisnis atau rahasia API Anda. R8/ProGuard juga memangkas ukuran aplikasi dari 50 MB menjadi 15 MB dengan menghapus pustaka yang tidak terpakai (Tree Shaking)." },
            { id: "mobile-13", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Memory Leak' (Kebocoran Memori) pada aplikasi mobile dan apa akibat fatalnya?", answers: ["Kondisi ketika objek yang sudah tidak lagi digunakan oleh aplikasi tetap ditahan rujukan (reference)-nya di dalam memori sehingga tidak bisa dibersihkan oleh Garbage Collector; jika terus menumpuk, aplikasi akan kehabisan RAM dan mengalami crash (OutOfMemoryError)", "Air hujan atau keringat yang merembes masuk ke dalam perangkat keras ponsel melalui slot kartu SIM", "Terhapusnya foto dan video pribadi pengguna secara tiba-tiba karena kesalahan pembaruan sistem operasi", "Kondisi di mana baterai ponsel cepat habis karena layar brightness diatur pada tingkat maksimal"], correct: 0, hint: "Layar halaman A ditutup, tapi karena ada proses background yang masih memegang rujukan halaman A, halaman A tetap nyangkut di RAM selamanya sampai memori meledak.", explanation: "Di Android, penyebab Memory Leak paling umum adalah `static reference` ke `Context` atau `Activity`, serta `Listener/Observer` atau `Coroutine/RxJava subscription` yang lupa dibatalkan saat metode `onDestroy()` dipanggil. Developer menggunakan alat seperti `LeakCanary` atau Android Studio Profiler untuk memburu dan menambal kebocoran ini." },
            { id: "mobile-14", category: "mobile", difficulty: "easy", question: "Apakah perbedaan antara format distribusi 'APK' (Android Package Kit) dan 'AAB' (Android App Bundle)?", answers: ["APK adalah file instalasi lengkap yang memuat semua resolusi dan arsitektur dalam satu file besar; AAB adalah format penerbitan modern di mana Google Play Store merakit dan mengirimkan hanya komponen/aset yang pas sesuai spesifikasi ponsel pengunduh (Dynamic Delivery)", "APK adalah aplikasi berbayar di toko resmi, sedangkan AAB adalah aplikasi gratis di toko alternatif", "APK hanya untuk ponsel Samsung, sedangkan AAB hanya untuk ponsel Xiaomi dan Oppo", "APK berukuran maksimal 1 MB, sedangkan AAB berukuran minimal 100 GB di harddisk server"], correct: 0, hint: "AAB memungkinkan Google Play membuang aset gambar layar tablet 4K dan bahasa Spanyol saat aplikasi diunduh oleh ponsel kecil berbahasa Indonesia, menghemat ukuran download hingga 50%.", explanation: "Sejak Agustus 2021, Google Play mewajibkan seluruh aplikasi baru diunggah dalam format AAB. Melalui mekanisme Google Play Dynamic Delivery, pengguna akhir hanya mengunduh APK minimalis yang disesuaikan persis dengan resolusi layar (mdpi/xhdpi), arsitektur prosesor (ARM64/x86), dan bahasa perangkat mereka." },
            { id: "mobile-15", category: "mobile", difficulty: "medium", question: "Apakah yang dimaksud dengan konsep 'Offline-First Architecture' pada aplikasi mobile?", answers: ["Pendekatan desain di mana aplikasi dirancang untuk berfungsi secara lancar menggunakan database lokal (misal Room/SQLite) tatkala koneksi internet putus atau tidak stabil; data sinkronisasi otomatis ke server cloud saat internet kembali terhubung", "Aplikasi mobile yang sama sekali tidak memiliki fitur koneksi internet dan tidak pernah terhubung ke cloud", "Metode mematikan antena Wi-Fi dan seluler ponsel secara otomatis untuk menghemat daya baterai", "Aplikasi yang meminta pengguna mematikan koneksi data seluler sebelum bisa membuka menu utama"], correct: 0, hint: "Aplikasi catatan atau to-do list yang tetap bisa dipakai mengetik lancar di dalam pesawat terbang tanpa internet, lalu otomatis tersinkron ke server saat mendarat.", explanation: "Dalam arsitektur ini, UI tidak pernah langsung membaca atau menulis data lewat HTTP request ke server. UI selalu membaca data dari Database Lokal (Single Source of Truth). Saat ada perubahan, data disimpan lokal, dan Service/Worker di latar belakang yang bertugas menyinkronkannya (dan menyelesaikan konflik) ke server cloud saat koneksi tersedia." },
            { id: "mobile-16", category: "mobile", difficulty: "hard", question: "Apakah perbedaan antara 'Background Service', 'Foreground Service', dan 'WorkManager' pada Android modern?", answers: ["Background Service berjalan diam-diam tanpa UI (kini dibatasi ketat oleh OS); Foreground Service berjalan untuk tugas aktif berdurasi panjang dengan menampilkan notifikasi persisten yang wajib dilihat pengguna (misal pemutar musik/GPS); WorkManager untuk tugas terstruktur yang ditunda dan dijamin selesai oleh sistem (misal sinkronisasi data malam hari)", "Ketiganya adalah nama aplikasi pembersih RAM otomatis yang tersedia di Google Play Store", "Background untuk layar gelap, Foreground untuk layar terang, WorkManager untuk jam kerja kantor", "Background Service untuk iOS, Foreground Service untuk Android, WorkManager untuk Windows Phone"], correct: 0, hint: "Mengapa pemutar Spotify di ponsel selalu memunculkan bar notifikasi permanen di atas yang tidak bisa digeser hapus saat lagu berputar? Itu adalah Foreground Service agar tidak dimatikan oleh OS.", explanation: "Sejak Android 8 (Oreo) dan sistem Doze Mode yang agresif menghemat baterai, sistem operasi akan membunuh aplikasi yang diam-diam menjalankan proses berat di background. WorkManager adalah standar modern Google karena sangat pintar: ia bisa diatur untuk hanya berjalan saat ponsel dicolokkan ke charger dan terhubung ke Wi-Fi." },
            { id: "mobile-17", category: "mobile", difficulty: "medium", question: "Apakah kegunaan dari 'Certificate Pinning' (SSL Pinning) pada keamanan aplikasi mobile?", answers: ["Teknik menanamkan sidik jari (hash) sertifikat SSL/TLS server backend resmi langsung di dalam kode aplikasi mobile, sehingga aplikasi menolak berkomunikasi jika sertifikat yang disajikan server tidak pas (meskipun sertifikat itu diterbitkan oleh CA yang sah di ponsel)", "Menyematkan sertifikat penghargaan digital berbingkai emas di halaman profil pengguna aplikasi", "Memasang pin angka rahasia 6 digit sebelum membuka menu pengaturan keamanan jaringan di ponsel", "Menyamakan waktu jam perangkat smartphone dengan waktu jam server sertifikat di cloud"], correct: 0, hint: "Membentengi aplikasi perbankan dari serangan Man-in-the-Middle (MitM) meskipun peretas berhasil memasang sertifikat palsu di ponsel pengguna.", explanation: "Secara default, aplikasi mobile mempercayai semua Certificate Authority (CA) yang ada di daftar root OS ponsel. Jika peretas (atau alat proxy penguji seperti Burp Suite) memasang sertifikat CA palsu di ponsel, mereka bisa menyadap seluruh lalu lintas HTTPS (MitM). SSL Pinning memastikan aplikasi hanya mau berbicara dengan server yang memiliki kunci publik spesifik milik perusahaan kita." },
            { id: "mobile-18", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Hot Reload' dan 'Hot Restart' pada framework Flutter / React Native?", answers: ["Hot Reload menyuntikkan file kode baru langsung ke dalam Dart/JS Virtual Machine yang sedang berjalan untuk memperbarui tampilan UI dalam hitungan milidetik tanpa kehilangan status data (state) saat ini; Hot Restart merestart ulang seluruh aplikasi dan mereset status data ke awal", "Hot Reload memanaskan prosesor ponsel untuk performa maksimal, Hot Restart mendinginkannya kembali", "Hot Reload mengunduh ulang seluruh file aplikasi dari Play Store, Hot Restart mematikan ponsel total", "Hot Reload adalah fitur berbayar untuk developer, sedangkan Hot Restart adalah fitur gratis untuk pemula"], correct: 0, hint: "Mengubah warna tombol dari biru menjadi merah di editor kode, dan dalam 0,5 detik tombol di layar simulator langsung berubah merah tanpa Anda harus mengulang login dari awal (Hot Reload).", explanation: "Hot Reload adalah revolusi produktivitas bagi mobile developer. Pada pengembangan Native tradisional (C++/Java), setiap perubahan kecil pada UI membutuhkan waktu kompilasi (Gradle build) 30 hingga 120 detik. Hot Reload memangkas siklus iterasi desain dari menit menjadi pecahan detik." },
            { id: "mobile-19", category: "mobile", difficulty: "easy", question: "Apakah fungsi dari tool 'adb' (Android Debug Bridge)?", answers: ["Alat baris perintah (command-line tool) serbaguna yang memungkinkan developer berkomunikasi, mengontrol, memasang aplikasi (install APK), dan mengambil log debugging (logcat) dari emulator atau perangkat fisik Android yang terhubung via USB/Wi-Fi", "Aplikasi pemutar musik dan video berkualitas tinggi bawaan dari sistem operasi Android", "Kabel fisik konverter dari colokan USB Type-C ponsel menuju port HDMI monitor komputer", "Sistem pengontrol kamera smartphone untuk mengambil foto dengan mode malam AI otomatis"], correct: 0, hint: "Perintah sakti di terminal seperti `adb devices`, `adb install app.apk`, atau `adb logcat`.", explanation: "ADB terdiri dari tiga komponen: Client (di terminal komputer Anda), Daemon (adbd yang berjalan di perangkat Android), dan Server (di background komputer yang mengatur komunikasi keduanya). ADB adalah senjata utama developer untuk memecahkan masalah (troubleshoot) dan menganalisis crash di level sistem operasi." },
            { id: "mobile-20", category: "mobile", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Biometric Authentication' (seperti Face ID / Fingerprint) menggunakan BiometricPrompt API di mobile?", answers: ["Kerangka kerja keamanan standar OS yang memverifikasi sidik jari atau wajah pengguna secara lokal di dalam perangkat keras aman (Secure Enclave / TEE), lalu membuka kunci kriptografis tanpa pernah mengirimkan data biometrik tersebut ke server cloud", "Merekam video wajah pengguna lalu mengirimkan file MP4 tersebut ke server cloud untuk dicocokkan oleh admin", "Meminta pengguna menggambar tanda tangan sidik jari menggunakan pensil di layar sentuh ponsel", "Sistem pendeteksi kedipan mata untuk mematikkan layar smartphone secara otomatis saat pengguna tertidur"], correct: 0, hint: "Mengapa aplikasi bank di ponsel tidak pernah mengirim foto wajah atau sidik jari Anda ke server bank? Karena verifikasi 100% dilakukan di dalam chip aman ponsel Anda sendiri.", explanation: "Data biometrik (sidik jari/wajah) adalah rahasia permanen yang tidak bisa diganti jika bocor. Oleh karena itu, Android (BiometricPrompt) dan iOS (LocalAuthentication) memproses pencocokan biometrik sepenuhnya di dalam perangkat keras terisolasi (Trusted Execution Environment / Secure Enclave). Aplikasi hanya menerima jawaban boolean `TRUE` (cocok) atau `FALSE` (gagal) serta token kunci kriptografi yang terbuka." },
            { id: "mobile-21", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'JNI' (Java Native Interface) dan NDK (Native Development Kit) di Android?", answers: ["Perangkat bantu yang memungkinkan kode Java/Kotlin di aplikasi Android untuk memanggil dan mengeksekusi pustaka (library) berkinerja tinggi yang ditulis dalam bahasa C atau C++ langsung pada level natif prosesor", "Alat untuk menerjemahkan aplikasi Android agar bisa berjalan di sistem operasi Windows 11 tanpa emulator", "Pustaka desain antarmuka grafis untuk membuat tombol beranimasi 3D pada layar sentuh smartphone", "Sistem penambalan keamanan kernel Linux secara remote tanpa perlu merestart smartphone pengguna"], correct: 0, hint: "Mengapa game 3D kelas berat seperti PUBG Mobile atau pemroses video ffmpeg di Android ditulis dengan C++, bukan Kotlin? Karena mereka membutuhkan performa mentah C++ lewat NDK.", explanation: "Meskipun Kotlin/Java sangat nyaman, mereka berjalan di atas mesin virtual (ART - Android Runtime) yang memiliki sedikit overhead. Untuk pemrosesan sinyal digital, pemrosesan citra kamera real-time, fisika game 3D, atau enkripsi kriptografi tingkat tinggi, developer menggunakan NDK dan mengaitkannya ke Kotlin melalui jembatan JNI." },
            { id: "mobile-22", category: "mobile", difficulty: "medium", question: "Apakah yang dimaksud dengan 'App Store Optimization' (ASO)?", answers: ["Proses mengoptimalkan judul aplikasi, kata kunci, deskripsi, ikon, tangkapan layar (screenshots), serta ulasan (ratings) di Google Play Store dan Apple App Store guna meningkatkan visibilitas pencarian dan rasio pengunduhan organik", "Metode mengompresi ukuran file aplikasi agar di bawah 10 MB sebelum diunggah ke toko aplikasi", "Proses membayar biaya pendaftaran akun developer sebesar $25 ke Google dan $99 ke Apple setiap tahun", "Teknik mempercepat waktu muat aplikasi di peramban web agar setara dengan kecepatan aplikasi toko"], correct: 0, hint: "SEO (Search Engine Optimization) versi toko aplikasi mobile: bagaimana agar aplikasi Anda muncul di nomor 1 saat orang mengetik kata kunci di Play Store.", explanation: "Sebagus apa pun aplikasi Anda, jika tidak ditemukan oleh pengguna, aplikasi tersebut akan mati. ASO adalah ilmu pemasaran teknis yang menggabungkan riset kata kunci, A/B testing desain ikon dan screenshot promosi, serta manajemen ulasan bintang lima untuk meningkatkan rasio konversi (Conversion Rate) dari pengunjung halaman toko menjadi penginstal aplikasi." },
            { id: "mobile-23", category: "mobile", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Responsive / Adaptive Layout' di aplikasi mobile (misal menggunakan ConstraintLayout atau Flexbox)?", answers: ["Desain antarmuka yang secara fleksibel menyesuaikan ukuran, posisi, dan tata letak elemen-elemen UI agar terlihat proporsional dan rapi di berbagai ukuran layar, rasio aspek, maupun orientasi (potret/lansekap) dari smartphone kecil hingga tablet lipat", "Desain antarmuka yang otomatis mengubah warna tema menjadi merah saat baterai smartphone di bawah 15%", "Aplikasi yang merespons dengan mengeluarkan suara bip setiap kali layar disentuh oleh pengguna", "Tata letak tombol yang hanya bisa diklik menggunakan dua jari secara bersamaan pada layar ponsel"], correct: 0, hint: "Satu desain antarmuka yang tampil cantik di ponsel mini 4 inci, smartphone lipat layar ganda, hingga tablet layar lebar 12 inci.", explanation: "Ekosistem Android memiliki ribuan variasi ukuran layar dan kepadatan piksel (ldpi hingga xxxhdpi). Dengan `ConstraintLayout` (Android) atau `Flexbox` (React Native/Flutter), developer menggunakan aturan relasional spasial ('tombol A selalu 16dp di bawah teks B dan berada tepat di tengah layar') alih-alih koordinat piksel mati yang kaku." },
            { id: "mobile-24", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Coroutines' (Kotlin) atau 'Async/Await' (Swift/JS) dalam pemrograman asinkron mobile?", answers: ["Mekanisme penulisan kode asinkron non-blocking yang terlihat sederhana seperti kode sekuensial biasa (menggunakan konsep suspend function/lightweight threads), menghindari kerumitan 'Callback Hell' saat memproses I/O jaringan atau database", "Mesin pemproses data ganda yang mengharuskan smartphone memiliki minimal 8 inti (octa-core) prosesor", "Metode menghapus riwayat panggilan telepon dan pesan teks secara asinkron di latar belakang ponsel", "Algoritma kompresi audio yang memperkecil ukuran file rekaman suara telepon hingga 50% di ponsel"], correct: 0, hint: "Cara modern mengeksekusi tugas berat di latar belakang tanpa memblokir UI Thread dan tanpa menulis ratusan baris kode callback yang bersarang sampai menjorok ke kanan layar.", explanation: "Sebelum Coroutines/Async-Await, developer terjebak dalam Callback Hell (`api.getUser(id, new Callback() { onSuccess(user) { api.getOrders(user, new Callback() { ... }) } })`). Coroutines di Kotlin menggunakan `suspend function` yang menunda eksekusi tanpa memblokir thread sistem operasi yang mahal, membuat kode asynchronous sebersih dan semudah dibaca seperti kode synchronous biasa." },
            { id: "mobile-25", category: "mobile", difficulty: "medium", question: "Apakah fungsi dari 'Crashlytics' (bagian dari Firebase / Google Cloud) pada pemeliharaan aplikasi mobile?", answers: ["Layanan pemantau dan pelapor kerusakan aplikasi (crash reporting) secara real-time yang mengumpulkan log stack trace detail dari perangkat pengguna saat aplikasi hang atau tertutup paksa, membantu developer melacak dan memperbaikinya dengan cepat", "Program antivirus yang memblokir serangan peretas yang mencoba membuat aplikasi mobile menjadi rusak", "Alat untuk menguji ketahanan fisik layar smartphone dengan cara menjatuhkannya dari ketinggian tertentu", "Software untuk menghapus file sampah cache dari dalam memori ponsel agar tidak mengalami crash"], correct: 0, hint: "Perekam kotak hitam (Black Box) pesawat terbang versi aplikasi mobile: dia memberi tahu persis baris kode mana yang meledak saat aplikasi pengguna crash di ujung dunia.", explanation: "Ketika aplikasi Anda diinstal oleh 1 juta pengguna di ribuan jenis ponsel berbeda, crash pasti terjadi. Firebase Crashlytics secara otomatis mengelompokkan crash berdasarkan akar masalah (Exception/Stack Trace), menunjukkan jenis ponsel, versi OS, serta langkah-langkah pengguna (Breadcrumbs) sebelum crash terjadi, sehingga engineer bisa langsung menambal bug di rilis berikutnya." },
            { id: "mobile-26", category: "mobile", difficulty: "easy", question: "Apakah yang dimaksud dengan 'OTA Update' (Over-The-Air Update) pada aplikasi Cross-Platform (seperti CodePush)?", answers: ["Kemampuan untuk mengirimkan pembaruan kode JavaScript/Dart dan aset statis langsung ke ponsel pengguna melalui jaringan internet secara instan tanpa harus menunggu proses peninjauan (review) dan rilis ulang di Apple App Store atau Google Play Store", "Pembaruan sistem operasi Android atau iOS lengkap berukuran giga-byte yang dikirimkan oleh produsen ponsel", "Metode mengisi daya baterai smartphone secara nirkabel dari jarak jauh menggunakan gelombang radio udara", "Pengiriman pesan siaran darurat bencana alam dari pemerintah ke seluruh ponsel yang terhubung ke menara"], correct: 0, hint: "Memperbaiki bug typo atau error logika di aplikasi pengguna dalam 5 menit langsung lewat internet tanpa perlu lolos sensor App Store yang memakan waktu 2 hari.", explanation: "Karena aplikasi React Native/Cordova memisahkan wadah Native (Java/Swift) dari logika bisnis JavaScript, alat seperti Microsoft CodePush memungkinkan tim mengirimkan bundle JS baru langsung ke ponsel. Saat pengguna membuka aplikasi, bundle baru diunduh di background dan diterapkan seketika (selama tidak ada perubahan pada kode native C/Java)." },
            { id: "mobile-27", category: "mobile", difficulty: "hard", question: "Apakah perbedaan antara 'MVC' (Model-View-Controller), 'MVP' (Model-View-Presenter), dan 'MVVM' (Model-View-ViewModel) dalam arsitektur aplikasi mobile?", answers: ["Pada MVVM, ViewModel mengekspos aliran data reaktif (seperti LiveData/StateFlow) yang diamati (observed) secara otomatis oleh View, memisahkan logika presentasi secara tegas tanpa referensi langsung ke UI, jauh lebih rapi dan mudah diuji (testable) dibanding MVC/MVP lawas", "MVC untuk aplikasi Android, MVP untuk aplikasi iOS, sedangkan MVVM untuk aplikasi website di komputer", "MVC adalah bahasa pemrograman, MVP adalah database lokal, sedangkan MVVM adalah server cloud", "Ketiganya adalah tingkat kesulitan permainan game mobile dari tingkat mudah, sedang, hingga super sulit"], correct: 0, hint: "MVVM (Model-View-ViewModel) adalah standar arsitektur emas yang direkomendasikan Google dan Apple saat ini karena keajaiban 'Data Binding & Reactive Observables'.", explanation: "Pada MVC lawas di mobile, `Activity/ViewController` sering menjadi raksasa ribuan baris ('Massive View Controller') karena menanggung tugas UI dan logika sekaligus. MVVM memecah masalah ini: `ViewModel` menangani logika bisnis dan memegang status data (`StateFlow`), sementara `View` (Activity/Compose) hanya bertugas mendengarkan perubahan data tersebut dan menggambarnya ke layar." },
            { id: "mobile-28", category: "mobile", difficulty: "medium", question: "Apakah kegunaan dari 'Sensors API' (seperti Accelerometer, Gyroscope, Magnetometer, dan GPS) pada perangkat mobile?", answers: ["Antarmuka pemrograman yang memungkinkan aplikasi membaca data fisika dunia nyata dari perangkat keras sensor ponsel, seperti percepatan gerakan, orientasi rotasi 3D, arah mata angin magnetik, dan koordinat lokasi geografis bumi", "Alat untuk mendeteksi adanya kerusakan fisik pada layar kaca smartphone setelah terjatuh ke lantai", "Sistem pemindai suhu baterai untuk mematikan ponsel secara otomatis jika panas melampaui 50 derajat Celsius", "Metode menghitung jumlah denyut nadi pengguna melalui sensor sidik jari di tombol daya ponsel"], correct: 0, hint: "Teknologi yang memungkinkan ponsel memutar layar otomatis saat dimiringkan, mengukur langkah kaki jogging, atau memandu arah navigasi peta Google Maps.", explanation: "Smartphone adalah komputer genggam yang sarat dengan sensor fisika. `Accelerometer` mengukur percepatan linear (berguna untuk mendeteksi ponsel digoyangkan/shake atau langkah kaki). `Gyroscope` mengukur kecepatan rotasi 3D (sangat penting untuk game AR/VR dan kestabilan kamera). `Magnetometer` berfungsi sebagai kompas digital." },
            { id: "mobile-29", category: "mobile", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Sandbox Security Model' pada sistem operasi mobile (Android dan iOS)?", answers: ["Mekanisme isolasi keamanan di mana setiap aplikasi yang diinstal berjalan di ruang pribadi terpisah (dengan ID pengguna sistem tersendiri); aplikasi tidak dapat mengakses file, memori, atau data milik aplikasi lain tanpa izin eksplisit melalui mekanisme IPC atau content provider", "Aplikasi khusus anak-anak yang berisi permainan membangun kotak pasir virtual 3D di layar ponsel", "Kotak pelindung silikon tahan air yang dipasang pada bodi smartphone agar tidak rusak terkena benturan", "Mode khusus ponsel yang menonaktifkan seluruh aplikasi jaringan sosial saat jam tidur malam hari"], correct: 0, hint: "Mengapa aplikasi game kalkulator yang baru Anda unduh tidak bisa diam-diam membaca riwayat chat WhatsApp atau mencuri foto di galeri Anda tanpa izin khusus?", explanation: "Di sistem operasi PC lawas (seperti Windows 98/XP), satu aplikasi yang terinfeksi virus bisa membaca dan merusak seluruh file di harddisk. Di Android dan iOS, setiap aplikasi dikurung di dalam 'penjara sandbox' terisolasi. Aplikasi A tidak bisa membaca folder data aplikasi B. Jika butuh berbagi data, mereka wajib melewati saluran resmi sistem operasi yang diproteksi izin." },
            { id: "mobile-30", category: "mobile", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Dependency Injection' (DI) dengan framework seperti Dagger/Hilt (Android) atau Swinject (iOS)?", answers: ["Teknik arsitektur di mana pembuatan objek dependensi (seperti kelas jaringan API atau database) tidak dilakukan langsung di dalam kelas yang membutuhkannya, melainkan 'disuntikkan' (injected) dari luar oleh kontainer DI, membuat kode super modular dan mudah diganti dengan objek tiruan (Mock) saat pengujian unit", "Sistem menyuntikkan kode virus atau malware ke dalam aplikasi milik kompetitor di toko aplikasi", "Proses mengunduh pustaka eksternal secara otomatis menggunakan koneksi internet Wi-Fi saat instalasi", "Teknik menggabungkan dua file APK Android menjadi satu file biner tunggal agar berukuran lebih padat"], correct: 0, hint: "Mengapa membuat objek dengan `new Database()` langsung di dalam setiap kelas Activity adalah kebiasaan buruk yang menyulitkan Automated Unit Testing?", explanation: "Jika `ViewModel` Anda membuat `new NetworkClient()` secara langsung di dalam kodenya, Anda tidak mungkin bisa menguji `ViewModel` tersebut tanpa koneksi internet asli. Dengan Dependency Injection (Hilt/Dagger), `ViewModel` cukup meminta antarmuka `INetworkClient` di konstruktornya. Saat production, Hilt menyuntikkan `RealNetworkClient`; saat testing, Hilt menyuntikkan `MockNetworkClient` tiruan." },

            // Quantum Computing (1-9)
            { id: "quantum-1", category: "quantum", difficulty: "easy", question: "Apa unit informasi terkecil dalam komputer kuantum yang setara dengan bit pada komputer klasik?", answers: ["Qubit (Quantum Bit)", "Gigabit", "Megabyte", "Superbit"], correct: 0, hint: "Menggunakan prinsip fisika kuantum.", explanation: "Qubit (Quantum Bit) adalah unit dasar komputasi kuantum yang dapat merepresentasikan keadaan 0, 1, atau keduanya secara bersamaan (superposisi)." },
            { id: "quantum-2", category: "quantum", difficulty: "easy", question: "Fenomena kuantum apa yang memungkinkan qubit berada dalam keadaan 0 dan 1 secara bersamaan?", answers: ["Superposisi", "Entanglement (Keterikatan)", "Teleportasi", "Interferensi"], correct: 0, hint: "Berada di atas atau menumpuk satu sama lain.", explanation: "Superposisi kuantum memungkinkan qubit untuk memiliki nilai 0, 1, atau kombinasi linier keduanya secara bersamaan hingga dilakukan pengukuran." },
            { id: "quantum-3", category: "quantum", difficulty: "easy", question: "Mengapa komputer kuantum membutuhkan suhu yang sangat dingin mendekati nol mutlak untuk beroperasi?", answers: ["Untuk menjaga qubit tetap stabil dan mencegah gangguan lingkungan (dekoherensi)", "Agar listrik berjalan lebih lambat", "Untuk membekukan virus komputer", "Agar komponen fisiknya tidak meleleh"], correct: 0, hint: "Suhu panas menimbulkan getaran atomik yang merusak kondisi kuantum.", explanation: "Qubit sangat sensitif terhadap gangguan termal dan elektromagnetik lingkungan. Suhu mendekati nol mutlak (sekitar 15 milikelvin) meminimalkan kebisingan termal untuk mencegah dekoherensi (hilangnya sifat kuantum)." },
            { id: "quantum-4", category: "quantum", difficulty: "medium", question: "Apa yang terjadi ketika dua qubit mengalami 'quantum entanglement' (keterikatan kuantum)?", answers: ["Keadaan satu qubit secara instan memengaruhi keadaan qubit pasangannya, meskipun terpisah jarak jauh", "Kedua qubit saling bertabrakan dan hancur", "Qubit tersebut tidak bisa lagi menerima data", "Kecepatan komputasi turun drastis menjadi klasik"], correct: 0, hint: "Hubungan misterius yang disebut Einstein 'spooky action at a distance'.", explanation: "Keterikatan (entanglement) adalah hubungan kuantum di mana properti fisik dua partikel saling berkorelasi secara instan, tidak peduli seberapa jauh jarak pemisahnya." },
            { id: "quantum-5", category: "quantum", difficulty: "medium", question: "Apakah kegunaan utama dari Quantum Key Distribution (QKD)?", answers: ["Mengamankan jalur komunikasi menggunakan hukum fisika kuantum agar tidak bisa disadap", "Mempercepat transfer file multimedia di internet", "Membuat sandi password yang lebih panjang di database", "Menyandikan gambar ke dalam qubit untuk render grafis"], correct: 0, hint: "Berhubungan dengan keamanan kriptografi.", explanation: "QKD menggunakan prinsip mekanika kuantum untuk mendeteksi penyadapan pada kunci rahasia. Upaya intersepsi kunci akan merusak keadaan kuantum qubit secara otomatis, sehingga kebocoran langsung terdeteksi." },
            { id: "quantum-6", category: "quantum", difficulty: "medium", question: "Manakah di bawah ini yang merupakan algoritma kuantum terkenal untuk memfaktorkan bilangan bulat besar yang mengancam kriptografi RSA saat ini?", answers: ["Algoritma Shor", "Algoritma Grover", "Algoritma Dijkstra", "Algoritma A*"], correct: 0, hint: "Ditemukan oleh Peter Shor pada tahun 1994.", explanation: "Algoritma Shor adalah algoritma kuantum yang dapat memfaktorkan bilangan bulat besar dalam waktu polinomial, yang secara teoretis dapat memecahkan kriptografi kunci publik klasik seperti RSA." },
            { id: "quantum-7", category: "quantum", difficulty: "hard", question: "Apa perbedaan mendasar antara model gerbang kuantum (Gate-based Quantum Computing) dengan Quantum Annealing?", answers: ["Gate-based mengendalikan qubit individual dengan logika gerbang kuantum umum, sedangkan Quantum Annealing dirancang khusus untuk masalah optimasi", "Gate-based menggunakan silikon klasik, Quantum Annealing menggunakan laser helium", "Quantum Annealing lebih lambat dan tidak membutuhkan suhu dingin", "Gate-based hanya untuk simulasi kimia, Quantum Annealing untuk enkripsi data"], correct: 0, hint: "Satu bersifat serbaguna (universal), yang lain khusus untuk menemukan nilai minimum global dari fungsi matematika.", explanation: "Komputer kuantum berbasis gerbang menggunakan gerbang logika kuantum universal untuk komputasi umum. Quantum Annealing (seperti yang dibuat D-Wave) adalah mesin khusus untuk mencari solusi optimal global dalam pemodelan matematika optimasi." },
            { id: "quantum-8", category: "quantum", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Noisy Intermediate-Scale Quantum' (NISQ) era?", answers: ["Era komputer kuantum saat ini dengan jumlah qubit terbatas (50-beberapa ratus) dan belum memiliki error correction yang sempurna", "Suara bising kipas pendingin pada superkomputer kuantum", "Kondisi di mana internet kuantum belum dilindungi firewall", "Sinyal radio klasik yang mengganggu frekuensi gelombang qubit"], correct: 0, hint: "Istilah yang dibuat John Preskill untuk mendeskripsikan teknologi kuantum masa kini.", explanation: "Era NISQ adalah tahap perkembangan komputer kuantum saat ini di mana mesin memiliki 50 hingga beberapa ratus qubit, namun rentan terhadap derau (noise) lingkungan dan belum memiliki koreksi kesalahan kuantum penuh (FTQC)." },
            { id: "quantum-9", category: "quantum", difficulty: "hard", question: "Bagaimana strategi utama Kriptografi Pasca-Kuantum (Post-Quantum Cryptography) dalam mengamankan data masa depan?", answers: ["Menggunakan masalah matematika klasik baru yang sangat sulit dipecahkan oleh komputer klasik maupun komputer kuantum", "Mengganti semua jaringan serat optik menjadi satelit kuantum", "Menyimpan seluruh data sensitif dalam bentuk qubit di RAM", "Menonaktifkan semua sistem enkripsi digital di server publik"], correct: 0, hint: "Ini adalah enkripsi matematika berbasis perangkat lunak klasik yang aman dari ancaman kuantum.", explanation: "Kriptografi Pasca-Kuantum berfokus pada pengembangan algoritma kriptografi klasik (seperti berbasis lattice atau kode linear) yang berjalan di komputer biasa saat ini, namun tahan terhadap serangan pemecahan sandi dari komputer kuantum masa depan." },

            // Blockchain & Web3 (1-9)
            { id: "blockchain-1", category: "blockchain", difficulty: "easy", question: "Apa karakteristik utama dari blockchain yang membuatnya sangat aman dan sulit dimanipulasi?", answers: ["Data disimpan secara terdesentralisasi di banyak komputer dan dihubungkan secara kriptografis", "Semua data dienkripsi dengan password admin tunggal", "Hanya pemerintah yang memiliki otoritas mengedit data", "Setiap data otomatis terhapus setelah 30 hari"], correct: 0, hint: "Desentralisasi dan rantai blok kriptografis.", explanation: "Blockchain menyimpan catatan transaksi di ribuan komputer (node) secara terdesentralisasi, di mana setiap blok baru dikaitkan dengan blok sebelumnya menggunakan hash kriptografis sehingga modifikasi sejarah transaksi sangat sulit dilakukan." },
            { id: "blockchain-2", category: "blockchain", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Smart Contract' dalam jaringan blockchain?", answers: ["Program komputer yang berjalan otomatis ketika kondisi kontrak yang ditentukan dalam kode terpenuhi", "Perjanjian kertas yang ditandatangani secara digital oleh pengacara online", "Sertifikat keamanan SSL untuk transaksi jual beli di web", "Algoritma AI yang menegosiasikan harga barang di marketplace"], correct: 0, hint: "Kode adalah hukum (Code is Law) di blockchain.", explanation: "Smart contract adalah protokol transaksi atau kode program yang dieksekusi secara otomatis di atas blockchain tanpa memerlukan perantara pihak ketiga." },
            { id: "blockchain-3", category: "blockchain", difficulty: "easy", question: "Apa perbedaan mendasar antara Web2 dan Web3?", answers: ["Web2 berpusat pada platform terpusat milik raksasa teknologi, sedangkan Web3 berbasis desentralisasi dengan kepemilikan data di tangan pengguna", "Web2 hanya teks, sedangkan Web3 sudah mendukung video streaming", "Web2 berjalan di smartphone, sedangkan Web3 hanya berjalan di headset VR", "Web2 tidak memerlukan internet, sedangkan Web3 membutuhkan satelit khusus"], correct: 0, hint: "Kepemilikan (Read-Write vs Read-Write-Own).", explanation: "Web2 dicirikan oleh platform sosial terpusat yang memiliki data pengguna. Web3 menggunakan blockchain dan token untuk menciptakan web terdesentralisasi di mana pengguna memiliki kendali atas identitas dan data mereka sendiri." },
            { id: "blockchain-4", category: "blockchain", difficulty: "medium", question: "Dalam jaringan blockchain, apakah fungsi dari mekanisme konsensus seperti Proof of Work (PoW) atau Proof of Stake (PoS)?", answers: ["Menyepakati validitas transaksi dan urutan blok baru tanpa adanya otoritas terpusat", "Mempercepat rendering tampilan visual user interface dompet kripto", "Mengamankan password admin utama dari serangan social engineering", "Menghubungkan jaringan internet lokal ke server server global"], correct: 0, hint: "Kesepakatan bersama antar node di seluruh dunia.", explanation: "Mekanisme konsensus adalah algoritma yang memastikan semua node independen dalam jaringan blockchain menyepakati satu versi kebenaran yang sama mengenai buku besar transaksi." },
            { id: "blockchain-5", category: "blockchain", difficulty: "medium", question: "Mengapa Ethereum sering disebut sebagai komputer dunia (World Computer) generasi kedua, berbeda dari Bitcoin?", answers: ["Karena Ethereum mendukung Turing-complete smart contracts yang memungkinkan jalannya aplikasi terdesentralisasi (dApps)", "Ethereum memiliki server fisik terbesar di dunia yang terletak di kutub utara", "Ethereum adalah satu-satunya mata uang kripto yang diakui PBB", "Ethereum menggunakan listrik yang jauh lebih sedikit sejak awal dibuat"], correct: 0, hint: "Ethereum dirancang bukan sekadar untuk transfer nilai, tapi sebagai platform aplikasi.", explanation: "Ethereum menambahkan lapisan logika pemrograman (Ethereum Virtual Machine) yang memungkinkan developer menulis dan mengeksekusi aplikasi terdesentralisasi (dApps) dan smart contracts yang rumit di atas blockchain-nya." },
            { id: "blockchain-6", category: "blockchain", difficulty: "medium", question: "Apakah yang dimaksud dengan DApp (Decentralized Application)?", answers: ["Aplikasi yang berjalan di atas sistem jaringan peer-to-peer terdesentralisasi seperti blockchain", "Aplikasi smartphone yang tidak memerlukan memori RAM untuk berjalan", "Software desain grafis yang bisa digunakan tanpa lisensi", "Situs web yang dibuat tanpa menggunakan file HTML atau CSS"], correct: 0, hint: "DApp menggunakan smart contract di backend-nya.", explanation: "dApps adalah aplikasi yang backend-nya dijalankan di jaringan terdesentralisasi (seperti blockchain Ethereum), bukan di server cloud terpusat seperti AWS atau Google Cloud." },
            { id: "blockchain-7", category: "blockchain", difficulty: "hard", question: "Apakah yang dimaksud dengan teknologi scaling Layer 2 (seperti Rollups) pada blockchain, dan masalah apa yang dipecahkannya?", answers: ["Memproses transaksi di luar rantai utama (off-chain) lalu menulis buktinya ke Layer 1; memecahkan masalah biaya gas tinggi dan kecepatan transaksi lambat", "Sistem keamanan dengan menumpuk dua firewall di server cloud database", "Metode pembagian database relasional secara horizontal untuk server lokal", "Jaringan satelit cadangan untuk mengirim data transaksi saat jaringan kabel putus"], correct: 0, hint: "Skalabilitas blockchain tanpa mengorbankan desentralisasi rantai dasar.", explanation: "Solusi Layer 2 (seperti Optimistic Rollups atau ZK-Rollups) memproses ribuan transaksi per detik di luar blockchain utama (Layer 1) secara efisien, lalu menggabungkannya ke dalam satu bukti transaksi yang dikirim ke Layer 1 untuk menghemat biaya gas dan waktu konfirmasi." },
            { id: "blockchain-8", category: "blockchain", difficulty: "hard", question: "Bagaimana cara kerja Zero-Knowledge Proofs (ZKP) dalam menjaga privasi transaksi Web3?", answers: ["Memungkinkan satu pihak membuktikan kepada pihak lain bahwa suatu pernyataan benar tanpa membocorkan informasi spesifik tentang pernyataan itu", "Menghapus riwayat transaksi secara acak setiap beberapa jam sekali", "Mengamankan server dompet digital dengan menyembunyikan alamat IP asli", "Mengubah nama akun pengguna menjadi karakter kosong di basis data"], correct: 0, hint: "Membuktikan kebenaran tanpa membagikan rahasia di baliknya.", explanation: "ZKP adalah metode kriptografi di mana 'Prover' dapat meyakinkan 'Verifier' bahwa mereka mengetahui suatu rahasia (seperti data transaksi atau password) tanpa perlu mengungkapkan data rahasia itu sendiri." },
            { id: "blockchain-9", category: "blockchain", difficulty: "hard", question: "Apakah risiko terbesar dari '51% Attack' pada jaringan blockchain berbasis konsensus Proof of Work?", answers: ["Penyerang dapat mengontrol mayoritas hashrate jaringan untuk membalikkan transaksi mereka sendiri (double spending) dan memblokir transaksi baru", "Penyerang dapat memodifikasi batas suplai maksimum koin yang sudah terkunci di kode dasar", "Penyerang dapat mencuri kunci privat (private key) dari dompet semua pengguna secara instan", "Server fisik node di seluruh dunia akan mengalami kerusakan hardware permanen"], correct: 0, hint: "Mengendalikan separuh lebih daya komputasi penambangan.", explanation: "Dengan memiliki lebih dari 50% daya komputasi (hashrate) jaringan PoW, penyerang dapat memodifikasi sejarah transaksi baru secara sepihak untuk melakukan pengeluaran ganda (double-spend) dan menyensor transaksi pengguna lain." },

            // Bio-Tech & Rekayasa Genetika (1-9)
            { id: "biotech-1", category: "biotech", difficulty: "easy", question: "Apa itu CRISPR-Cas9 yang sangat revolusioner dalam biologi modern?", answers: ["Alat atau teknologi pengeditan genom yang dapat memotong DNA dengan presisi tinggi", "Jenis vaksin baru untuk mencegah virus flu burung", "Software komputer untuk mendesain protein secara 3D", "Layanan cloud penyimpanan data kesehatan pasien"], correct: 0, hint: "Gunting molekuler DNA.", explanation: "CRISPR-Cas9 bertindak sebagai 'gunting molekuler' yang memungkinkan para ilmuwan memotong dan memodifikasi urutan DNA pada organisme hidup dengan tingkat akurasi dan kemudahan yang belum pernah ada sebelumnya." },
            { id: "biotech-2", category: "biotech", difficulty: "easy", question: "Apakah fungsi utama dari molekul DNA dalam makhluk hidup?", answers: ["Menyimpan informasi genetik dan instruksi untuk perkembangan dan fungsi tubuh", "Menghasilkan energi panas instan di dalam sel", "Mengirimkan sinyal listrik langsung ke otak", "Membasmi bakteri berbahaya yang masuk ke darah"], correct: 0, hint: "Peta cetak biru biologis.", explanation: "DNA (Deoxyribonucleic Acid) adalah materi genetik yang membawa semua instruksi instruktif yang diwariskan dari orang tua untuk pertumbuhan, perkembangan, dan fungsi seluruh makhluk hidup." },
            { id: "biotech-3", category: "biotech", difficulty: "easy", question: "Apa yang dimaksud dengan klonase (cloning) pada makhluk hidup?", answers: ["Proses menghasilkan organisme individu dengan kode genetik yang identik secara genetik dengan sel induknya", "Menyuntikkan gen tanaman ke dalam tubuh hewan", "Mempercepat pembelahan sel menggunakan terapi radiasi laser", "Mengubah golongan darah pasien secara buatan di laboratorium"], correct: 0, hint: "Duplikasi genetik identik (seperti domba Dolly).", explanation: "Kloning menghasilkan salinan genetik yang persis sama dari suatu molekul, sel, jaringan, atau organisme utuh tanpa melalui reproduksi seksual." },
            { id: "biotech-4", category: "biotech", difficulty: "medium", question: "Bagaimana konsep kerja dari DNA Computing (Komputer DNA) yang sedang diteliti untuk masa depan?", answers: ["Menggunakan molekul DNA, bio-kimia, dan biologi molekuler untuk melakukan perhitungan komputasi paralel besar", "Menghubungkan kabel komputer klasik ke sel saraf tumbuhan", "Menginstal sistem operasi Linux di dalam sel darah merah manusia", "Membuat memori flash drive dari bahan baku kolesterol"], correct: 0, hint: "Memanfaatkan kemampuan DNA menyimpan informasi dalam basa nitrogen (A, T, C, G).", explanation: "Komputer DNA menggunakan biologi molekuler daripada silikon. Informasi dikodekan dalam urutan basa nitrogen DNA, dan reaksi kimia enzimatis digunakan untuk melakukan kalkulasi secara paralel dalam skala mikroskopis." },
            { id: "biotech-5", category: "biotech", difficulty: "medium", question: "Apakah kegunaan utama dari teknologi terapi gen (Gene Therapy)?", answers: ["Mengobati penyakit dengan memasukkan, mengubah, atau memperbaiki gen yang rusak di dalam sel pasien", "Mengubah penampilan fisik seseorang sesuai keinginan estetika mereka", "Meningkatkan daya tahan tubuh menggunakan obat-obatan kimia sintetis", "Memperbaiki sel saraf otak yang rusak menggunakan chip mikroelektroda"], correct: 0, hint: "Mengoreksi langsung akar penyebab penyakit genetik di DNA sel.", explanation: "Terapi gen menargetkan materi genetik sel hidup untuk mengobati penyakit bawaan lahir atau kelainan genetik dengan mengganti gen abnormal dengan gen sehat fungsional." },
            { id: "biotech-6", category: "biotech", difficulty: "medium", question: "Apakah yang dimaksud dengan bio-sensor dalam bioteknologi modern?", answers: ["Perangkat analitis yang menggabungkan elemen biologis dengan transduser untuk mendeteksi zat kimia tertentu", "Alat perekam detak jantung digital yang dipasang di jam tangan pintar", "Kamera mikroskopis untuk melihat bakteri secara real-time di layar monitor", "Sistem keamanan sidik jari berbasis pemindaian sel kulit mati"], correct: 0, hint: "Menggunakan antibodi, enzim, atau DNA untuk mengukur kadar zat kimia.", explanation: "Bio-sensor mendeteksi target kimiawi (seperti glukosa atau polutan) menggunakan reseptor biologis sensitif, lalu mengubah interaksi tersebut menjadi sinyal elektrik yang mudah dibaca." },
            { id: "biotech-7", category: "biotech", difficulty: "hard", question: "Apakah tujuan dari teknik 'Gene Drive' yang dikembangkan menggunakan CRISPR dan risiko ekologis apa yang dimilikinya?", answers: ["Memaksa warisan gen tertentu menyebar ke 100% keturunan populasi liar; risikonya adalah kepunahan spesies yang tidak disengaja di alam", "Mempercepat pertumbuhan tanaman pertanian di laboratorium; risikonya adalah polusi tanah", "Mengubah sel kulit menjadi sel induk serbaguna; risikonya adalah memicu kanker", "Membuat antibodi buatan di pabrik obat; risikonya adalah biaya produksi yang terlalu tinggi"], correct: 0, hint: "Mengubah hukum pewarisan Mendel secara permanen di alam bebas.", explanation: "Gene drive memodifikasi DNA organisme agar gen tertentu diwariskan ke hampir seluruh keturunannya, sangat potensial untuk membasmi nyamuk pembawa malaria, tetapi berisiko merusak ekosistem global jika menyebar di luar kendali." },
            { id: "biotech-8", category: "biotech", difficulty: "hard", question: "Dalam bidang biologi sintesis, apakah yang dimaksud dengan 'Xenobiology'?", answers: ["Studi tentang organisme yang memiliki bentuk kehidupan atau kode genetik alternatif yang tidak ditemukan di alam (seperti asam nukleat buatan XNA)", "Studi tentang virus purba yang membeku di dalam es kutub utara", "Teknologi pencangkokan organ tubuh hewan ke dalam tubuh manusia", "Penelitian tentang kehidupan seluler mikroorganisme di luar angkasa"], correct: 0, hint: "Xeno berarti asing/buatan. DNA/RNA memiliki alternatif bernama XNA.", explanation: "Xenobiologi berfokus pada perancangan bentuk kehidupan dengan biokimia yang tidak standar, misalnya menggunakan asam nukleat buatan (Xenonucleic Acid / XNA) atau kode genetik dengan asam amino yang tidak ada secara alami di bumi." },
            { id: "biotech-9", category: "biotech", difficulty: "hard", question: "Bagaimana cara kerja teknologi Bioprinting 3D dalam memproduksi jaringan atau organ tubuh buatan?", answers: ["Mencetak bahan hydrogel yang dicampur sel hidup (bio-ink) lapis demi lapis untuk membentuk struktur organ 3D fungsional", "Membuat replika plastik organ tubuh pasien untuk latihan bedah dokter", "Menggunakan laser logam untuk mencetak implan tulang titanium", "Merekam struktur organ tubuh pasien menggunakan sensor ultrasonik 3D"], correct: 0, hint: "Mencetak sel hidup fungsional, bukan cetakan plastik mati.", explanation: "Bioprinting 3D menggunakan printer khusus dengan bio-tinta (bio-ink) yang kaya akan sel hidup untuk menyusun struktur jaringan biologis lapis demi lapis, bertujuan menghasilkan organ transplantasi fungsional di masa depan." },

            // Teknologi Otonom & Dirgantara (1-9)
            { id: "futuretech-1", category: "futuretech", difficulty: "easy", question: "Apa tantangan terbesar yang dihadapi dalam mengembangkan mobil otonom (Self-Driving Cars) tingkat tinggi (Level 5)?", answers: ["Kemampuan sistem AI mengambil keputusan cepat di tengah lalu lintas liar dan cuaca buruk ekstrem", "Daya tahan baterai mobil yang terlalu cepat habis", "Menemukan stasiun pengisian daya listrik di jalan pedesaan", "Mengubah ban mobil agar tidak bisa bocor saat menabrak paku"], correct: 0, hint: "Keputusan kemudi di lingkungan dinamis tanpa campur tangan manusia sama sekali.", explanation: "Mobil Level 5 harus mampu mengemudi sendiri secara penuh dalam segala kondisi. AI harus memproses data Lidar/kamera secara real-time dan mengatasi skenario lalu lintas yang kompleks, tidak terduga, dan ekstrem." },
            { id: "futuretech-2", category: "futuretech", difficulty: "easy", question: "Mengapa roket reusable (seperti Falcon 9 dari SpaceX) sangat mengubah industri eksplorasi luar angkasa?", answers: ["Menurunkan biaya peluncuran ke luar angkasa secara drastis dengan menggunakan kembali pendorong roket utama", "Membuat roket berjalan lebih cepat dari kecepatan cahaya di luar atmosfer", "Menggunakan bahan bakar air biasa sehingga ramah lingkungan", "Mampu membawa ribuan penumpang ke bulan dalam satu kali perjalanan"], correct: 0, hint: "Efisiensi biaya dengan tidak membuang roket setelah sekali pakai.", explanation: "Secara historis, roket dibuang setelah satu kali peluncuran. Dengan mendaratkan kembali dan menggunakan kembali booster roket utama, biaya misi luar angkasa berkurang hingga puluhan juta dolar." },
            { id: "futuretech-3", category: "futuretech", difficulty: "easy", question: "Apa kegunaan utama dari teknologi Internet of Things (IoT) pada Smart City?", answers: ["Menghubungkan sensor-sensor kota secara real-time untuk memantau lalu lintas, polusi, sampah, dan energi secara efisien", "Membuat koneksi Wi-Fi publik gratis berkecepatan tinggi bagi semua warga", "Mengganti semua jalan aspal kota menjadi panel surya kaca", "Menghapus kebutuhan akan kantor polisi fisik dengan drone patroli"], correct: 0, hint: "Sensor yang saling terhubung dan mengumpulkan data untuk manajemen kota otomatis.", explanation: "Smart City memanfaatkan jaringan sensor IoT untuk mengumpulkan data infrastruktur sipil, memungkinkan pengelolaan lampu jalan otomatis, pemantauan banjir, manajemen parkir pintar, dan efisiensi energi." },
            { id: "futuretech-4", category: "futuretech", difficulty: "medium", question: "Apakah perbedaan mendasar antara Fusi Nuklir (Nuclear Fusion) dan Fisi Nuklir (Nuclear Fission)?", answers: ["Fusi menggabungkan atom ringan untuk menghasilkan energi melimpah minim limbah, sedangkan Fisi membelah atom berat yang menghasilkan limbah radioaktif", "Fusi adalah reaksi nuklir di bumi, Fisi adalah reaksi nuklir di matahari", "Fusi menggunakan uranium-235, sedangkan Fisi menggunakan air laut biasa", "Fusi menghasilkan bom atom, Fisi menghasilkan reaktor pembangkit listrik saja"], correct: 0, hint: "Menggabungkan vs Membelah. Reaksi matahari adalah contoh fusi.", explanation: "Fusi nuklir (menggabungkan isotop hidrogen seperti deuterium dan tritium) menghasilkan energi jauh lebih besar tanpa menghasilkan limbah radioaktif berumur panjang seperti pada fisi nuklir (pembelahan atom berat seperti uranium)." },
            { id: "futuretech-5", category: "futuretech", difficulty: "medium", question: "Bagaimana cara kerja teknologi LiDAR yang sangat krusial bagi navigasi mobil otonom dan drone pemetaan?", answers: ["Memancarkan denyut laser ke lingkungan dan mengukur waktu pantulan kembali untuk membuat peta 3D akurat", "Menggunakan gelombang suara frekuensi rendah untuk mendeteksi logam di dalam tanah", "Menerima sinyal GPS satelit secara terus-menerus untuk melacak koordinat", "Memotret lingkungan secara bertahap dan mendeteksi warna piksel gambar"], correct: 0, hint: "Deteksi jarak menggunakan cahaya laser (Light Detection and Ranging).", explanation: "LiDAR mengirimkan ribuan pulsa laser per detik dan menghitung seberapa cepat cahaya memantul kembali dari objek sekitar, menciptakan peta titik 3D (point cloud) resolusi tinggi dari lingkungan sekitar." },
            { id: "futuretech-6", category: "futuretech", difficulty: "medium", question: "Apakah tujuan dari proyek konstelasi satelit orbit rendah (Low Earth Orbit / LEO) seperti Starlink?", answers: ["Menyediakan akses internet pita lebar (broadband) berlatensi rendah ke seluruh penjuru bumi secara global", "Memotret permukaan bumi dengan detail mikroskopis untuk spionase militer", "Membangun pangkalan militer luar angkasa untuk menangkal ancaman asteroid", "Mengarahkan energi matahari langsung ke bumi sebagai pembangkit listrik alternatif"], correct: 0, hint: "Konektivitas global melalui satelit jarak dekat.", explanation: "Satelit LEO mengorbit pada ketinggian 500-1200 km (jauh lebih dekat dibanding satelit geostasioner tradisional pada 35.000 km), meminimalkan latensi sinyal internet sehingga cocok untuk komunikasi real-time di seluruh dunia." },
            { id: "futuretech-7", category: "futuretech", difficulty: "hard", question: "Apakah yang dimaksud dengan BCI (Brain-Computer Interface) non-invasif dibandingkan dengan invasif (seperti Neuralink)?", answers: ["Non-invasif membaca sinyal otak dari permukaan kulit kepala (seperti EEG), sedangkan invasif menanamkan elektroda langsung di dalam jaringan otak", "Non-invasif tidak memerlukan koneksi bluetooth, sedangkan invasif wajib nirkabel", "Non-invasif mengendalikan komputer dengan mata, sedangkan invasif mengendalikan dengan otot tangan", "Non-invasif dipasang di leher pasien, sedangkan invasif dipasang di mata"], correct: 0, hint: "Tanpa bedah kepala vs memerlukan operasi bedah saraf.", explanation: "BCI non-invasif menangkap sinyal listrik otak melalui kulit kepala (seperti topi sensor EEG) tanpa bedah. BCI invasif (seperti chip Neuralink) memerlukan operasi bedah saraf untuk menanamkan sensor elektroda ultra-halus langsung ke dalam korteks serebral untuk mendapatkan resolusi sinyal yang jauh lebih tinggi." },
            { id: "futuretech-8", category: "futuretech", difficulty: "hard", question: "Apa fungsi dari teknologi 'Swarm Robotics' (Robotika Kawanan) yang terinspirasi dari alam?", answers: ["Mengoordinasikan ratusan robot kecil agar bekerja sama secara terdesentralisasi menyelesaikan tugas tanpa komando tunggal", "Membuat robot berbentuk serangga untuk membasmi hama tanaman pertanian", "Menggabungkan beberapa bagian robot menjadi satu robot raksasa fungsional", "Membuat robot militer dengan sistem pertahanan kebal peluru"], correct: 0, hint: "Koloni semut atau kawanan lebah.", explanation: "Swarm Robotics menggunakan prinsip kecerdasan kawanan (swarm intelligence). Robot-robot berinteraksi secara lokal satu sama lain dan dengan lingkungan mereka, menghasilkan perilaku kolektif global untuk menyelesaikan tugas-tugas kompleks secara mandiri dan tangguh." },
            { id: "futuretech-9", category: "futuretech", difficulty: "hard", question: "Dalam teknologi dirgantara futuristik, apakah tantangan utama pengembangan mesin Scramjet (Supersonic Combusting Ramjet) untuk penerbangan hipersonik?", answers: ["Menjaga kestabilan pembakaran bahan bakar di dalam aliran udara supersonic yang bergerak sangat cepat di dalam mesin", "Membuat mesin menyala saat pesawat masih berada di landasan pacu bandara", "Mengurangi kebisingan suara agar tidak memekakkan telinga penumpang sipil", "Menemukan bahan bakar gas helium cair yang murah dan aman digunakan"], correct: 0, hint: "Pembakaran dalam aliran udara yang melebihi kecepatan suara.", explanation: "Mesin Scramjet tidak memiliki bagian bergerak (kompresor) dan mengandalkan kompresi udara masuk pada kecepatan supersonik. Tantangannya adalah mencampur dan membakar bahan bakar secara stabil dalam aliran udara supersonik yang melintas dalam hitungan milidetik." }
          ];

if (typeof window !== "undefined" && window.ContentEngine) {
    window.ContentEngine.registerContent('quizzes', window.questionBank.map(q => ({
        id: q.id,
        question: q.question,
        options: q.answers || q.options,
        correctAnswer: q.correct !== undefined ? q.correct : q.correctAnswer,
        explanation: q.explanation || "",
        skills: [q.category],
        difficulty: q.difficulty || "easy",
        source: "quiz-question-bank",
        status: "published",
        version: 1
    })));
}
